INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(8, 'Kedarnath Dham opening 2026', NULL, NULL, NULL, '<h1 class=\"ql-align-center\"><strong><em>Kedarnath Dham Opening 2026 </em></strong></h1><h2 class=\"ql-align-center\">Opening Details (2026)</h2><ul><li class=\"ql-align-center\"><strong>Kedarnath Temple gates opened on:</strong> <strong>22 April 2026</strong></li><li class=\"ql-align-center\">Opening time: Around <strong>8:00 AM (auspicious muhurat)</strong></li><li class=\"ql-align-center\">Marks the beginning of the <strong>Char Dham Yatra</strong></li><li class=\"ql-align-center\">Temple remains open for about <strong>6 months (April/May → Oct/Nov)</strong> due to extreme winter</li><li class=\"ql-align-center\">Located in: <strong>Uttarakhand</strong></li></ul><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><br></p><h2 class=\"ql-align-center\">What is Kedarnath?</h2><ul><li class=\"ql-align-center\"><strong>Kedarnath Temple</strong> is a <strong>Hindu temple dedicated to Lord Shiva</strong></li><li class=\"ql-align-center\">Situated at an altitude of <strong>~3,583 meters</strong> in the <strong>Garhwal Himalayas</strong></li><li class=\"ql-align-center\">Located near the <strong>Mandakini River</strong></li><li class=\"ql-align-center\">One of the <strong>most sacred pilgrimage sites in India</strong></li></ul><h2 class=\"ql-align-center\"><br></h2><h2 class=\"ql-align-center\">Why is Kedarnath Famous?</h2><ul><li class=\"ql-align-center\">One of the <strong>holiest shrines of Lord Shiva</strong></li><li class=\"ql-align-center\">Surrounded by snow-clad Himalayan peaks</li><li class=\"ql-align-center\">Associated with <strong>Mahabharata legends (Pandavas)</strong></li><li class=\"ql-align-center\">Survived the <strong>2013 Uttarakhand floods</strong>, increasing its spiritual significance</li><li class=\"ql-align-center\">Part of both:</li><li class=\"ql-align-center\">Char Dham Yatra (Uttarakhand)</li><li class=\"ql-align-center\">Panch Kedar temples</li></ul><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><br></p><h2 class=\"ql-align-center\">Is Kedarnath a Jyotirlinga?</h2><p class=\"ql-align-center\">✔️ <strong>Yes, Kedarnath is one of the 12 Jyotirlingas of Lord Shiva</strong></p><ul><li class=\"ql-align-center\">Jyotirlinga = <strong>“pillar of divine light” (Shiva manifestation)</strong></li></ul><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><br></p><h3 class=\"ql-align-center\">Kedarnath Jyotirlinga</h3><ul><li class=\"ql-align-center\">Considered <strong>the most remote and highest Jyotirlinga</strong></li><li class=\"ql-align-center\">Symbolizes <strong>cosmic energy of Lord Shiva</strong></li></ul><h2 class=\"ql-align-center\"><br></h2><h2 class=\"ql-align-center\">List of 12 Jyotirlingas (Important for Exams)</h2><ol><li class=\"ql-align-center\">Somnath Temple – Gujarat</li><li class=\"ql-align-center\">Mallikarjuna Temple – Andhra Pradesh</li><li class=\"ql-align-center\">Mahakaleshwar Temple – Madhya Pradesh</li><li class=\"ql-align-center\">Omkareshwar Temple – Madhya Pradesh</li><li class=\"ql-align-center\">Kedarnath Temple – Uttarakhand</li><li class=\"ql-align-center\">Bhimashankar Temple – Maharashtra</li><li class=\"ql-align-center\">Kashi Vishwanath Temple – Uttar Pradesh</li><li class=\"ql-align-center\">Trimbakeshwar Temple – Maharashtra</li><li class=\"ql-align-center\">Vaidyanath Temple – Jharkhand</li><li class=\"ql-align-center\">Nageshwar Temple – Gujarat</li><li class=\"ql-align-center\">Ramanathaswamy Temple – Tamil Nadu</li><li class=\"ql-align-center\">Grishneshwar Temple – Maharashtra</li></ol><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><br></p><h2 class=\"ql-align-center\">History of Kedarnath Temple</h2><ul><li class=\"ql-align-center\">Believed to be built by the <strong>Pandavas</strong></li><li class=\"ql-align-center\">Later revived by <strong>Adi Shankaracharya</strong> in the 8th century</li><li class=\"ql-align-center\">Temple architecture:</li><li class=\"ql-align-center\">Made of <strong>massive stone slabs</strong></li><li class=\"ql-align-center\">Built without modern cement</li><li class=\"ql-align-center\">Behind the temple lies the <strong>samadhi of Adi Shankaracharya</strong></li></ul><h2 class=\"ql-align-center\"><br></h2><h2 class=\"ql-align-center\">Mythological Significance</h2><ul><li class=\"ql-align-center\">After the <strong>Mahabharata</strong>, Pandavas sought forgiveness from Lord Shiva</li><li class=\"ql-align-center\">Shiva disguised himself as a bull (Nandi) and hid</li><li class=\"ql-align-center\">Body parts appeared in different places → formed <strong>Panch Kedar temples</strong></li><li class=\"ql-align-center\">Kedarnath represents the <strong>hump of the bull</strong></li></ul><h2 class=\"ql-align-center\"><br></h2><h2 class=\"ql-align-center\">Seasonal Opening &amp; Closing</h2><ul><li class=\"ql-align-center\">Temple closes during winter due to heavy snowfall</li><li class=\"ql-align-center\">Idol is shifted to <strong>Omkareshwar Temple</strong> (winter seat)</li><li class=\"ql-align-center\">Reopens every year in April/May</li></ul>', NULL, ' National News', '', '', , 'active', 1, '2026-04-22 02:06:00', '2026-04-21 18:44:31', '2026-04-21 19:04:08');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(14, 'Panchayat Advancement Index (PAI) 2.0 launched ', '', '<h2><strong>Panchayat Advancement Index (PAI) 2.0 launched&nbsp;</strong></h2><p><br></p><ul><li>Launched by <strong>Ministry of Panchayati Raj</strong>.</li><li>Measures performance of 2.5 lakh <strong>Gram Panchayats</strong> in health, education, sanitation, governance and rural development.</li><li>Helps improve transparency, accountability and rural planning.</li><li>Based on <strong>Local Sustainable Development Goals (LSDGs)</strong>.</li></ul>', '', '<h2><strong>Panchayat Advancement Index (PAI) 2.0 </strong></h2><p><br></p><p><strong>Overview</strong></p><ul><li><strong>Panchayat Advancement Index (PAI) 2.0</strong> is a national-level performance assessment framework for <strong>Gram Panchayats</strong> in India.</li><li>It was launched by the <strong>Ministry of Panchayati Raj (MoPR)</strong>.</li><li>The index measures the overall development, governance quality, and service delivery performance of Panchayats.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is a Panchayat?</strong></p><ul><li>A <strong>Panchayat</strong> is a local self-government institution in rural India.</li><li><strong>Article 40</strong> of the Indian Constitution deals with <strong>Panchayats</strong>.</li><li>&nbsp;Added under <strong>Part IV</strong> of the Constitution.</li><li>&nbsp;Related to <strong>Directive Principles of State Policy (DPSP)</strong>.</li><li>&nbsp;Provides constitutional encouragement for rural local self-government.</li><li>It works under the <strong>Panchayati Raj System</strong> introduced through the:</li><li><strong>73rd Constitutional Amendment Act, 1992</strong> ⭐</li><li>Panchayats help in:</li><li>rural development</li><li>local administration</li><li>implementation of government schemes</li><li>public welfare activities</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Objective of PAI 2.0</strong></p><p>The main aims are:</p><ul><li>To measure development performance of Gram Panchayats.</li><li>To improve transparency and accountability in rural governance.</li><li>To promote data-based planning and policy making.</li><li>To identify strong and weak Panchayats.</li><li>To support achievement of <strong>Local Sustainable Development Goals (LSDGs)</strong>.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Areas Covered Under PAI 2.0</strong></p><p>The index evaluates Panchayats in important sectors such as:</p><ul><li>Health services</li><li>Education</li><li>Sanitation</li><li>Drinking water supply</li><li>Infrastructure</li><li>Women empowerment</li><li>Child welfare</li><li>Poverty reduction</li><li>Environmental sustainability</li><li>Digital governance</li><li>Social justice</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Local Sustainable Development Goals (LSDGs)</strong></p><ul><li>LSDGs are local-level versions of the <strong>United Nations Sustainable Development Goals (SDGs)</strong>.</li><li>Panchayats are assessed on how effectively they contribute to sustainable rural development.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of PAI 2.0 ⭐</strong></p><p><strong>For Government</strong></p><ul><li>Helps monitor Panchayat performance across India.</li><li>Assists in better fund allocation and policy planning.</li><li>Identifies governance gaps and development needs.</li></ul><p><strong>For Panchayats</strong></p><ul><li>Encourages healthy competition among Panchayats.</li><li>Motivates better implementation of welfare schemes.</li><li>Improves administrative efficiency.</li></ul><p><strong>For Citizens</strong></p><ul><li>Better public services in villages.</li><li>Improved accountability and transparency.</li><li>Faster rural development.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Panchayati Raj</li><li>Rural governance</li><li>Decentralization</li><li>Sustainable Development Goals (SDGs)</li></ul><p><strong>SSC / Railway / Banking / State PCS</strong></p><ul><li>Ministry-related questions</li><li>Constitutional Amendments</li><li>Rural development schemes</li><li>Governance indexes</li></ul><p class=\"ql-align-center\"><br></p><p><img src=\"data:image/png;base64,\"></p>', '', 'NATIONAL AFFAIRS, ENVIRONMENT, POLITY & GOVERNANCE, REPORTS & INDEXES', '', '', NULL, 'active', 1, '2026-04-30 19:49:00', '2026-05-09 17:57:29', '2026-05-09 19:04:49');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(15, 'Maharashtra AI Policy 2026 approved ', 'महाराष्ट्र एआई नीति 2026 को मंजूरी', '<h2><strong>Maharashtra AI Policy 2026 approved </strong></h2><p><br></p><ul><li>Aim: Develop Maharashtra as an AI hub.</li><li>Target investment: ₹10,000 crore.</li><li>Focus on AI startups, innovation, skill development and jobs.</li></ul>', '<h2><strong>महाराष्ट्र एआई नीति 2026 को मंजूरी</strong></h2><p><br></p><ul><li>उद्देश्य: महाराष्ट्र को एआई हब के रूप में विकसित करना।</li><li>लक्ष्य निवेश: ₹10,000 करोड़।</li><li>एआई स्टार्टअप, नवाचार, कौशल विकास और नौकरियों पर ध्यान दें।</li></ul>', '<p><br></p><p><br></p><p><br></p><p><br></p><h2><strong>Maharashtra AI Policy 2026 approved ⭐</strong></h2><p><br></p><ul><li>Aim: Develop Maharashtra as an AI hub.</li><li>Target investment: ₹10,000 crore.</li><li>Focus on AI startups, innovation, skill development and jobs.</li></ul><p><strong>Maharashtra AI Policy 2026 ⭐</strong></p><p><strong>Overview</strong></p><ul><li>The <strong>Maharashtra Government</strong> approved the <strong>AI Policy 2026</strong> to make the state a leading <strong>Artificial Intelligence (AI) hub</strong> in India.</li><li>The policy aims to attract around <strong>₹10,000 crore investment</strong> and generate employment opportunities in the technology sector.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Artificial Intelligence (AI)? ⭐</strong></p><ul><li><strong>Artificial Intelligence (AI)</strong> is a technology that enables machines and computers to:</li><li>think</li><li>learn</li><li>analyze data</li><li>solve problems</li><li>make decisions like humans</li></ul><p>Examples:</p><ul><li>Chatbots</li><li>Face recognition</li><li>Self-driving technology</li><li>Voice assistants like Siri/Alexa</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Father of Artificial Intelligence ⭐</strong></p><ul><li><strong>John McCarthy</strong> is known as the <strong>“Father of Artificial Intelligence.”</strong></li><li>He coined the term <strong>Artificial Intelligence</strong> in <strong>1956</strong>.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Aim of Maharashtra AI Policy 2026</strong></p><ul><li>To develop Maharashtra into a major <strong>AI hub</strong>.</li><li>To encourage:</li><li>AI startups</li><li>innovation</li><li>research</li><li>digital economy</li><li>skill development</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is an AI Hub? ⭐</strong></p><ul><li>An <strong>AI hub</strong> is a region where:</li><li>AI companies</li><li>startups</li><li>research centers</li><li>skilled workers</li><li>technology investment</li><li>are concentrated.</li></ul><p>It becomes a center for:</p><ul><li>innovation</li><li>job creation</li><li>advanced technology development</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Sectors Covered Under the Policy</strong></p><p>AI will be promoted in:</p><ul><li>Healthcare</li><li>Agriculture</li><li>Education</li><li>Governance</li><li>Manufacturing</li><li>Transport</li><li>Finance</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of AI Policy ⭐</strong></p><p><strong>For Common People</strong></p><ul><li>Faster government services</li><li>Better healthcare diagnosis</li><li>Smart farming support for farmers</li><li>Improved online education</li><li>Better traffic and transport management</li><li>More job opportunities in technology sector</li></ul><p><strong>For State Economy</strong></p><ul><li>Increase in investment</li><li>Growth of startups</li><li>Skill development</li><li>Digital transformation</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Merits of Artificial Intelligence ⭐</strong></p><ul><li>Saves time and cost</li><li>Improves efficiency</li><li>Reduces human error</li><li>Faster data analysis</li><li>Better public services</li><li>Helps in medical diagnosis and disaster prediction</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Demerits of Artificial Intelligence ⭐</strong></p><ul><li>Job loss in some sectors due to automation</li><li>Privacy and data security concerns</li><li>High implementation cost</li><li>Over-dependence on technology</li><li>Risk of misuse and cyber threats</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Science &amp; Technology</li><li>Digital governance</li><li>AI ethics</li></ul><p><strong>SSC / Banking / Railway / State Exams</strong></p><ul><li>AI full form</li><li>Father of AI</li><li>AI policy and investment amount</li><li>Technology-based governance&nbsp;</li></ul><p><img src=\"data:image/png;base64,\"></p>', '<p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><h2><strong>महाराष्ट्र एआई नीति 2026 को मंजूरी ⭐</strong></h2><p><br></p><ul><li>उद्देश्य: महाराष्ट्र को एआई हब के रूप में विकसित करना।</li><li>लक्ष्य निवेश: ₹10,000 करोड़।</li><li>एआई स्टार्टअप, नवाचार, कौशल विकास और नौकरियों पर ध्यान दें।</li></ul><p><strong>महाराष्ट्र एआई नीति 2026 ⭐</strong></p><p><strong>सिंहावलोकन</strong></p><ul><li><strong>महाराष्ट्र सरकार</strong>को मंजूरी दे दी<strong>एआई नीति 2026</strong>राज्य को अग्रणी बनाना है<strong>आर्टिफिशियल इंटेलिजेंस (एआई) हब</strong>भारत में.</li><li>नीति का उद्देश्य चारों ओर आकर्षित करना है<strong>₹10,000 करोड़ का निवेश</strong>और प्रौद्योगिकी क्षेत्र में रोजगार के अवसर पैदा करें।</li></ul><p class=\"ql-align-center\"><br></p><p><strong>आर्टिफिशियल इंटेलिजेंस (एआई) क्या है? ⭐</strong></p><ul><li><strong>कृत्रिम बुद्धिमत्ता (एआई)</strong>एक ऐसी तकनीक है जो मशीनों और कंप्यूटरों को सक्षम बनाती है:</li><li>सोचना</li><li>सीखना</li><li>डेटा का विश्लेषण करें</li><li>समस्याओं का समाधान</li><li>इंसानों की तरह निर्णय लें</li></ul><p>उदाहरण:</p><ul><li>चैटबॉट्स</li><li>चेहरा पहचान</li><li>सेल्फ-ड्राइविंग तकनीक</li><li>सिरी/एलेक्सा जैसे वॉयस असिस्टेंट</li></ul><p class=\"ql-align-center\"><br></p><p><strong>आर्टिफिशियल इंटेलिजेंस के जनक ⭐</strong></p><ul><li><strong>जॉन मैक्कार्थी</strong>के नाम से जाना जाता है<strong>\"आर्टिफिशियल इंटेलिजेंस के जनक।\"</strong></li><li>उन्होंने यह शब्द गढ़ा<strong>कृत्रिम होशियारी</strong>में<strong>1956</strong>.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>महाराष्ट्र एआई नीति 2026 का उद्देश्य</strong></p><ul><li>महाराष्ट्र को प्रमुख राज्य के रूप में विकसित करना है<strong>एआई हब</strong>.</li><li>उत्साहित करना:</li><li>एआई स्टार्टअप</li><li>नवाचार</li><li>अनुसंधान</li><li>डिजिटल अर्थव्यवस्था</li><li>कौशल विकास</li></ul><p class=\"ql-align-center\"><br></p><p><strong>AI हब क्या है? ⭐</strong></p><ul><li>एक<strong>एआई हब</strong>एक ऐसा क्षेत्र है जहां:</li><li>एआई कंपनियां</li><li>स्टार्टअप</li><li>अनुसंधान केंद्र</li><li>कुशल श्रमिक</li><li>प्रौद्योगिकी निवेश</li><li>केंद्रित हैं.</li></ul><p>यह इसके लिए एक केंद्र बन जाता है:</p><ul><li>नवाचार</li><li>रोजगार सृजन</li><li>उन्नत प्रौद्योगिकी विकास</li></ul><p class=\"ql-align-center\"><br></p><p><strong>नीति के अंतर्गत शामिल क्षेत्र</strong></p><p>AI को बढ़ावा दिया जाएगा:</p><ul><li>स्वास्थ्य देखभाल</li><li>कृषि</li><li>शिक्षा</li><li>शासन</li><li>उत्पादन</li><li>परिवहन</li><li>वित्त</li></ul><p class=\"ql-align-center\"><br></p><p><strong>एआई नीति के लाभ ⭐</strong></p><p><strong>आम लोगों के लिए</strong></p><ul><li>तेज़ सरकारी सेवाएँ</li><li>बेहतर स्वास्थ्य देखभाल निदान</li><li>किसानों के लिए स्मार्ट खेती सहायता</li><li>ऑनलाइन शिक्षा में सुधार</li><li>बेहतर यातायात एवं परिवहन प्रबंधन</li><li>प्रौद्योगिकी क्षेत्र में रोजगार के अधिक अवसर</li></ul><p><strong>राज्य की अर्थव्यवस्था के लिए</strong></p><ul><li>निवेश में वृद्धि</li><li>स्टार्टअप्स का विकास</li><li>कौशल विकास</li><li>डिजिटल परिवर्तन</li></ul><p class=\"ql-align-center\"><br></p><p><strong>आर्टिफिशियल इंटेलिजेंस के गुण ⭐</strong></p><ul><li>समय और लागत बचाता है</li><li>कार्यकुशलता में सुधार करता है</li><li>मानवीय त्रुटि को कम करता है</li><li>तेज़ डेटा विश्लेषण</li><li>बेहतर सार्वजनिक सेवाएँ</li><li>चिकित्सा निदान और आपदा भविष्यवाणी में मदद करता है</li></ul><p class=\"ql-align-center\"><br></p><p><strong>आर्टिफिशियल इंटेलिजेंस के अवगुण ⭐</strong></p><ul><li>स्वचालन के कारण कुछ क्षेत्रों में नौकरियाँ ख़त्म हो गईं</li><li>गोपनीयता और डेटा सुरक्षा संबंधी चिंताएँ</li><li>उच्च कार्यान्वयन लागत</li><li>प्रौद्योगिकी पर अत्यधिक निर्भरता</li><li>दुरुपयोग और साइबर खतरों का जोखिम</li></ul><p class=\"ql-align-center\"><br></p><p><strong>परीक्षा के लिए महत्व ⭐</strong></p><p><strong>यूपीएससी</strong></p><ul><li>विज्ञान प्रौद्योगिकी</li><li>डिजिटल शासन</li><li>एआई नैतिकता</li></ul><p><strong>एसएससी/बैंकिंग/रेलवे/राज्य परीक्षा</strong></p><ul><li>एआई का फुल फॉर्म</li><li>एआई के जनक</li><li>एआई नीति और निवेश राशि</li><li>प्रौद्योगिकी आधारित शासन</li></ul><p><img src=\"data:image/png;base64,\"></p>', 'NATIONAL AFFAIRS, SCIENCE & TECHNOLOGY, SCHEMES & GOVT. POLICIES', '', '', NULL, 'active', 1, '2026-04-30 19:59:00', '2026-05-09 18:03:40', '2026-05-12 20:37:24');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(16, 'EPFO launches E-PRAAPTI portal ', '', '<h2><strong>EPFO launches E-PRAAPTI portal </strong></h2><p><br></p><ul><li>Launched by <strong>EPFO</strong></li><li>Digital grievance redressal platform</li><li>Helps in complaint tracking</li><li>Improves transparency and faster services</li><li>Benefits EPFO subscribers and pensioners</li></ul>', '', '<h2><strong>EPFO launches E-PRAAPTI Portal </strong></h2><p><br></p><p><strong>What is EPFO? ⭐</strong></p><ul><li><strong>EPFO</strong> stands for <strong>Employees’ Provident Fund Organisation</strong>.</li><li>It is one of India’s largest social security organizations.</li><li>Works under the:</li><li><strong>Ministry of Labour &amp; Employment</strong></li><li>Government of India</li><li>EPFO manages:</li><li>Provident Fund (PF)</li><li>Pension Scheme</li><li>Insurance benefits for employees</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Provident Fund (PF)? ⭐</strong></p><p><strong>Introduction</strong></p><ul><li><strong>Provident Fund (PF)</strong> is a government-backed retirement savings scheme for salaried employees in India.</li><li>It helps employees save money regularly during their working years for:</li><li>retirement</li><li>emergencies</li><li>financial security</li><li>PF is mainly managed by the:</li><li><strong>Employees’ Provident Fund Organisation (EPFO)</strong>.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>How PF Works ⭐</strong></p><ul><li>Every month:</li><li>the <strong>employee</strong> contributes a part of salary</li><li>the <strong>employer</strong> also contributes an equal amount</li><li>This money is deposited into the employee’s PF account.</li><li>The amount earns:</li><li>annual interest fixed by the Government of India.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Employee Contribution</strong></p><ul><li>Usually:</li><li><strong>12% of Basic Salary + Dearness Allowance (DA)</strong> is deducted from employee salary.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Employer Contribution</strong></p><ul><li>Employer also contributes:</li><li>12%</li><li>Employer contribution is divided into:</li><li>EPF (Provident Fund)</li><li>EPS (Employee Pension Scheme)</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of Provident Fund ⭐</strong></p><p>PF is designed to provide:</p><ul><li>retirement savings</li><li>pension benefits</li><li>financial support during emergencies</li><li>long-term financial security</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of PF ⭐</strong></p><p><strong>1. Retirement Security</strong></p><ul><li>Helps employees build savings for old age.</li></ul><p><strong>2. Interest Earnings</strong></p><ul><li>PF deposits earn government-declared interest annually.</li></ul><p><strong>3. Tax Benefits</strong></p><ul><li>PF contributions and returns get tax benefits under income tax laws.</li></ul><p><strong>4. Emergency Withdrawal</strong></p><p>Employees can partially withdraw PF money for:</p><ul><li>medical treatment</li><li>education</li><li>marriage</li><li>home purchase</li><li>unemployment</li></ul><p><strong>5. Pension Benefits</strong></p><ul><li>Part of employer contribution goes to:</li><li>Employee Pension Scheme (EPS).</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Universal Account Number (UAN) ⭐</strong></p><ul><li>Every EPFO member gets a:</li><li><strong>UAN (Universal Account Number)</strong>.</li><li>It helps employees:</li><li>manage PF accounts online</li><li>transfer PF while changing jobs</li><li>check balance digitally</li></ul><p><br></p><p class=\"ql-align-center\"><br></p><p><strong>What is E-PRAAPTI Portal? ⭐</strong></p><ul><li><strong>E-PRAAPTI</strong> is a digital grievance redressal and monitoring portal launched by EPFO.</li><li>It helps members:</li><li>file complaints online</li><li>track grievance status</li><li>get faster resolution of PF-related issues</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why was E-PRAAPTI launched?</strong></p><p>The portal was launched to:</p><ul><li>improve transparency</li><li>reduce delays in complaint handling</li><li>digitize EPFO services</li><li>provide faster support to subscribers and pensioners</li><li>strengthen accountability in EPFO offices</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of E-PRAAPTI ⭐</strong></p><ul><li>Faster grievance resolution</li><li>Better monitoring system</li><li>Improved public service delivery</li><li>Digital governance and paperless functioning</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of E-PRAAPTI Portal ⭐</strong></p><p><strong>For Employees</strong></p><ul><li>Easy online complaint registration</li><li>Faster PF and pension issue resolution</li><li>Real-time tracking of complaints</li><li>Reduced need to visit EPFO offices</li></ul><p><strong>For EPFO Administration</strong></p><ul><li>Better monitoring of pending grievances</li><li>Improved efficiency</li><li>Increased transparency and accountability</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>Banking / SSC / Railway</strong></p><ul><li>Full form of EPFO</li><li>Ministry under which EPFO works</li><li>Social security schemes</li></ul><p><strong>UPSC</strong></p><ul><li>Labour welfare</li><li>Digital governance</li><li>Social security reforms&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p>', '', 'NATIONAL AFFAIRS, SCHEMES & GOVT. POLICIES', '', '', NULL, 'active', 1, '2026-05-01 07:04:00', '2026-05-09 18:07:29', '2026-05-09 18:55:11');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(17, 'Bengaluru Police launches AI multilingual helpline ', 'बेंगलुरु पुलिस ने एआई बहुभाषी हेल्पलाइन शुरू की', '<h2><strong>Bengaluru Police launches AI multilingual helpline</strong></h2><p><br></p><ul><li>Launched by <strong>Bengaluru Police</strong></li><li>AI-based citizen support service</li><li>Provides help in multiple languages</li><li>Improves public communication and complaint support</li><li>Uses Artificial Intelligence for faster response system</li></ul>', '<p>बेंगलुरु पुलिस ने AI बहुभाषी हेल्पलाइन लॉन्च की बेंगलुरु पुलिस द्वारा लॉन्च की गई AI आधारित नागरिक सहायता सेवा कई भाषाओं में मदद प्रदान करती है सार्वजनिक संचार और शिकायत समर्थन में सुधार करती है तेज प्रतिक्रिया प्रणाली के लिए आर्टिफिशियल इंटेलिजेंस का उपयोग करती है</p>', '<p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><h2><strong>Bengaluru Police launches AI Multilingual Helpline </strong></h2><p><br></p><p><strong>Overview</strong></p><ul><li><strong>Bengaluru Police</strong> launched an <strong>AI-based multilingual helpline</strong> to improve communication between police and citizens.</li><li>The helpline uses <strong>Artificial Intelligence (AI)</strong> to provide support in multiple languages.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Who launched it?</strong></p><ul><li>Launched by the:</li><li><strong>Bengaluru City Police</strong></li><li>Karnataka</li></ul><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;·&nbsp;Comes under the <strong>Ministry of Home Affairs (MHA)</strong> at the central level.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;·&nbsp;Implemented by <strong>Bengaluru City Police, Karnataka Government</strong>.</p><p class=\"ql-align-center\"><br></p><p><strong>Where is Bengaluru? ⭐</strong></p><ul><li><strong>Bengaluru</strong> (formerly Bangalore) is the capital city of:</li><li><strong>Karnataka</strong></li><li>Located in:</li><li><strong>Southern India</strong></li><li>Known as:</li><li><strong>“Silicon Valley of India”</strong> ⭐</li><li>Major IT and startup hub</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Geographical Importance of Bengaluru ⭐</strong></p><ul><li>Located on the:</li><li><strong>Deccan Plateau</strong></li><li>Famous for:</li><li>Information Technology (IT)</li><li>software industries</li><li>startups</li><li>research institutions</li><li>Headquarters of many tech companies and innovation centers.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Artificial Intelligence (AI)? ⭐</strong></p><ul><li><strong>Artificial Intelligence (AI)</strong> is a technology that enables machines and computers to:</li><li>think</li><li>learn</li><li>understand language</li><li>solve problems</li><li>make decisions like humans</li></ul><p>Examples:</p><ul><li>Chatbots</li><li>Voice assistants</li><li>Face recognition systems</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is an AI Multilingual Helpline? ⭐</strong></p><ul><li>It is a smart digital support system that:</li><li>communicates with people in different languages</li><li>answers queries automatically</li><li>helps register complaints</li><li>provides quick assistance</li></ul><p>The system uses:</p><ul><li>AI</li><li>speech recognition</li><li>language translation technology</li></ul><p class=\"ql-align-center\"><br></p><p><strong>How does it work? ⭐</strong></p><ol><li>Citizens call or message the helpline.</li><li>AI detects the language of the user.</li><li>The system responds in the same language.</li><li>Complaints and queries are processed digitally.</li><li>Police receive information quickly for action.</li></ol><p class=\"ql-align-center\"><br></p><p><strong>Benefits of AI Multilingual Helpline ⭐</strong></p><p><strong>For Citizens</strong></p><ul><li>Easier communication with police</li><li>Support in local languages</li><li>Faster complaint registration</li><li>24×7 digital assistance</li></ul><p><strong>For Police</strong></p><ul><li>Reduces workload</li><li>Faster response system</li><li>Better public interaction</li><li>Improved digital policing</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>AI in governance</li><li>Smart policing</li><li>Digital India initiatives</li></ul><p><strong>SSC / Banking / Railway / State Exams</strong></p><ul><li>Bengaluru location</li><li>Silicon Valley of India</li><li>AI applications&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p>', '<p>बेंगलुरु पुलिस ने एआई बहुभाषी हेल्पलाइन लॉन्च की अवलोकन बेंगलुरु पुलिस ने पुलिस और नागरिकों के बीच संचार को बेहतर बनाने के लिए एआई-आधारित बहुभाषी हेल्पलाइन शुरू की। हेल्पलाइन कई भाषाओं में सहायता प्रदान करने के लिए आर्टिफिशियल इंटेलिजेंस (एआई) का उपयोग करती है। इसे किसने लॉन्च किया? बेंगलुरु सिटी पुलिस द्वारा लॉन्च किया गया · कर्नाटक · केंद्रीय स्तर पर गृह मंत्रालय (एमएचए) के अंतर्गत आता है। · बेंगलुरु सिटी पुलिस, कर्नाटक सरकार द्वारा कार्यान्वित किया गया। बेंगलुरु कहां है? ⭐ बेंगलुरु (पूर्व में बेंगलुरु) कर्नाटक की राजधानी है: दक्षिणी भारत में स्थित है: \"भारत की सिलिकॉन वैली\" के रूप में जाना जाता है ⭐ प्रमुख आईटी और स्टार्टअप हब बेंगलुरु का भौगोलिक महत्व ⭐ स्थित है: डेक्कन पठार के लिए प्रसिद्ध: सूचना प्रौद्योगिकी (आईटी) सॉफ्टवेयर उद्योग स्टार्टअप अनुसंधान संस्थान कई तकनीकी कंपनियों और नवाचार केंद्रों के मुख्यालय। आर्टिफिशियल इंटेलिजेंस क्या है (एआई)? ⭐आर्टिफिशियल इंटेलिजेंस (एआई) एक ऐसी तकनीक है जो मशीनों और कंप्यूटरों को सोचने, भाषा समझने, समस्याओं को हल करने, इंसानों की तरह निर्णय लेने में सक्षम बनाती है। उदाहरण: चैटबॉट्स, वॉयस असिस्टेंट, फेस रिकग्निशन सिस्टम, एआई बहुभाषी हेल्पलाइन क्या है? ⭐यह एक स्मार्ट डिजिटल सपोर्ट सिस्टम है जो: विभिन्न भाषाओं में लोगों के साथ संचार करता है, प्रश्नों का स्वचालित रूप से उत्तर देता है, शिकायत दर्ज करने में मदद करता है, त्वरित सहायता प्रदान करता है। सिस्टम उपयोग करता है: AI भाषण पहचान भाषा अनुवाद तकनीक यह कैसे काम करती है? ⭐नागरिक हेल्पलाइन पर कॉल या संदेश भेजते हैं। एआई उपयोगकर्ता की भाषा का पता लगाता है। सिस्टम उसी भाषा में जवाब देता है। शिकायतों और प्रश्नों को डिजिटल रूप से संसाधित किया जाता है। पुलिस को कार्रवाई के लिए तुरंत जानकारी मिलती है। एआई बहुभाषी हेल्पलाइन के लाभ ⭐नागरिकों के लिए पुलिस के साथ आसान संचार, स्थानीय भाषाओं में सहायता, तेज शिकायत पंजीकरण 24×7 डिजिटल सहायता, पुलिस के लिए काम का बोझ कम, तेज प्रतिक्रिया प्रणाली, बेहतर सार्वजनिक संपर्क, बेहतर डिजिटल पुलिसिंगपरीक्षाओं के लिए महत्व ⭐शासन में यूपीएससीएआईस्मार्ट पुलिसिंगडिजिटल भारत पहलएसएससी/बैंकिंग/रेलवे/राज्य परीक्षाबेंगलुरु स्थानसिलिकवैली ऑफ इंडियाएआई अनुप्रयोगों पर</p>', 'NATIONAL AFFAIRS, SCIENCE & TECHNOLOGY', '', '', NULL, 'active', 1, '2026-04-30 14:38:00', '2026-05-09 18:10:31', '2026-05-12 18:34:16');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(18, 'BRICS Entrepreneurs Alliance expands MSME cooperation ', '', '<h2><strong>BRICS Entrepreneurs Alliance expands MSME cooperation</strong></h2><p><br></p><ul><li>Initiative by BRICS nations</li><li>Focus on MSME and startup ecosystem</li><li>Promotes trade and entrepreneurship</li><li>Encourages innovation and business partnerships</li><li>Strengthens economic cooperation among BRICS countries</li></ul>', '', '<h2><strong>BRICS Entrepreneurs Alliance expands MSME Cooperation </strong></h2><p><br></p><p><strong>What is BRICS? ⭐</strong></p><ul><li><strong>BRICS</strong> is a group of major emerging economies.</li><li>BRICS originally included:</li><li><strong>Brazil</strong></li><li><strong>Russia</strong></li><li><strong>India</strong></li><li><strong>China</strong></li><li><strong>South Africa</strong></li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Expansion of BRICS ⭐</strong></p><ul><li>BRICS has recently expanded with new member countries in global cooperation discussions.</li><li>The group focuses on:</li><li>economic growth</li><li>trade cooperation</li><li>development partnership</li><li>Global South representation</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is BRICS Entrepreneurs Alliance (BEA)? ⭐</strong></p><ul><li>A business and entrepreneurship platform under BRICS cooperation.</li><li>It promotes:</li><li>startups</li><li>MSMEs</li><li>innovation</li><li>investment</li><li>business networking among BRICS nations.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is MSME? ⭐</strong></p><ul><li><strong>MSME</strong> stands for:</li><li><strong>Micro, Small and Medium Enterprises</strong></li><li>MSMEs are small businesses that:</li><li>generate employment</li><li>support exports</li><li>strengthen economy</li><li>promote entrepreneurship</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Objective of BRICS Entrepreneurs Alliance ⭐</strong></p><ul><li>To strengthen:</li><li>MSME cooperation</li><li>startup ecosystem</li><li>innovation partnerships</li><li>trade relations among BRICS countries</li><li>Encourages:</li><li>technology sharing</li><li>investment opportunities</li><li>global market access for small businesses</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Indian Prime Minister in BRICS ⭐</strong></p><ul><li><strong>Narendra Modi</strong> represents India in BRICS summits and meetings.</li><li>India plays an important role in:</li><li>digital economy</li><li>startup ecosystem</li><li>Global South leadership</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Meetings &amp; Cooperation ⭐</strong></p><ul><li>BRICS leaders and business groups regularly hold:</li><li>summits</li><li>trade forums</li><li>entrepreneurship meetings</li><li>economic cooperation conferences</li></ul><p>Topics discussed:</p><ul><li>startup growth</li><li>digital economy</li><li>MSME financing</li><li>trade expansion</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Motto / Vision of BRICS Cooperation ⭐</strong></p><p>Main focus areas:</p><ul><li>economic cooperation</li><li>inclusive growth</li><li>innovation</li><li>sustainable development</li><li>stronger Global South partnership</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of BRICS MSME Cooperation ⭐</strong></p><p><strong>For Businesses</strong></p><ul><li>Better international trade opportunities</li><li>Access to new markets</li><li>Technology exchange</li><li>Startup funding opportunities</li></ul><p><strong>For Countries</strong></p><ul><li>Economic growth</li><li>Job creation</li><li>Stronger trade relations</li><li>Increased innovation</li></ul><p><strong>For Common People</strong></p><ul><li>More employment opportunities</li><li>Growth of small businesses</li><li>Better digital and startup ecosystem&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>International relations</li><li>Global South</li><li>Economic diplomacy</li></ul><p><strong>SSC / Banking / Railway</strong></p><ul><li>BRICS full form</li><li>Capitals</li><li>MSME full form</li><li>BRICS objectives</li></ul>', '', 'INTERNATIONAL AFFAIRS, SUMMITS & CONFERENCES, INTERNATIONAL ORGANIZATIONS', '', '', NULL, 'active', 1, '2026-05-01 01:44:00', '2026-05-09 18:18:58', '2026-05-09 19:09:45');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(19, 'Bhaskar Jyoti Sonowal elected President of BRICS Entrepreneurs Alliance Global Forum ', '', '<h2><strong>Bhaskar Jyoti Sonowal elected President of BRICS Entrepreneurs Alliance Global Forum</strong></h2><p><br></p><ul><li>This is an <strong>Appointments</strong> current affair.</li><li>Focus:</li><li>person appointed</li><li>position</li><li>tenure (2026–27)</li></ul>', '', '<h2><strong>Bhaskar Jyoti Sonowal elected President of BRICS Entrepreneurs Alliance Global Forum </strong></h2><p><br></p><p><strong>Overview</strong></p><ul><li><strong>Bhaskar Jyoti Sonowal</strong> was elected as:</li><li><strong>President of BRICS Entrepreneurs Alliance (BEA) Global Forum</strong></li><li>Tenure:</li><li><strong>2026–27</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Who is Bhaskar Jyoti Sonowal? ⭐</strong></p><ul><li>Indian entrepreneur and business leader.</li><li>Associated with:</li><li>MSME promotion</li><li>entrepreneurship development</li><li>business cooperation initiatives</li><li>Came into national news after being elected President of BEA Global Forum.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is BRICS? ⭐</strong></p><ul><li>BRICS is a group of major emerging economies.&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p class=\"ql-align-center\"><br></p><p><strong>Prime Ministers / Presidents of BRICS Nations ⭐</strong></p><p><strong>Country</strong></p><p><strong>Leader (2026)</strong></p><p>Brazil</p><p>President Luiz Inácio Lula da Silva</p><p>Russia</p><p>President Vladimir Putin</p><p>India</p><p>PM Narendra Modi</p><p>China</p><p>President Xi Jinping</p><p>South Africa</p><p>President Cyril Ramaphosa</p><p class=\"ql-align-center\"><br></p><p><strong>What is BRICS Entrepreneurs Alliance (BEA)? ⭐</strong></p><ul><li>A business cooperation platform among BRICS nations.</li><li>Focuses on:</li><li>MSMEs</li><li>startups</li><li>innovation</li><li>trade</li><li>entrepreneurship</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Objective of BEA ⭐</strong></p><ul><li>Promote:</li><li>business partnerships</li><li>startup ecosystem</li><li>MSME cooperation</li><li>investment opportunities</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is MSME? ⭐</strong></p><ul><li>MSME stands for:</li><li><strong>Micro, Small and Medium Enterprises</strong></li><li>Important for:</li><li>employment</li><li>exports</li><li>industrial growth</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Chairman / Presidency of BRICS ⭐</strong></p><ul><li>BRICS does not have a permanent chairman.</li><li>The chairmanship rotates annually among member countries.&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Previous Presidents of BEA Global Forum ⭐</strong></p><ul><li>No officially standardized year-wise global president list is widely published in exam-oriented sources.</li><li>Current important fact:</li><li><strong>Bhaskar Jyoti Sonowal elected President for 2026–27</strong> ⭐</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of BRICS Entrepreneurs Alliance ⭐</strong></p><p><strong>For Businesses</strong></p><ul><li>Better trade opportunities</li><li>Startup funding support</li><li>Technology sharing</li></ul><p><strong>For Countries</strong></p><ul><li>Economic cooperation</li><li>Employment generation</li><li>Increased investments</li></ul><p><strong>For Common People</strong></p><ul><li>More jobs</li><li>Strong MSME growth</li><li>Better business ecosystem&nbsp;</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>SSC / Banking / Railway</strong></p><ul><li>BRICS full form</li><li>Capitals &amp; currencies</li><li>MSME full form</li></ul><p><strong>UPSC</strong></p><ul><li>International relations</li><li>Economic diplomacy</li><li>Global South cooperation</li></ul>', '', 'APPOINTMENTS NEWS, AWARDS & HONOURS, PERSONS IN NEWS', '', '', NULL, 'active', 1, '2026-05-01 01:50:00', '2026-05-09 18:27:39', '2026-05-09 19:07:17');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(20, 'India strengthens Global South partnership ', '', '<h2><strong>India strengthens Global South partnership</strong> </h2><p><br></p><ul><li>India increased cooperation with developing countries. </li><li>Focus on development, trade and diplomacy. </li><li>Promotes Global South representation in international forums. </li><li>Strengthens economic and strategic partnerships.</li></ul><p><br></p>', '', '<h2><strong>India strengthens Global South Partnership </strong></h2><p><br></p><p><strong>What is Global South? ⭐</strong></p><ul><li><strong>Global South</strong> refers to: </li><li>developing and less-developed countries mainly in: </li><li>Asia </li><li>Africa </li><li>Latin America </li><li>Oceania </li><li>These countries generally face: </li><li>poverty </li><li>lower industrial development </li><li>economic challenges </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why is it called “Global South”?</strong></p><ul><li>Most developing countries are located in the <strong>Southern Hemisphere</strong>. </li><li>It is a political and economic term, not strictly geographical.&nbsp;</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p class=\"ql-align-center\"><br></p><p><strong>How India strengthens Global South Partnership ⭐</strong></p><p><strong>1. Development Assistance</strong></p><p>India provides:</p><ul><li>financial aid </li><li>grants </li><li>loans </li><li>infrastructure projects</li><li> to developing countries. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>2. Technology &amp; Digital Support</strong></p><p>India shares:</p><ul><li>digital payment systems </li><li>IT services </li><li>digital public infrastructure </li><li>telemedicine technology </li></ul><p class=\"ql-align-center\"><br></p><p><strong>3. Vaccine &amp; Health Support ⭐</strong></p><ul><li>India supplied medicines and vaccines to many countries during global health crises. </li><li>Known for: </li><li>“Vaccine Maitri” initiative. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>4. Trade &amp; Economic Cooperation</strong></p><p>India increases:</p><ul><li>exports </li><li>investments </li><li>trade partnerships</li><li> with developing nations. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>5. Capacity Building Programs</strong></p><p>India offers:</p><ul><li>scholarships </li><li>training programs </li><li>skill development</li><li> for students and officials from Global South countries. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>6. Diplomatic Leadership ⭐</strong></p><p>India raises issues related to:</p><ul><li>climate justice </li><li>food security </li><li>energy security </li><li>fair global governance</li><li> on international platforms. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>India’s Role in Global South ⭐</strong></p><ul><li>India presents itself as: </li><li>“Voice of the Global South.” </li><li>Focuses on: </li><li>inclusive growth </li><li>South-South cooperation </li><li>sustainable development </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Global South Partnership ⭐</strong></p><p><strong>For India</strong></p><ul><li>Stronger diplomatic influence </li><li>Better trade opportunities </li><li>Strategic partnerships </li><li>Global leadership role </li></ul><p><strong>For Developing Countries</strong></p><ul><li>Infrastructure development </li><li>Technology access </li><li>Healthcare support </li><li>Educational opportunities </li></ul><p><strong>For Common People</strong></p><ul><li>More jobs and business opportunities </li><li>Better international cooperation </li><li>Improved healthcare and education support&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p class=\"ql-align-center\"><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>International Relations </li><li>South-South Cooperation </li><li>India’s foreign policy </li></ul><p><strong>SSC / Banking / Railway</strong></p><ul><li>Capitals &amp; currencies </li><li>International cooperation </li><li>Important global groupings</li></ul><p><br></p>', '', 'INTERNATIONAL AFFAIRS', '', '', NULL, 'active', 1, '2026-05-01 12:59:00', '2026-05-09 18:34:16', '2026-05-09 18:34:16');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(21, 'SEBI launches PaRRVA system ', '', '<h2><strong>SEBI launches PaRRVA system</strong> </h2><p><br></p><ul><li>Launched by <strong>SEBI (Securities and Exchange Board of India)</strong> </li><li>Digital regulatory reporting platform </li><li>Improves transparency and monitoring in financial markets </li><li>Helps faster and efficient data reporting and compliance</li></ul><p><br></p>', '', '<h2><strong>SEBI launches PaRRVA System </strong></h2><p><br></p><p><strong>What is SEBI? ⭐</strong></p><ul><li><strong>SEBI</strong> stands for: </li><li><strong>Securities and Exchange Board of India</strong> </li><li>It is the main regulator of: </li><li>stock markets </li><li>capital markets </li><li>securities markets in India </li><li>SEBI protects: </li><li>investors </li><li>traders </li><li>market integrity </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Establishment of SEBI ⭐</strong></p><ul><li>Established: </li><li><strong>1988</strong> </li><li>Given statutory powers through: </li><li><strong>SEBI Act, 1992</strong> ⭐ </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><ul><li><strong>Mumbai, Maharashtra</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Chairman of SEBI ⭐</strong></p><ul><li>Current Chairman: </li><li><strong>Tuhin Kanta Pandey</strong> <em>(2026)</em> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Who controls SEBI? ⭐</strong></p><ul><li>SEBI works under: </li><li><strong>Ministry of Finance</strong> </li><li>Government of India </li><li>However, it functions as an: </li><li>autonomous regulatory body. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Main Roles of SEBI ⭐</strong></p><p><strong>1. Protect Investors</strong></p><ul><li>Prevents fraud and unfair trade practices. </li></ul><p><strong>2. Regulate Stock Markets</strong></p><ul><li>Supervises: </li><li>NSE </li><li>BSE </li><li>brokers </li><li>mutual funds </li></ul><p><strong>3. Promote Fair Trading</strong></p><ul><li>Ensures transparency in financial markets. </li></ul><p><strong>4. Regulate Companies Raising Funds</strong></p><ul><li>Controls IPOs and public issues. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Other Important SEBI Initiatives ⭐</strong></p><p>SEBI has launched:</p><ul><li>SCORES grievance portal </li><li>ASBA system </li><li>T+1 settlement system </li><li>Investor awareness programs </li><li>Digital compliance systems </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is PaRRVA System? ⭐</strong></p><ul><li><strong>PaRRVA</strong> is a digital regulatory reporting platform launched by SEBI. </li><li>It helps in: </li><li>faster data submission </li><li>digital compliance reporting </li><li>market monitoring </li><li>better regulatory supervision </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of PaRRVA ⭐</strong></p><ul><li>To modernize financial market regulation. </li><li>To improve: </li><li>transparency </li><li>efficiency </li><li>digital governance </li><li>compliance management </li></ul><p class=\"ql-align-center\"><br></p><p><strong>How does PaRRVA regulate markets? ⭐</strong></p><p>The system:</p><ul><li>collects digital reports from market participants </li><li>tracks compliance automatically </li><li>monitors irregularities </li><li>helps SEBI take faster action against violations </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of PaRRVA System ⭐</strong></p><p><strong>For SEBI</strong></p><ul><li>Better monitoring </li><li>Faster data analysis </li><li>Improved regulation </li><li>Reduced paperwork </li></ul><p><strong>For Financial Institutions</strong></p><ul><li>Easier compliance process </li><li>Faster reporting </li><li>Better transparency </li></ul><p><strong>For Investors</strong></p><ul><li>Safer and more transparent markets </li><li>Better investor protection </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>Banking / SSC / Railway</strong></p><ul><li>Full form of SEBI </li><li>SEBI headquarters </li><li>SEBI chairman </li><li>Regulatory functions </li></ul><p><strong>UPSC</strong></p><ul><li>Financial market regulation </li><li>Capital market reforms </li><li>Digital governance&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p>', '', 'ECONOMY & BANKING', '', '', NULL, 'active', 1, '2026-05-01 13:05:00', '2026-05-09 18:38:39', '2026-05-09 18:38:39');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(22, ' EPFO digitization initiative launched ', '', '<h2><strong>EPFO digitization initiative launched</strong> </h2><p><br></p><ul><li>Launched by <strong>EPFO</strong> </li><li>Improves PF and pension grievance services </li><li>Provides faster and transparent digital support </li><li>Enhances online complaint tracking and resolution</li></ul><p><br></p>', '', '<h2><strong>EPFO Digitization Initiative Launched </strong></h2><p><br></p><p><strong>What is EPFO? ⭐</strong></p><ul><li><strong>EPFO</strong> stands for: </li><li><strong>Employees’ Provident Fund Organisation</strong> </li><li>It is India’s largest social security organization. </li><li>Works under: </li><li><strong>Ministry of Labour &amp; Employment</strong> </li><li>Government of India </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><ul><li><strong>New Delhi</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Chairman of EPFO ⭐</strong></p><ul><li>Union Labour &amp; Employment Minister acts as the: </li><li><strong>Chairman of EPFO</strong> </li><li><em>(2026: Mansukh Mandaviya)</em> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is PF (Provident Fund)? ⭐</strong></p><ul><li><strong>Provident Fund (PF)</strong> is a retirement savings scheme for salaried employees. </li><li>Both: </li><li>employee and </li><li>employer</li><li> contribute money every month. </li><li>Managed by: </li><li>EPFO </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of PF ⭐</strong></p><ul><li>Provides: </li><li>retirement savings </li><li>financial security </li><li>pension benefits </li><li>emergency financial support </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Pension in EPFO? ⭐</strong></p><ul><li>EPFO also manages: </li><li><strong>Employees’ Pension Scheme (EPS)</strong> </li><li>Provides monthly pension after retirement. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is EPFO Digitization Initiative? ⭐</strong></p><ul><li>EPFO launched digital initiatives to: </li><li>modernize PF services </li><li>improve grievance redressal </li><li>provide faster online services </li><li>Includes: </li><li>online portals </li><li>complaint tracking systems </li><li>digital verification </li><li>paperless processing </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why was it launched? ⭐</strong></p><p>The initiative was launched to:</p><ul><li>reduce delays in PF claims </li><li>improve transparency </li><li>provide easier online access </li><li>reduce paperwork </li><li>strengthen digital governance </li></ul><p class=\"ql-align-center\"><br></p><p><strong>How does it improve PF &amp; pension grievance services? ⭐</strong></p><p><strong>1. Faster Complaint Resolution</strong></p><ul><li>Complaints are processed digitally. </li><li>Reduces manual delays. </li></ul><p><strong>2. Online Tracking</strong></p><ul><li>Users can track complaint status online in real time. </li></ul><p><strong>3. Paperless Services</strong></p><ul><li>Less physical paperwork and office visits. </li></ul><p><strong>4. Better Transparency</strong></p><ul><li>Subscribers get updates and digital records. </li></ul><p><strong>5. Faster PF Withdrawals &amp; Pension Services</strong></p><ul><li>Improves efficiency in claim settlement. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of EPFO Digitization ⭐</strong></p><p><strong>For Employees</strong></p><ul><li>Easy access to PF services </li><li>Faster pension processing </li><li>Online grievance support </li><li>Reduced corruption and delays </li></ul><p><strong>For Pensioners</strong></p><ul><li>Quick complaint resolution </li><li>Better pension management </li></ul><p><strong>For Government</strong></p><ul><li>Efficient administration </li><li>Better monitoring system </li><li>Improved digital governance </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Other Important EPFO Services ⭐</strong></p><ul><li>UAN (Universal Account Number) </li><li>Online PF transfer </li><li>PF balance check </li><li>Pension tracking </li><li>Digital KYC services </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>SSC / Banking / Railway</strong></p><ul><li>EPFO full form </li><li>Ministry </li><li>PF-related questions </li><li>Social security schemes </li></ul><p><strong>UPSC</strong></p><ul><li>Labour welfare </li><li>Digital governance </li><li>Social security reforms&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p>', '', 'ECONOMY & BANKING', '', '', NULL, 'active', 1, '2026-05-01 13:09:00', '2026-05-09 18:42:06', '2026-05-09 18:42:06');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(23, 'NDMA tests Cell Broadcast Emergency Alert System ', '', '<h2><strong>NDMA tests Cell Broadcast Emergency Alert System</strong></h2><p><br></p><ul><li>Tested by <strong>National Disaster Management Authority (NDMA)</strong></li><li>Nationwide mobile emergency warning system</li><li>Sends disaster alerts directly to mobile phones</li><li>Helps during earthquakes, floods and emergencies</li><li>Improves disaster communication and public safety</li></ul>', '', '<h2><strong>NDMA tests Cell Broadcast Emergency Alert System </strong></h2><p><br></p><p><strong>What is NDMA? ⭐</strong></p><ul><li><strong>NDMA</strong> stands for:</li><li><strong>National Disaster Management Authority</strong></li><li>It is India’s top disaster management body.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Established Under ⭐</strong></p><ul><li>Created under:</li><li><strong>Disaster Management Act, 2005</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Ministry ⭐</strong></p><ul><li>Works under:</li><li><strong>Ministry of Home Affairs (MHA)</strong></li><li>Government of India</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><ul><li><strong>New Delhi</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Chairman of NDMA ⭐</strong></p><ul><li>The <strong>Prime Minister of India</strong> is the ex-officio Chairman of NDMA.</li><li><em>(2026: Narendra Modi)</em></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Main Role of NDMA ⭐</strong></p><p>NDMA works for:</p><ul><li>disaster prevention</li><li>preparedness</li><li>mitigation</li><li>rescue and relief operations</li><li>disaster response planning</li></ul><p>Handles disasters like:</p><ul><li>earthquakes</li><li>floods</li><li>cyclones</li><li>heatwaves</li><li>landslides</li><li>industrial accidents</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Cell Broadcast Emergency Alert System? ⭐</strong></p><ul><li>A nationwide emergency warning system tested by NDMA.</li><li>Sends emergency alerts directly to:</li><li>mobile phones</li><li>without internet or SMS registration.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of the System ⭐</strong></p><ul><li>To warn people quickly during:</li><li>earthquakes</li><li>floods</li><li>cyclones</li><li>tsunamis</li><li>heatwaves</li><li>national emergencies</li></ul><p class=\"ql-align-center\"><br></p><p><strong>How does it work? ⭐</strong></p><p><strong>Step-by-Step Process</strong></p><ol><li>NDMA or government authority issues emergency alert.</li><li>Telecom networks transmit the message using:</li></ol><ul><li>Cell Broadcast Technology.</li></ul><ol><li>All mobile phones in the affected area receive warning alerts instantly.</li><li>Alert appears with:</li></ol><ul><li>loud sound</li><li>vibration</li><li>emergency notification</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Cell Broadcast Technology? ⭐</strong></p><ul><li>A technology that sends messages to all mobile devices connected to specific cell towers.</li><li>Unlike SMS:</li><li>no mobile number database required</li><li>works even during network congestion</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Cell Broadcast Alert System ⭐</strong></p><p><strong>For Citizens</strong></p><ul><li>Instant disaster warnings</li><li>Saves lives during emergencies</li><li>No internet required</li><li>Reaches millions quickly</li></ul><p><strong>For Government</strong></p><ul><li>Faster emergency communication</li><li>Better disaster preparedness</li><li>Efficient public safety management</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance in Disaster Management ⭐</strong></p><ul><li>Helps reduce:</li><li>casualties</li><li>panic</li><li>communication delays</li><li>Strengthens India’s:</li><li>early warning system</li><li>disaster response mechanism&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Disaster management</li><li>Internal security</li><li>Governance</li></ul><p><strong>SSC / Railway / Banking</strong></p><ul><li>Full forms</li><li>Ministries</li><li>Disaster management agencies&nbsp;</li></ul>', '', 'NATIONAL AFFAIRS, DEFENCE & SECURITY, DISASTER MANAGEMENT', '', '', NULL, 'active', 1, '2026-05-01 14:45:00', '2026-05-10 07:19:57', '2026-05-11 17:39:53');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(24, 'OCI Rules 2026 notified by MHA ', '', '<h2><strong> OCI Rules 2026 notified by MHA</strong></h2><p><br></p><ul><li>Notified by <strong>Ministry of Home Affairs (MHA)</strong></li><li>Introduces fully digital <strong>e-OCI registration system</strong></li><li>Simplifies Overseas Citizen of India services</li><li>Improves online application and verification process</li></ul>', '', '<h2><strong> OCI Rules 2026 notified by MHA </strong></h2><p><strong>What is OCI? ⭐</strong></p><ul><li><strong>OCI</strong> stands for:</li><li><strong>Overseas Citizen of India</strong></li><li>OCI is a special immigration status given to:</li><li>foreign citizens of Indian origin.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Introduced By ⭐</strong></p><ul><li>Introduced under:</li><li><strong>Citizenship Act, 1955</strong></li><li>Implemented by:</li><li><strong>Ministry of Home Affairs (MHA)</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Who can get OCI Card? ⭐</strong></p><p>People eligible include:</p><ul><li>Persons of Indian origin living abroad</li><li>Foreign citizens whose:</li><li>parents</li><li>grandparents</li><li>great-grandparents</li><li>were Indian citizens</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Who cannot get OCI? ⭐</strong></p><ul><li>Citizens of:</li><li>Pakistan</li><li>Bangladesh</li><li>and some other restricted countries are not eligible.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is OCI Card? ⭐</strong></p><ul><li>A lifelong visa-like facility for eligible foreign citizens of Indian origin.</li><li>Allows:</li><li>multiple entry into India</li><li>long-term stay in India</li><li>easier travel and residence</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of OCI Card ⭐</strong></p><p><strong>Travel Benefits</strong></p><ul><li>Lifelong multiple-entry visa to India.</li><li>No need for repeated visa applications.</li></ul><p><strong>Residence Benefits</strong></p><ul><li>Can stay in India for unlimited duration.</li></ul><p><strong>Economic &amp; Educational Benefits</strong></p><ul><li>Similar economic and educational rights as NRIs in many sectors.</li></ul><p><strong>Simplified Immigration</strong></p><ul><li>Easier registration and documentation process.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>OCI Rules 2026 ⭐</strong></p><ul><li>New rules notified by:</li><li><strong>Ministry of Home Affairs (MHA)</strong></li></ul><p>Main objective:</p><ul><li>digitization and simplification of OCI services.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is e-OCI Registration System? ⭐</strong></p><ul><li>A fully digital online system for:</li><li>OCI application</li><li>registration</li><li>verification</li><li>document submission</li><li>status tracking</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of e-OCI System ⭐</strong></p><ul><li>Reduce paperwork</li><li>Faster processing</li><li>Improve transparency</li><li>Provide easier access for overseas Indians</li></ul><p class=\"ql-align-center\"><br></p><p><strong>How does e-OCI work? ⭐</strong></p><ol><li>Applicant applies online.</li><li>Uploads documents digitally.</li><li>Online verification is conducted.</li><li>Application status can be tracked online.</li><li>OCI card issued digitally and physically after approval.</li></ol><p class=\"ql-align-center\"><br></p><p><strong>Benefits of OCI Rules 2026 ⭐</strong></p><p><strong>For Applicants</strong></p><ul><li>Faster application processing</li><li>Less paperwork</li><li>Online convenience</li><li>Better transparency</li></ul><p><strong>For Government</strong></p><ul><li>Efficient database management</li><li>Improved digital governance</li><li>Faster verification system&nbsp;</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong style=\"color: rgb(230, 0, 0);\">Importance for Exams </strong></p><p><strong style=\"color: rgb(230, 0, 0);\">UPSC</strong></p><ul><li><span style=\"color: rgb(230, 0, 0);\">Citizenship </span></li><li><span style=\"color: rgb(230, 0, 0);\">Governance </span></li><li><span style=\"color: rgb(230, 0, 0);\">Diaspora policy </span></li></ul><p><strong style=\"color: rgb(230, 0, 0);\">SSC / Railway / Banking</strong></p><ul><li><span style=\"color: rgb(230, 0, 0);\">Full forms </span></li><li><span style=\"color: rgb(230, 0, 0);\">Ministries </span></li><li><span style=\"color: rgb(230, 0, 0);\">Citizenship-related questions</span></li></ul>', '', 'NATIONAL AFFAIRS, POLITY & GOVERNANCE, AMENDMENTS & BILLS', '', '', NULL, 'active', 1, '2026-05-01 09:21:00', '2026-05-10 07:23:52', '2026-05-11 15:45:57');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(25, 'Prime Minister Internship Scheme 2026 gains attention ', '', '<h2><strong>Prime Minister Internship Scheme 2026 gains attention</strong></h2><p><br></p><ul><li>Government internship initiative for youth</li><li>Monthly stipend: ₹9,000</li><li>Focus on skill development and employment opportunities</li><li>Provides industry and workplace experience to students and young professionals</li></ul>', '', '<h2><strong>Prime Minister Internship Scheme 2026 </strong></h2><p><br></p><p><strong>Overview</strong></p><ul><li><strong>Prime Minister Internship Scheme 2026</strong> is a Government of India initiative aimed at:</li><li>skill development</li><li>practical training</li><li>employment readiness for youth.</li><li>The scheme gained attention because it provides:</li><li>internship opportunities</li><li>real workplace experience</li><li>monthly stipend of <strong>₹9,000</strong> ⭐</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Objective of the Scheme ⭐</strong></p><p>Main goals:</p><ul><li>improve employability of youth</li><li>provide industry exposure</li><li>bridge the gap between education and jobs</li><li>develop practical skills</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Who can benefit? ⭐</strong></p><ul><li>Students</li><li>Graduates</li><li>Young professionals</li><li>Skill trainees</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is an Internship? ⭐</strong></p><ul><li>An internship is:</li><li>short-term practical work training</li><li>provided by companies or organizations.</li><li>Helps students gain:</li><li>real job experience</li><li>professional skills</li><li>workplace knowledge</li></ul><p class=\"ql-align-center\"><br></p><p><strong>How does the scheme support Skill Development? ⭐</strong></p><p><strong>1. Practical Learning</strong></p><ul><li>Students learn:</li><li>communication skills</li><li>technical skills</li><li>teamwork</li><li>professional behavior</li></ul><p class=\"ql-align-center\"><br></p><p><strong>2. Industry Exposure</strong></p><ul><li>Interns work in:</li><li>companies</li><li>industries</li><li>government departments</li><li>corporate offices</li></ul><p>This helps them understand:</p><ul><li>workplace environment</li><li>business operations</li><li>real-world challenges</li></ul><p class=\"ql-align-center\"><br></p><p><strong>3. Employment Opportunities</strong></p><ul><li>Experience improves chances of:</li><li>getting jobs</li><li>campus placement</li><li>career growth</li></ul><p>Many interns may receive:</p><ul><li>permanent job offers</li><li>after successful internship performance.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why is it Important? ⭐</strong></p><p>India has:</p><ul><li>a large youth population</li><li>increasing demand for skilled workers.</li></ul><p>The scheme helps:</p><ul><li>reduce unemployment</li><li>improve workforce quality</li><li>support economic growth</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Prime Minister Internship Scheme ⭐</strong></p><p><strong>For Students</strong></p><ul><li>Monthly financial support (₹9,000)</li><li>Work experience</li><li>Better resume/profile</li><li>Skill improvement</li></ul><p><strong>For Industry</strong></p><ul><li>Access to trained young workforce</li><li>Better industry-academia connection</li></ul><p><strong>For Government</strong></p><ul><li>Employment generation</li><li>Skilled workforce development</li><li>Youth empowerment&nbsp;</li></ul><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Related Government Programs ⭐</strong></p><ul><li>Skill India Mission</li><li>PMKVY (Pradhan Mantri Kaushal Vikas Yojana)</li><li>Digital India</li><li>Startup India</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Skill development</li><li>Employment generation</li><li>Human resource development</li></ul><p><strong>SSC / Banking / Railway</strong></p><ul><li>Government schemes</li><li>Youth employment</li><li>Stipend-related questions</li></ul><p><br></p>', '', 'NATIONAL AFFAIRS, SCHEMES & GOVT. POLICIES', '', '', NULL, 'active', 1, '2026-05-01 20:30:00', '2026-05-10 07:34:45', '2026-05-11 15:26:12');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(26, 'India-US trade talks enter key phase in Washington ', '', '<h2><strong>India-US trade talks enter key phase in Washington</strong></h2><p><br></p><ul><li>Trade discussions held between India and USA in Washington D.C.</li><li>Focus on bilateral trade agreement and market access</li><li>Aims to strengthen economic and commercial cooperation</li><li>Discussions include technology, exports and investment opportunities</li></ul>', '', '<h2><strong>India-US Trade Talks enter Key Phase in Washington </strong></h2><p><br></p><p><strong>Overview</strong></p><ul><li>India and the United States held important trade discussions in:</li><li><strong>Washington D.C., USA</strong></li><li>Focus areas:</li><li>bilateral trade agreement</li><li>market access</li><li>technology cooperation</li><li>investment</li><li>exports and imports</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Where is Washington D.C.? ⭐</strong></p><ul><li><strong>Washington D.C.</strong> is the capital of:</li><li><strong>United States of America (USA)</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Geographical Importance of Washington D.C. ⭐</strong></p><ul><li>Located on the:</li><li><strong>Potomac River</strong></li><li>Situated between:</li><li>Maryland and Virginia</li><li>Political and administrative center of the USA.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance of Washington D.C. ⭐</strong></p><ul><li>Headquarters of:</li><li>White House</li><li>US Congress</li><li>Supreme Court</li><li>Major global diplomatic center.</li><li>Important for:</li><li>international trade negotiations</li><li>global diplomacy</li></ul><p class=\"ql-align-center\"><br></p><p><strong>India–USA Relations ⭐</strong></p><p>India and USA are strategic partners in:</p><ul><li>trade</li><li>defence</li><li>technology</li><li>energy</li><li>education</li><li>Indo-Pacific cooperation&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Bilateral Trade? ⭐</strong></p><ul><li>Trade conducted between:</li><li>two countries.</li><li>Includes:</li><li>exports</li><li>imports</li><li>investment cooperation</li></ul><p>Example:</p><ul><li>India exports medicines and IT services to USA.</li><li>USA exports technology and machinery to India.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Market Access? ⭐</strong></p><ul><li>Permission and opportunity for companies to:</li><li>sell goods and services in another country’s market.</li></ul><p>Trade talks focus on:</p><ul><li>reducing trade barriers</li><li>lowering tariffs</li><li>easier business operations</li></ul><p class=\"ql-align-center\"><br></p><p><strong>How do India-US trade talks strengthen cooperation? ⭐</strong></p><p><strong>1. Increase Trade</strong></p><ul><li>More exports and imports between both countries.</li></ul><p><strong>2. Technology Sharing</strong></p><ul><li>Cooperation in:</li><li>semiconductors</li><li>AI</li><li>digital technology</li></ul><p><strong>3. Investment Growth</strong></p><ul><li>Encourages US companies to invest in India.</li></ul><p><strong>4. Job Creation</strong></p><ul><li>Expands manufacturing and service sectors.</li></ul><p><strong>5. Supply Chain Development</strong></p><ul><li>Reduces dependence on single-country imports.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of India-US Trade Cooperation ⭐</strong></p><p><strong>For India</strong></p><ul><li>More foreign investment</li><li>Technology transfer</li><li>Export growth</li><li>Employment generation</li></ul><p><strong>For USA</strong></p><ul><li>Access to Indian market</li><li>Business expansion</li><li>Strategic partnership in Asia</li></ul><p><strong>For Common People</strong></p><ul><li>More jobs</li><li>Better products and technology</li><li>Economic growth&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>International relations</li><li>Trade diplomacy</li><li>India-US strategic partnership</li></ul><p><strong>SSC / Banking / Railway</strong></p><ul><li>Capitals &amp; currencies</li><li>Bilateral agreements</li><li>Trade-related terms</li></ul>', '', 'INTERNATIONAL AFFAIRS, SUMMITS & CONFERENCES', '', '', NULL, 'active', 1, '2026-05-01 20:36:00', '2026-05-10 07:40:21', '2026-05-11 15:31:37');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(27, 'India strengthens semiconductor partnerships globally ', '', '<h2><strong>India strengthens semiconductor partnerships globally</strong></h2><p><br></p><ul><li>India expands global semiconductor cooperation</li><li>Focus on chip manufacturing and technology development</li><li>Aims to boost electronics and digital economy</li><li>Encourages foreign investment and supply chain growth</li></ul>', '', '<h2><strong>India strengthens Semiconductor Partnerships Globally </strong></h2><p><br></p><p><strong>Overview</strong></p><ul><li>India is increasing global partnerships in:</li><li>semiconductor manufacturing</li><li>chip technology</li><li>electronics production</li><li>Focus:</li><li>technology cooperation</li><li>supply chain development</li><li>reducing import dependence</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is a Semiconductor? ⭐</strong></p><ul><li>A <strong>semiconductor</strong> is a material that conducts electricity:</li><li>better than an insulator</li><li>but less than a conductor.</li><li>Used to make:</li><li>computer chips</li><li>processors</li><li>electronic circuits</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Common Semiconductor Materials ⭐</strong></p><ul><li>Silicon ⭐ (most widely used)</li><li>Germanium</li><li>Gallium Arsenide</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Made Of ⭐</strong></p><p>Most semiconductor chips are made from:</p><ul><li><strong>Silicon</strong></li><li>which is obtained from:</li><li>sand (silica).</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Father of Semiconductor / Electronics ⭐</strong></p><ul><li><strong>William Shockley</strong> is known as:</li><li>“Father of the Semiconductor”</li><li>Co-inventor of the:</li><li>transistor ⭐</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is a Chip? ⭐</strong></p><ul><li>A chip is a small electronic circuit made using semiconductors.</li><li>Also called:</li><li>Integrated Circuit (IC)</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Uses of Semiconductors ⭐</strong></p><p><strong>Electronics</strong></p><ul><li>Mobile phones</li><li>Computers</li><li>TVs</li><li>Laptops</li></ul><p><strong>Automobiles</strong></p><ul><li>Electric vehicles</li><li>Smart cars</li></ul><p><strong>Defence</strong></p><ul><li>Missiles</li><li>Radars</li><li>Communication systems</li></ul><p><strong>Space &amp; Technology</strong></p><ul><li>Satellites</li><li>AI systems</li><li>Robotics</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why is India strengthening semiconductor partnerships globally? ⭐</strong></p><p><strong>1. Reduce Import Dependence</strong></p><ul><li>India imports most chips from foreign countries.</li></ul><p><strong>2. Build Domestic Manufacturing</strong></p><ul><li>Promote:</li><li>“Make in India”</li><li>electronics manufacturing</li></ul><p><strong>3. Secure Supply Chains</strong></p><ul><li>Global chip shortages affected industries worldwide.</li></ul><p><strong>4. Support Digital Economy</strong></p><ul><li>Growing demand for:</li><li>AI</li><li>5G</li><li>electronics</li><li>data centers</li></ul><p class=\"ql-align-center\"><br></p><p><strong>How does it boost electronics &amp; digital economy? ⭐</strong></p><p><strong>Electronics Manufacturing Growth</strong></p><ul><li>Helps India produce:</li><li>mobile phones</li><li>laptops</li><li>smart devices</li></ul><p><strong>Technology Development</strong></p><ul><li>Encourages:</li><li>AI</li><li>automation</li><li>digital innovation</li></ul><p><strong>Startup Ecosystem</strong></p><ul><li>Supports tech startups and innovation.</li></ul><p><strong>Digital Infrastructure</strong></p><ul><li>Strengthens:</li><li>telecom</li><li>internet services</li><li>smart governance</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Semiconductor Partnerships ⭐</strong></p><p><strong>For India</strong></p><ul><li>Foreign investment</li><li>Employment generation</li><li>Technology transfer</li><li>Economic growth</li></ul><p><strong>For Industries</strong></p><ul><li>Better chip availability</li><li>Reduced production cost</li><li>Stable supply chains</li></ul><p><strong>For Common People</strong></p><ul><li>More affordable electronics</li><li>Faster digital services</li><li>More technology jobs</li></ul><p class=\"ql-align-center\"><br></p><p><strong>India’s Semiconductor Mission ⭐</strong></p><ul><li>Government launched:</li><li><strong>India Semiconductor Mission (ISM)</strong> ⭐</li><li>Aim:</li><li>develop semiconductor ecosystem in India.&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Science &amp; Technology</li><li>Economic development</li><li>Strategic industries</li></ul><p><strong>SSC / Banking / Railway</strong></p><ul><li>Semiconductor basics</li><li>Silicon uses</li><li>Technology-related GK</li></ul>', '', 'INTERNATIONAL AFFAIRS, SCIENCE & TECHNOLOGY, MoUS & AGREEMENTS', '', '', NULL, 'active', 1, '2026-05-01 09:41:00', '2026-05-10 07:45:29', '2026-05-11 15:48:58');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(28, 'RBI maintains focus on liquidity management ', '', '<h2><strong>RBI maintains focus on liquidity management</strong> </h2><p><br></p><ul><li>RBI monitoring inflation and economic growth </li><li>Focus on controlling money supply in banking system </li><li>Aims to maintain price stability and financial stability </li><li>Markets tracking RBI policy signals closely</li></ul><p><br></p>', '', '<h2><strong>Reserve Bank of India (RBI) </strong></h2><p><br></p><p><strong>What is RBI?</strong></p><ul><li>RBI is the <strong>Central Bank of India</strong>. </li><li>It controls: </li><li>Money supply </li><li>Banking system </li><li>Inflation </li><li>Monetary policy </li><li>Currency issue </li></ul><p><strong>Established</strong></p><ul><li>Established on: <strong>1 April 1935</strong> </li><li>Under: <strong>Reserve Bank of India Act, 1934</strong> </li><li>Nationalised in: <strong>1949</strong> </li></ul><p><strong>Headquarters</strong></p><ul><li>Mumbai, Maharashtra </li></ul><p><strong>Motto</strong></p><ul><li><strong>“Yogakshemam Vahamyaham”</strong> </li><li>Meaning: <em>I shall carry out welfare.</em> </li></ul><p><strong>Symbol</strong></p><ul><li>Tiger and Palm Tree. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Main Functions of RBI</strong></p><p><strong>1. Banker to Government</strong></p><ul><li>Manages Central and State Government accounts. </li><li>Gives loans to government. </li></ul><p><strong>2. Banker’s Bank</strong></p><ul><li>All commercial banks keep accounts with RBI. </li></ul><p><strong>3. Currency Issuer</strong></p><ul><li>RBI prints and issues Indian currency notes. </li><li>₹1 note issued by Finance Ministry. </li><li>Coins issued by Government of India. </li></ul><p><strong>4. Monetary Policy Authority</strong></p><ul><li>Controls inflation and economic growth. </li></ul><p><strong>5. Foreign Exchange Management</strong></p><ul><li>Manages forex reserves. </li><li>Regulates FEMA Act, 1999. </li></ul><p><strong>6. Financial Stability</strong></p><ul><li>Supervises banks and NBFCs.&nbsp;</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>First Indian RBI Governor</strong></p><ul><li>C.D. Deshmukh </li></ul><p><strong>First Woman Deputy Governor</strong></p><ul><li>K.J. Udeshi </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Banks Under RBI Supervision</strong></p><p><strong>Commercial Banks</strong></p><ul><li>Public Sector Banks </li><li>Private Banks </li><li>Foreign Banks </li><li>Regional Rural Banks (RRBs) </li><li>Small Finance Banks </li><li>Payments Banks </li></ul><p><strong>NBFCs</strong></p><ul><li>Non-Banking Financial Companies regulated by RBI. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Important RBI Policies &amp; Norms</strong></p><p><strong>Monetary Policy</strong></p><ul><li>Decides interest rates and money supply. </li></ul><p><strong>Inflation Target</strong></p><ul><li>RBI inflation target: </li><li><strong>4% (+/- 2%)</strong> </li></ul><p><strong>Basel Norms</strong></p><ul><li>Banking safety and capital adequacy standards. </li></ul><p><strong>CRR &amp; SLR Rules</strong></p><ul><li>Mandatory reserve requirements for banks. </li></ul><p><strong>Digital Banking Rules</strong></p><ul><li>UPI </li><li>CBDC (Digital Rupee) </li><li>Payment systems regulation </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Liquidity?</strong></p><p><strong>Meaning</strong></p><ul><li>Liquidity means: </li><li>Availability of money/cash in economy or banking system. </li></ul><p><strong>Example</strong></p><ul><li>More loans and cash availability = High liquidity. </li><li>Less money supply = Low liquidity. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Liquidity Management</strong></p><p><strong>Meaning</strong></p><ul><li>RBI controls flow of money in economy. </li></ul><p><strong>Objectives</strong></p><ul><li>Maintain price stability. </li><li>Ensure enough money for growth. </li><li>Prevent excess inflation. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>How RBI Manages Liquidity?</strong></p><p><strong>1. Repo Rate ⭐</strong></p><ul><li>Rate at which RBI lends money to banks. </li></ul><p><strong>Increase Repo Rate</strong></p><ul><li>Loans become costly. </li><li>Money supply decreases. </li><li>Inflation reduces. </li></ul><p><strong>Decrease Repo Rate</strong></p><ul><li>Loans become cheaper. </li><li>Money supply increases. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>2. Reverse Repo Rate</strong></p><ul><li>RBI borrows money from banks. </li></ul><p><strong>Higher Reverse Repo</strong></p><ul><li>Banks deposit more money with RBI. </li><li>Liquidity decreases. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>3. CRR (Cash Reserve Ratio) ⭐</strong></p><p>CRR=Cash&nbsp;ReserveNet&nbsp;Demand&nbsp;and&nbsp;Time&nbsp;Liabilities×100CRR = \\frac{Cash\\ Reserve}{Net\\ Demand\\ and\\ Time\\ Liabilities} \\times 100CRR=Net&nbsp;Demand&nbsp;and&nbsp;Time&nbsp;LiabilitiesCash&nbsp;Reserve​×100</p><ul><li>Portion of deposits banks keep with RBI. </li><li>Higher CRR: </li><li>Less lending capacity. </li><li>Lower liquidity. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>4. SLR (Statutory Liquidity Ratio)</strong></p><p>SLR=Liquid&nbsp;AssetsNet&nbsp;Demand&nbsp;and&nbsp;Time&nbsp;Liabilities×100SLR = \\frac{Liquid\\ Assets}{Net\\ Demand\\ and\\ Time\\ Liabilities} \\times 100SLR=Net&nbsp;Demand&nbsp;and&nbsp;Time&nbsp;LiabilitiesLiquid&nbsp;Assets​×100</p><ul><li>Banks maintain liquid assets like gold/government securities. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>5. Open Market Operations (OMO) ⭐</strong></p><ul><li>RBI buys/sells government securities. </li></ul><p><strong>RBI Buys Securities</strong></p><ul><li>Injects money into economy. </li></ul><p><strong>RBI Sells Securities</strong></p><ul><li>Absorbs money from economy. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>6. Bank Rate</strong></p><ul><li>Long-term lending rate of RBI to banks. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>7. MSF (Marginal Standing Facility)</strong></p><ul><li>Emergency borrowing facility for banks. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>8. LAF (Liquidity Adjustment Facility)</strong></p><ul><li>Daily liquidity management system. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Inflation?</strong></p><p><strong>Meaning</strong></p><ul><li>Continuous increase in prices of goods and services. </li></ul><p><strong>Example</strong></p><ul><li>Food, fuel, transport becoming expensive.&nbsp;</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>How RBI Controls Inflation?</strong></p><p><strong>1. Increase Repo Rate</strong></p><ul><li>Loans become expensive. </li><li>Spending reduces. </li></ul><p><strong>2. Increase CRR/SLR</strong></p><ul><li>Banks lend less money. </li></ul><p><strong>3. Sell Government Securities</strong></p><ul><li>Removes excess money. </li></ul><p><strong>4. Tight Monetary Policy</strong></p><ul><li>Reduces liquidity. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Banking System in India</strong></p><p><strong>Scheduled Banks</strong></p><ul><li>Included in RBI Second Schedule. </li></ul><p><strong>Types</strong></p><ul><li>Public Sector Banks </li><li>Private Banks </li><li>Foreign Banks </li><li>Cooperative Banks </li><li>RRBs </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Monetary Policy Committee (MPC) ⭐</strong></p><p><strong>Formed</strong></p><ul><li>2016 </li></ul><p><strong>Members</strong></p><ul><li>6 members: </li><li>3 RBI </li><li>3 Government nominees </li></ul><p><strong>Function</strong></p><ul><li>Decides Repo Rate.&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>One-Line Exam Revision</strong></p><ul><li>RBI = Central Bank of India. </li><li>Repo Rate ↑ = Inflation ↓ </li><li>CRR ↑ = Liquidity ↓ </li><li>RBI established in 1935. </li><li>Monetary Policy Committee formed in 2016. </li><li>RBI controls inflation using monetary policy tools.</li></ul><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Monetary policy </li><li>Inflation control </li><li>Banking reforms </li></ul><p><strong>SSC / Banking / Railway</strong></p><ul><li>RBI full form </li><li>Repo rate </li><li>CRR &amp; SLR </li><li>Governor questions</li></ul><p><br></p><p><br></p>', '', 'ECONOMY & BANKING', '', '', NULL, 'active', 1, '2026-05-02 02:17:00', '2026-05-10 07:53:41', '2026-05-10 07:53:41');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(29, 'India adds 44.61 GW solar capacity in FY26 ', '', '<h2><strong>India adds 44.61 GW solar capacity in FY26</strong> </h2><p><br></p><ul><li>India expanded solar power generation in FY26 </li><li>Added 44.61 GW solar energy capacity </li><li>Boosts renewable and clean energy sector </li><li>Supports India’s green energy and climate goals</li></ul><p><br></p>', '', '<h2><strong>India adds 44.61 GW Solar Capacity in FY26 </strong></h2><p><br></p><p><strong>Overview</strong></p><ul><li>India added: </li><li><strong>44.61 GW (Gigawatt)</strong> solar power capacity in FY26. </li><li>Major boost to: </li><li>renewable energy </li><li>clean energy </li><li>green energy sector </li><li>Related Ministry: </li><li><strong>Ministry of New and Renewable Energy (MNRE)</strong> ⭐ </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Solar Energy? ⭐</strong></p><ul><li>Solar energy is energy obtained from: </li><li>sunlight. </li><li>It is converted into electricity using: </li><li>solar panels. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>How is Solar Power Generated? ⭐</strong></p><p><strong>Step-by-Step Process</strong></p><ol><li>Sunlight falls on: </li></ol><ul><li>solar panels. </li></ul><ol><li>Solar cells absorb sunlight. </li><li>Solar cells convert sunlight into: </li></ol><ul><li>electrical energy. </li></ul><ol><li>Electricity is supplied to: </li></ol><ul><li>homes </li><li>industries </li><li>power grids. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What are Solar Panels Made Of? ⭐</strong></p><ul><li>Mainly made from: </li><li><strong>Silicon</strong> ⭐ </li><li>Silicon is a semiconductor material. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Renewable Energy? ⭐</strong></p><ul><li>Energy obtained from natural sources that: </li><li>can be replenished naturally. </li></ul><p>Examples:</p><ul><li>Solar energy </li><li>Wind energy </li><li>Hydropower </li><li>Biomass </li><li>Geothermal energy </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Clean Energy? ⭐</strong></p><ul><li>Energy sources that produce: </li><li>very low pollution </li><li>low carbon emissions. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Green Energy? ⭐</strong></p><ul><li>Environment-friendly energy produced from: </li><li>natural renewable resources. </li></ul><p>Goal:</p><ul><li>reduce climate change and pollution.&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><strong>India’s Major Green Energy Plans ⭐</strong></p><p><strong>1. National Solar Mission ⭐</strong></p><ul><li>Launched under: </li><li>National Action Plan on Climate Change. </li></ul><p>Goal:</p><ul><li>increase solar power generation. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>2. PM-KUSUM Scheme ⭐</strong></p><ul><li>Solar pumps for farmers. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>3. Green Hydrogen Mission ⭐</strong></p><ul><li>Promote green hydrogen fuel production. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>4. International Solar Alliance (ISA) ⭐</strong></p><ul><li>Global solar energy initiative led by: </li><li>India and France. </li></ul><p>Headquarters:</p><ul><li>Gurugram, Haryana </li></ul><p class=\"ql-align-center\"><br></p><p><strong>5. Renewable Energy Target ⭐</strong></p><p>India aims for:</p><ul><li><strong>500 GW non-fossil fuel energy capacity by 2030</strong>. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Solar Energy ⭐</strong></p><p><strong>Environmental Benefits</strong></p><ul><li>Reduces pollution </li><li>Reduces greenhouse gases </li><li>Helps fight climate change </li></ul><p><strong>Economic Benefits</strong></p><ul><li>Reduces fuel imports </li><li>Creates jobs </li><li>Attracts investment </li></ul><p><strong>Social Benefits</strong></p><ul><li>Electricity in rural areas </li><li>Lower electricity costs </li><li>Sustainable development </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why is Solar Energy Important for India? ⭐</strong></p><p>India receives:</p><ul><li>abundant sunlight throughout the year. </li></ul><p>Helps:</p><ul><li>reduce coal dependence </li><li>improve energy security </li><li>support clean energy transition </li></ul><p class=\"ql-align-center\"><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Climate change </li><li>Renewable energy </li><li>Sustainable development </li></ul><p><strong>SSC / Banking / Railway</strong></p><ul><li>Solar mission </li><li>Renewable energy sources </li><li>ISA headquarters&nbsp;</li></ul><p><br></p><p><br></p><p><br></p><p><br></p>', '', 'ECONOMY & BANKING', '', '', NULL, 'active', 1, '2026-05-02 02:24:00', '2026-05-10 07:59:08', '2026-05-10 07:59:08');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(30, 'FPO sustainability report released by NAAS ', '', '<h2><strong>FPO sustainability report released by NAAS </strong></h2><p><strong>﻿</strong></p><ul><li><strong>Released by National Academy of Agricultural Sciences (NAAS) </strong></li><li><strong>Report highlights sustainability challenges in FPOs </strong></li><li><strong>Around 70% Farmer Producer Organisations face operational and financial difficulties </strong></li><li><strong>Focus on improving rural agriculture and farmer support systems</strong></li></ul>', '', '<h2><strong>FPO Sustainability Report released by NAAS </strong></h2><p><br></p><p><strong>Overview</strong></p><ul><li><strong>National Academy of Agricultural Sciences (NAAS)</strong> released a report on:</li><li>sustainability challenges of FPOs.</li><li>Report states:</li><li>around <strong>70% Farmer Producer Organisations (FPOs)</strong> face:</li><li>financial</li><li>operational</li><li>management-related challenges.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is FPO? ⭐</strong></p><ul><li><strong>FPO</strong> stands for:</li><li><strong>Farmer Producer Organisation</strong></li><li>It is a group formed by:</li><li>farmers</li><li>to work collectively for:</li><li>production</li><li>marketing</li><li>storage</li><li>selling agricultural products.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of FPOs ⭐</strong></p><ul><li>Improve farmers’ income.</li><li>Reduce middlemen involvement.</li><li>Increase bargaining power of farmers.</li><li>Provide better access to:</li><li>markets</li><li>technology</li><li>loans</li><li>fertilizers</li><li>seeds</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Sustainability? ⭐</strong></p><ul><li>Sustainability means:</li><li>ability to continue functioning successfully for a long time.</li></ul><p>For FPOs:</p><ul><li>financial stability</li><li>proper management</li><li>regular income</li><li>long-term operation</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Challenges faced by FPOs ⭐</strong></p><p><strong>Financial Problems</strong></p><ul><li>Lack of funding</li><li>Low profits</li></ul><p><strong>Management Issues</strong></p><ul><li>Weak business planning</li><li>Lack of skilled management</li></ul><p><strong>Market Challenges</strong></p><ul><li>Difficulty in selling products</li><li>Competition in markets</li></ul><p><strong>Infrastructure Problems</strong></p><ul><li>Poor storage and transport facilities</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is NAAS? ⭐</strong></p><ul><li><strong>NAAS</strong> stands for:</li><li><strong>National Academy of Agricultural Sciences</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><ul><li><strong>New Delhi</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Role of NAAS ⭐</strong></p><ul><li>Promotes:</li><li>agricultural research</li><li>scientific farming</li><li>policy recommendations</li><li>rural development</li><li>Provides advice related to:</li><li>agriculture</li><li>food security</li><li>sustainability</li></ul><p class=\"ql-align-center\"><br></p><p><strong>How do FPOs improve Rural Agriculture? ⭐</strong></p><p><strong>1. Better Market Access</strong></p><ul><li>Farmers can sell products collectively at better prices.</li></ul><p><strong>2. Reduced Costs</strong></p><ul><li>Shared purchase of:</li><li>seeds</li><li>fertilizers</li><li>machinery</li></ul><p><strong>3. Increased Income</strong></p><ul><li>Farmers get higher profits.</li></ul><p><strong>4. Rural Employment</strong></p><ul><li>Creates jobs in villages.</li></ul><p><strong>5. Modern Farming</strong></p><ul><li>Encourages scientific and digital farming methods.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Government Support for FPOs ⭐</strong></p><ul><li>Government launched:</li><li><strong>Scheme for Formation and Promotion of 10,000 FPOs</strong> ⭐</li></ul><p>Goal:</p><ul><li>strengthen farmer collectives and agriculture economy.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Strong FPOs ⭐</strong></p><p><strong>For Farmers</strong></p><ul><li>Better income</li><li>Stronger bargaining power</li><li>Easy access to credit</li></ul><p><strong>For Agriculture Sector</strong></p><ul><li>Organized farming system</li><li>Improved productivity</li><li>Better supply chains</li></ul><p><strong>For Economy</strong></p><ul><li>Rural development</li><li>Employment generation</li><li>Food security&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Agriculture reforms</li><li>Rural economy</li><li>Farmer welfare</li></ul><p><strong>SSC / Banking / Railway</strong></p><ul><li>Full forms</li><li>Agriculture schemes</li><li>Rural development</li></ul><p><br></p>', '', 'ECONOMY & BANKING, SCHEMES & GOVT. POLICIES, REPORTS & INDEXES', '', '', NULL, 'active', 1, '2026-05-01 15:30:00', '2026-05-10 08:04:07', '2026-05-11 15:51:24');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(31, 'AI investments continue driving startup growth ', '', '<h2><strong>AI investments continue driving startup growth</strong> </h2><p><br></p><ul><li>Rising investments in Artificial Intelligence sector </li><li>Boosting startup ecosystem and innovation </li><li>Expanding digital economy and technology development </li><li>Creating new jobs and business opportunities</li></ul><p><br></p>', '', '<h2><strong>AI investments continue driving Startup Growth </strong></h2><p><br></p><p><strong>What is AI? ⭐</strong></p><ul><li><strong>AI</strong> stands for: </li><li><strong>Artificial Intelligence</strong> </li><li>AI is a technology that enables machines and computers to: </li><li>think </li><li>learn </li><li>analyze data </li><li>solve problems </li><li>make decisions like humans. </li></ul><p>Examples:</p><ul><li>Chatbots </li><li>Voice assistants </li><li>Face recognition </li><li>Self-driving systems </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Father of AI ⭐</strong></p><ul><li><strong>John McCarthy</strong> is known as: </li><li>“Father of Artificial Intelligence” </li><li>He coined the term: </li><li><strong>Artificial Intelligence</strong></li><li> in: </li><li><strong>1956</strong> ⭐ </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why are governments and companies investing in AI? ⭐</strong></p><p><strong>1. Fast Technology Growth</strong></p><ul><li>AI improves: </li><li>automation </li><li>digital services </li><li>productivity </li></ul><p class=\"ql-align-center\"><br></p><p><strong>2. Economic Growth</strong></p><ul><li>AI is becoming a major part of: </li><li>digital economy </li><li>global business </li><li>future industries </li></ul><p class=\"ql-align-center\"><br></p><p><strong>3. Global Competition</strong></p><p>Countries are competing in:</p><ul><li>AI research </li><li>semiconductor technology </li><li>robotics </li><li>digital innovation </li></ul><p class=\"ql-align-center\"><br></p><p><strong>4. Better Public Services</strong></p><p>AI helps improve:</p><ul><li>healthcare </li><li>education </li><li>banking </li><li>governance </li><li>transport </li></ul><p class=\"ql-align-center\"><br></p><p><strong>How AI boosts Startup Ecosystem &amp; Innovation ⭐</strong></p><p><strong>What is a Startup? ⭐</strong></p><ul><li>A startup is: </li><li>a newly established innovative business company. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>AI Helps Startups By ⭐</strong></p><p><strong>1. Faster Work</strong></p><ul><li>AI automates repetitive tasks. </li></ul><p><strong>2. Better Data Analysis</strong></p><ul><li>Helps companies make smart decisions. </li></ul><p><strong>3. Innovation</strong></p><ul><li>AI enables: </li><li>new apps </li><li>robotics </li><li>fintech </li><li>health-tech </li><li>ed-tech solutions </li></ul><p><strong>4. Lower Costs</strong></p><ul><li>Automation reduces operational expenses. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>How AI creates Jobs &amp; Business Opportunities ⭐</strong></p><p><strong>New Job Sectors Created ⭐</strong></p><p>AI creates jobs in:</p><ul><li>software development </li><li>data science </li><li>cybersecurity </li><li>AI engineering </li><li>robotics </li><li>digital marketing </li><li>cloud computing </li></ul><p class=\"ql-align-center\"><br></p><p><strong>AI Creates New Industries ⭐</strong></p><p>Examples:</p><ul><li>AI healthcare </li><li>autonomous vehicles </li><li>smart agriculture </li><li>fintech </li><li>AI-based education </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Skill-Based Employment ⭐</strong></p><p>Demand increasing for:</p><ul><li>coding </li><li>machine learning </li><li>data analysis </li><li>digital management </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Will AI destroy Human Jobs? ⭐</strong></p><p><strong>Yes — Some Traditional Jobs May Reduce</strong></p><p>AI may replace:</p><ul><li>repetitive manual work </li><li>basic data-entry jobs </li><li>simple automation tasks </li></ul><p class=\"ql-align-center\"><br></p><p><strong>But AI Also Creates New Jobs ⭐</strong></p><p>Historically:</p><ul><li>new technologies replace some jobs </li><li>but create new industries and employment opportunities. </li></ul><p>Example:</p><ul><li>computers replaced typewriters </li><li>but created IT industry jobs. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Is AI Dangerous to Humans? ⭐</strong></p><p><strong>Risks of AI ⭐</strong></p><ul><li>Cybercrime </li><li>Privacy concerns </li><li>Deepfake misuse </li><li>Job displacement </li><li>Overdependence on machines </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Safe Use of AI ⭐</strong></p><p>Governments focus on:</p><ul><li>ethical AI </li><li>AI regulations </li><li>human supervision </li><li>cybersecurity laws&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>India AI Mission ⭐</strong></p><ul><li>Government initiative to: </li><li>develop AI ecosystem in India. </li><li>Focus: </li><li>computing infrastructure </li><li>startups </li><li>AI education </li><li>innovation </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of AI Investments ⭐</strong></p><p><strong>For Economy</strong></p><ul><li>Economic growth </li><li>Digital transformation </li><li>Startup expansion </li></ul><p><strong>For Society</strong></p><ul><li>Better healthcare </li><li>Faster services </li><li>Smart governance </li></ul><p><strong>For Youth</strong></p><ul><li>High-paying technology jobs </li><li>Innovation opportunities </li></ul><p class=\"ql-align-center\"><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Science &amp; Technology </li><li>AI ethics </li><li>Digital economy </li></ul><p><strong>SSC / Banking / Railway</strong></p><ul><li>AI full form </li><li>Father of AI </li><li>AI applications</li></ul><p><br></p><p><br></p><p><br></p><p><br></p>', '', 'SCIENCE & TECHNOLOGY', '', '', NULL, 'active', 1, '2026-05-02 02:36:00', '2026-05-10 08:10:45', '2026-05-10 08:10:45');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(32, ' ISRO advances Gaganyaan mission preparations', '', '<h2><br></h2><h2><strong>ISRO advances Gaganyaan mission preparations</strong></h2><p><strong><span class=\"ql-cursor\">﻿</span></strong></p><ul><li>ISRO achieved new test milestones for Gaganyaan mission </li><li>India’s first human spaceflight programme </li><li>Focus on astronaut safety and space technology </li><li>Aims to send Indian astronauts into space orbit</li></ul><p><br></p>', '', '<h2><strong>ISRO advances Gaganyaan Mission Preparations </strong></h2><p><br></p><p><strong>What is ISRO? ⭐</strong></p><ul><li><strong>ISRO</strong> stands for: </li><li><strong>Indian Space Research Organisation</strong> </li><li>It is India’s national space agency. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Established ⭐</strong></p><ul><li>Founded in: </li><li><strong>1969</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><ul><li><strong>Bengaluru, Karnataka</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Under Which Ministry? ⭐</strong></p><ul><li>Works under: </li><li><strong>Department of Space</strong> </li><li>Government of India </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Father of Indian Space Programme ⭐</strong></p><ul><li><strong>Dr. Vikram Sarabhai</strong> ⭐ </li><li>Known as: </li><li>“Father of Indian Space Programme” </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Current ISRO Chairman ⭐</strong></p><ul><li><strong>V. Narayanan</strong> <em>(2026)</em> </li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Main Functions of ISRO ⭐</strong></p><ul><li>Satellite launches </li><li>Space exploration </li><li>Communication technology </li><li>Weather forecasting </li><li>Navigation systems </li><li>Scientific research&nbsp;</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Major Successes of ISRO ⭐</strong></p><p><strong>Chandrayaan-3 ⭐</strong></p><ul><li>India became: </li><li>first country to land near Moon’s south pole. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Mangalyaan ⭐</strong></p><ul><li>India became first Asian nation to reach Mars orbit successfully. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>PSLV Success ⭐</strong></p><ul><li>Highly reliable satellite launch vehicle. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Aditya-L1 ⭐</strong></p><ul><li>India’s first solar mission. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Major Challenges / Unsuccessful Missions ⭐</strong></p><p><strong>Chandrayaan-2 (2019)</strong></p><ul><li>Vikram lander lost communication during landing. </li><li>Orbiter remains successful. </li></ul><p><strong>Early Rocket Failures</strong></p><ul><li>Some launch failures during initial development years. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Gaganyaan Mission? ⭐</strong></p><ul><li>India’s: </li><li><strong>first human spaceflight mission</strong> ⭐ </li><li>Aim: </li><li>send Indian astronauts (Vyomanauts) into space orbit. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Objectives of Gaganyaan ⭐</strong></p><ul><li>Demonstrate human spaceflight capability. </li><li>Develop: </li><li>crew module </li><li>astronaut safety systems </li><li>space technology&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What are “Test Milestones”? ⭐</strong></p><p>ISRO conducts tests for:</p><ul><li>crew escape system </li><li>rocket systems </li><li>safety modules </li><li>astronaut survival systems </li></ul><p>These are important before human launch.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Gaganyaan Mission ⭐</strong></p><p><strong>Scientific Benefits</strong></p><ul><li>Space technology advancement </li></ul><p><strong>Strategic Benefits</strong></p><ul><li>Strengthens India’s global space status </li></ul><p><strong>Economic Benefits</strong></p><ul><li>Growth of space industry and startups </li></ul><p><strong>Educational Benefits</strong></p><ul><li>Encourages science and innovation&nbsp;</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Space technology </li><li>Science &amp; Tech </li><li>Strategic capability </li></ul><p><strong>SSC / Railway / Banking</strong></p><ul><li>ISRO full form </li><li>Founder </li><li>Gaganyaan mission </li></ul><p>Chandrayaan facts&nbsp;</p><p><br></p><p><br></p>', '', 'SPACE & ASTRONOMY', '', '', NULL, 'active', 1, '2026-05-02 02:41:00', '2026-05-10 08:18:14', '2026-05-10 08:18:14');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(33, 'IMD issues El Niño Watch for 2026 ', '', '<p><br></p><p><br></p><h2><strong>IMD issues El Niño Watch for 2026</strong></h2><p><br></p><ul><li>Issued by <strong>India Meteorological Department (IMD)</strong></li><li>Monsoon forecast at <strong>94% of Long Period Average (LPA)</strong></li><li>Indicates possibility of El Niño conditions</li><li>May affect rainfall, agriculture and temperature patterns in India&nbsp;</li></ul>', '', '<h2><strong>IMD issues El Niño Watch for 2026 </strong></h2><p><br></p><p><strong>What is IMD? ⭐</strong></p><ul><li><strong>IMD</strong> stands for:</li><li><strong>India Meteorological Department</strong></li><li>It is India’s main weather forecasting agency.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Established ⭐</strong></p><ul><li>Established in:</li><li><strong>1875</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><ul><li><strong>New Delhi</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Ministry ⭐</strong></p><ul><li>Works under:</li><li><strong>Ministry of Earth Sciences</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Main Functions of IMD ⭐</strong></p><ul><li>Weather forecasting</li><li>Monsoon prediction</li><li>Cyclone warnings</li><li>Earthquake monitoring</li><li>Climate research</li><li>Heatwave and rainfall alerts</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is El Niño? ⭐</strong></p><ul><li><strong>El Niño</strong> is a climate phenomenon caused by:</li><li>unusual warming of Pacific Ocean surface waters near South America.</li><li>It affects:</li><li>global weather patterns</li><li>rainfall</li><li>temperature</li><li>monsoon systems</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Meaning of “El Niño” ⭐</strong></p><ul><li>Spanish term meaning:</li><li><strong>“Little Boy”</strong> or <strong>“Christ Child”</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is El Niño Watch? ⭐</strong></p><ul><li>An early warning issued when:</li><li>chances of El Niño conditions increase.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>How does El Niño affect India? ⭐</strong></p><p><strong>1. Weak Monsoon Rainfall ⭐</strong></p><ul><li>El Niño often weakens:</li><li>southwest monsoon winds.</li><li>May cause:</li><li>below-normal rainfall in India.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>2. Higher Temperatures ⭐</strong></p><ul><li>Leads to:</li><li>heatwaves</li><li>warmer climate conditions</li></ul><p class=\"ql-align-center\"><br></p><p><strong>3. Agriculture Impact ⭐</strong></p><ul><li>Less rainfall affects:</li><li>crop production</li><li>irrigation</li><li>food supply</li></ul><p>Crops affected:</p><ul><li>rice</li><li>wheat</li><li>sugarcane</li><li>pulses</li></ul><p class=\"ql-align-center\"><br></p><p><strong>4. Water Shortage ⭐</strong></p><ul><li>Lower rainfall reduces:</li><li>reservoir levels</li><li>groundwater availability</li></ul><p class=\"ql-align-center\"><br></p><p><strong>5. Economic Impact ⭐</strong></p><ul><li>Agriculture slowdown can affect:</li><li>rural income</li><li>food prices</li><li>inflation</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Monsoon? ⭐</strong></p><ul><li>Seasonal wind system bringing rainfall to India.</li><li>Southwest Monsoon occurs:</li><li>June to September.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is LPA (Long Period Average)? ⭐</strong></p><ul><li>Average monsoon rainfall calculated over many years.</li><li>Used by IMD to compare annual rainfall forecasts.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>94% of LPA Means ⭐</strong></p><ul><li>Rainfall expected slightly below normal.</li><li>Generally considered:</li><li>near-normal monsoon range.&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Climatology</li><li>Monsoon system</li><li>Disaster management</li></ul><p><strong>SSC / Railway / Banking</strong></p><ul><li>IMD full form</li><li>El Niño meaning</li><li>Weather-related GK&nbsp;</li></ul>', '', 'ENVIRONMENT, REPORTS & INDEXES', '', '', NULL, 'active', 1, '2026-05-01 23:16:00', '2026-05-10 10:20:38', '2026-05-11 15:56:04');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(34, 'CWMA directs Karnataka to release Cauvery water to Tamil Nadu ', '', '<p><br></p><h2><strong>CWMA directs Karnataka to release Cauvery water to Tamil Nadu</strong> </h2><p><br></p><ul><li>Ordered by <strong>Cauvery Water Management Authority (CWMA)</strong> </li><li>Karnataka directed to release <strong>2.5 TMC</strong> water to Tamil Nadu </li><li>Related to Cauvery river water-sharing dispute </li><li>Important for irrigation and agriculture needs</li></ul><p><br></p>', '', '<h2><strong>CWMA directs Karnataka to release Cauvery Water to Tamil Nadu </strong></h2><p><br></p><p><strong>What is CWMA? ⭐</strong></p><ul><li><strong>CWMA</strong> stands for: </li><li><strong>Cauvery Water Management Authority</strong> </li><li>It is an authority created to: </li><li>manage and regulate sharing of Cauvery river water among states. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Established ⭐</strong></p><ul><li>Established in: </li><li><strong>2018</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Formed By ⭐</strong></p><ul><li>Constituted by: </li><li>Government of India</li><li> following Supreme Court directions. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Ministry ⭐</strong></p><ul><li>Works under: </li><li><strong>Ministry of Jal Shakti</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><ul><li><strong>New Delhi</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Chairman of CWMA ⭐</strong></p><ul><li>Headed by: </li><li>a senior central government official appointed by Government of India. </li></ul><p><em>(Chairmanship may change periodically according to appointments.)</em></p><p class=\"ql-align-center\"><br></p><p><strong>Main Role of CWMA ⭐</strong></p><ul><li>Monitor Cauvery river water distribution. </li><li>Ensure states follow water-sharing orders. </li><li>Resolve interstate water disputes. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is the Cauvery Water Dispute? ⭐</strong></p><ul><li>A long-running river water dispute between: </li><li>Karnataka </li><li>Tamil Nadu</li><li> and also involving: </li><li>Kerala </li><li>Puducherry </li></ul><p>Main issue:</p><ul><li>sharing Cauvery river water for: </li><li>irrigation </li><li>drinking water </li><li>agriculture </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why was Karnataka directed to release 2.5 TMC water? ⭐</strong></p><ul><li>Tamil Nadu requested water for: </li><li>agriculture </li><li>irrigation needs. </li><li>CWMA ordered Karnataka to release: </li><li><strong>2.5 TMC water</strong> ⭐</li><li> according to water-sharing arrangements. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is TMC? ⭐</strong></p><ul><li><strong>TMC</strong> means: </li><li><strong>Thousand Million Cubic Feet</strong> </li><li>Unit used to measure large quantities of water. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance of Cauvery River ⭐</strong></p><p><strong>States Through Which It Flows</strong></p><ul><li>Karnataka </li><li>Tamil Nadu </li><li>Kerala </li><li>Puducherry </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Origin of Cauvery River ⭐</strong></p><ul><li>Originates at: </li><li><strong>Talakaveri</strong> </li><li>Kodagu district, Karnataka </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Where does it drain? ⭐</strong></p><ul><li>Empties into: </li><li><strong>Bay of Bengal</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Geographical Importance ⭐</strong></p><p><strong>Karnataka</strong></p><ul><li>Used for: </li><li>irrigation </li><li>reservoirs </li><li>drinking water </li></ul><p><strong>Tamil Nadu</strong></p><ul><li>Lifeline for: </li><li>delta agriculture </li><li>paddy cultivation </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Water Release ⭐</strong></p><p><strong>For Tamil Nadu</strong></p><ul><li>Supports farming and irrigation. </li><li>Protects crops during low rainfall periods. </li></ul><p><strong>For Agriculture</strong></p><ul><li>Maintains food production. </li><li>Supports rural economy. </li></ul><p><strong>For Interstate Coordination</strong></p><ul><li>Helps peaceful water management between states. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why is Cauvery River Important? ⭐</strong></p><p><strong>Agriculture</strong></p><ul><li>Major irrigation source. </li></ul><p><strong>Drinking Water</strong></p><ul><li>Supplies water to cities including: </li><li>Bengaluru </li></ul><p><strong>Hydropower</strong></p><ul><li>Supports electricity generation.&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Related Constitutional &amp; Legal Facts ⭐</strong></p><ul><li>Interstate river disputes handled under: </li><li><strong>Inter-State River Water Disputes Act, 1956</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Water disputes </li><li>Federalism </li><li>River geography </li></ul><p><strong>SSC / Railway / Banking</strong></p><ul><li>River origin </li><li>Full forms </li><li>Interstate disputes&nbsp;</li></ul><p><br></p><p><br></p><p><br></p>', '', 'ENVIRONMENT', '', '', NULL, 'active', 1, '2026-05-02 04:59:00', '2026-05-10 10:26:25', '2026-05-10 10:26:25');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(35, 'IPL 2026 playoff race intensifies ', '', '<h2><strong>IPL 2026 playoff race intensifies</strong> </h2><p><br></p><ul><li>Teams competing for top 4 positions in IPL 2026</li><li>Every match becoming important for playoff qualification</li><li>Net Run Rate (NRR) playing key role in standings</li><li>Strong competition among franchises for knockout stage entry</li></ul><p><br></p>', '', '<h2><strong>IPL 2026 Playoff Race Intensifies </strong></h2><p><br></p><p><strong>What is IPL? ⭐</strong></p><ul><li><strong>IPL</strong> stands for: </li><li><strong>Indian Premier League</strong> </li><li>It is: </li><li>India’s biggest professional T20 cricket league. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Started In ⭐</strong></p><ul><li>IPL started in: </li><li><strong>2008</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Founded By ⭐</strong></p><ul><li>Founded by: </li><li><strong>BCCI</strong> (Board of Control for Cricket in India) </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is BCCI? ⭐</strong></p><ul><li>Governing body of cricket in India. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Current IPL Chairman ⭐</strong></p><ul><li><strong>Arun Singh Dhumal</strong> <em>(2026)</em> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>IPL Brand Ambassadors ⭐</strong></p><ul><li>IPL usually appoints: </li><li>celebrities </li><li>actors </li><li>sports personalities</li><li> for promotions. </li><li>Brand ambassadors may change season-wise. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Format of IPL ⭐</strong></p><ul><li>Based on: </li><li><strong>T20 format</strong> </li><li>Each team plays: </li><li>20 overs. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>When does IPL occur? ⭐</strong></p><ul><li>Usually held: </li><li>every year </li><li>between March–May.&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>What is Playoff Race? ⭐</strong></p><ul><li>Teams compete to finish in: </li><li>top 4 positions</li><li> to qualify for: </li><li>playoffs.&nbsp;&nbsp;&nbsp;&nbsp;</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>What is NRR? ⭐</strong></p><ul><li><strong>NRR</strong> stands for: </li><li><strong>Net Run Rate</strong> </li><li>Used when teams have equal points.&nbsp;</li></ul><p><br></p><p><strong>Meaning of NRR ⭐</strong></p><ul><li>Measures team performance based on: </li><li>scoring speed </li><li>bowling efficiency. </li></ul><p>Higher NRR:</p><ul><li>better playoff chances. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Example of NRR ⭐</strong></p><ul><li>Team scoring quickly and restricting opponents gets: </li><li>positive NRR. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>IPL Playoff Format ⭐</strong></p><p><strong>1. Qualifier 1</strong></p><ul><li>Top 2 teams compete. </li></ul><p><strong>2. Eliminator</strong></p><ul><li>Teams ranked 3rd &amp; 4th compete. </li></ul><p><strong>3. Qualifier 2</strong></p><ul><li>Loser of Qualifier 1 vs Winner of Eliminator. </li></ul><p><strong>4. Final</strong></p><ul><li>Winners compete for trophy. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of IPL ⭐</strong></p><p><strong>For Cricket</strong></p><ul><li>Identifies young talent. </li><li>Improves Indian cricket standards. </li></ul><p><strong>For Economy</strong></p><ul><li>Tourism </li><li>Sponsorship </li><li>Advertising revenue </li></ul><p><strong>For Players</strong></p><ul><li>International exposure </li><li>High salaries&nbsp;</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>SSC / Railway / Banking</strong></p><ul><li>IPL full form </li><li>NRR full form </li><li>BCCI questions </li></ul><p><strong>UPSC</strong></p><ul><li>Sports administration </li><li>Sports economy</li></ul><p><br></p><p><br></p><p><br></p><p><br></p>', '', 'GAMES & SPORTS', '', '', NULL, 'active', 1, '2026-05-02 05:01:00', '2026-05-10 10:37:51', '2026-05-10 10:37:51');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(36, 'MyNRAI Athlete App launched ', '', '<h2 class=\"ql-align-center\"><strong>MyNRAI Athlete App launched</strong></h2><p><br></p><ul><li>Launched by <strong>National Rifle Association of India (NRAI)</strong></li><li>Digital app for shooting athletes and training support</li><li>Helps manage performance, events and communication</li><li>Promotes sports technology and athlete development</li></ul>', '', '<h2 class=\"ql-align-center\"><strong>MyNRAI Athlete App launched </strong></h2><p><br></p><p><strong>What is NRAI? ⭐</strong></p><ul><li><strong>NRAI</strong> stands for:</li><li><strong>National Rifle Association of India</strong></li><li>It is the national governing body for:</li><li>shooting sports in India.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Established ⭐</strong></p><ul><li>Founded in:</li><li><strong>1951</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><ul><li><strong>New Delhi</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Current President / Chairman ⭐</strong></p><ul><li><strong>Kalikesh Narayan Singh Deo</strong> <em>(2026)</em></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Main Role of NRAI ⭐</strong></p><ul><li>Organizes shooting competitions.</li><li>Selects Indian shooting teams.</li><li>Promotes shooting sports in India.</li><li>Provides athlete training and development.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Affiliated With ⭐</strong></p><ul><li>International Shooting Sport Federation (ISSF)</li><li>Indian Olympic Association (IOA)</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is MyNRAI Athlete App? ⭐</strong></p><ul><li>A digital platform launched for:</li><li>Indian shooting athletes</li><li>coaches</li><li>officials.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why was MyNRAI Athlete App launched? ⭐</strong></p><p><strong>Main Purpose ⭐</strong></p><ul><li>Modernize athlete management system.</li><li>Improve communication and training support.</li><li>Promote digital sports governance.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>How does the App help Athletes? ⭐</strong></p><p><strong>1. Performance Management</strong></p><ul><li>Tracks athlete:</li><li>scores</li><li>rankings</li><li>training progress</li></ul><p class=\"ql-align-center\"><br></p><p><strong>2. Event Management</strong></p><ul><li>Provides updates on:</li><li>tournaments</li><li>schedules</li><li>registrations</li></ul><p class=\"ql-align-center\"><br></p><p><strong>3. Communication System</strong></p><ul><li>Connects:</li><li>athletes</li><li>coaches</li><li>NRAI officials</li></ul><p class=\"ql-align-center\"><br></p><p><strong>4. Training Support</strong></p><ul><li>Shares:</li><li>training plans</li><li>performance analysis</li><li>practice information</li></ul><p class=\"ql-align-center\"><br></p><p><strong>5. Digital Record Keeping</strong></p><ul><li>Stores athlete profiles and competition data digitally.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of MyNRAI Athlete App ⭐</strong></p><p><strong>For Athletes</strong></p><ul><li>Faster access to information</li><li>Better performance tracking</li><li>Easy tournament updates</li></ul><p><strong>For Coaches</strong></p><ul><li>Monitor athlete development</li><li>Analyze performance data</li></ul><p><strong>For Sports Administration</strong></p><ul><li>Transparent management</li><li>Better coordination</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Importance of Shooting Sports in India ⭐</strong></p><p>India has won medals in:</p><ul><li>Olympics</li><li>Asian Games</li><li>Commonwealth Games</li></ul><p>Famous Indian shooters:</p><ul><li>Abhinav Bindra ⭐</li><li>Manu Bhaker</li><li>Gagan Narang&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>SSC / Railway / Banking</strong></p><ul><li>NRAI full form</li><li>Sports organizations</li><li>App launches</li></ul><p><strong>UPSC</strong></p><ul><li>Sports governance</li><li>Digital sports infrastructure</li></ul><p><br></p><p><br></p>', '', 'GAMES & SPORTS', '', '', NULL, 'active', 1, '2026-05-01 23:39:00', '2026-05-10 10:42:20', '2026-05-11 07:11:10'),
(37, 'MyNRAI Athlete App launched (UPDATED)', '', '<h2 class=\"ql-align-center\"><strong>MyNRAI Athlete App launched</strong></h2><p><br></p><ul><li>Launched by <strong>National Rifle Association of India (NRAI)</strong></li><li>Digital app for shooting athletes and training support</li><li>Helps manage performance, events and communication</li><li>Promotes sports technology and athlete development</li></ul>', '', '<p><strong>What is NRAI? ⭐</strong></p><p>The National Rifle Association of India (NRAI) is the national governing body responsible for managing and promoting shooting sports in India. It conducts national-level shooting competitions, selects Indian shooting teams for international events, and works for the development of shooting athletes across the country. NRAI also helps in improving sports infrastructure, athlete training, and international participation in shooting sports.</p><p><br></p><p><strong>Established ⭐</strong></p><p>The National Rifle Association of India was established in the year 1951. Since its formation, NRAI has played a major role in developing India’s shooting ecosystem and producing world-class shooters who have represented India in global competitions.</p><p><br></p><p><strong>Headquarters ⭐</strong></p><p>The headquarters of NRAI is located in New Delhi. From here, the organization manages national shooting activities, competitions, athlete coordination, and international sports relations.</p><p><strong>Current President / Chairman ⭐</strong></p><p>As of 2026, the President of NRAI is Kalikesh Narayan Singh Deo. Under his leadership, NRAI is focusing on modernization, athlete welfare, and digital sports governance.</p><p><br></p><p><strong>Main Role of NRAI ⭐</strong></p><p>The main responsibility of NRAI is to promote and regulate shooting sports in India. It organizes national shooting championships, selects athletes for international competitions such as the Olympics and Asian Games, and provides coaching, training, and development opportunities to shooters. NRAI also works to improve sports facilities and encourage young talent in shooting sports.</p><p><br></p><p><strong>Affiliated With ⭐</strong></p><p>NRAI is affiliated with the International Shooting Sport Federation (ISSF), which governs shooting sports at the international level. It is also associated with the Indian Olympic Association (IOA), which manages India’s participation in Olympic sports.</p><p><br></p><p><strong>What is MyNRAI Athlete App? ⭐</strong></p><p>The “MyNRAI Athlete App” is a digital platform launched by NRAI for Indian shooting athletes, coaches, and officials. The app is designed to improve athlete management, communication, training support, and performance tracking through digital technology.</p><p><br></p><p><strong>Why was MyNRAI Athlete App launched? ⭐</strong></p><p>The MyNRAI Athlete App was launched to modernize the athlete management system in Indian shooting sports. Its aim is to improve communication between athletes, coaches, and officials, provide better training support, and strengthen digital sports governance in India.</p><p><br></p><p><strong>How does the App help Athletes? ⭐</strong></p><p>The app helps athletes in multiple ways. It tracks athlete scores, rankings, and training progress for better performance management. It provides updates regarding tournaments, schedules, and registrations through an event management system. The app also creates smooth communication between athletes, coaches, and NRAI officials. In addition, it shares training plans, practice information, and performance analysis. The app also stores athlete profiles and competition records digitally for easy access and better management.</p><p><br></p><p><strong>Benefits of MyNRAI Athlete App ⭐</strong></p><p>The MyNRAI Athlete App provides several advantages for athletes, coaches, and sports administrators. Athletes get faster access to information, easier tournament updates, and better performance tracking. Coaches can monitor athlete development and analyze performance data effectively. For sports administration, the app improves transparency, coordination, and efficient management of shooting activities.</p><p><br></p><p><strong>Importance of Shooting Sports in India ⭐</strong></p><p>Shooting sports have become one of India’s strongest medal-winning sports at international events like the Olympics, Asian Games, and Commonwealth Games. Indian shooters have achieved global recognition through outstanding performances. Famous Indian shooters include Abhinav Bindra, who won India’s first individual Olympic gold medal, Manu Bhaker, and Gagan Narang, who have also brought glory to India in international competitions.</p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p>This topic is important for competitive examinations such as SSC, Railway, Banking, and UPSC. Questions may be asked about the full form of NRAI, sports organizations, headquarters, important app launches, digital sports governance, and India’s achievements in shooting sports.</p>', '', 'GAMES & SPORTS', '', '', NULL, 'active', 1, '2026-05-10 22:43:00', '2026-05-11 15:14:26', '2026-05-11 15:15:37');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(38, '16th Finance Commission recommends heatwaves as notified disaster ', '', '<h2><strong>16th Finance Commission recommends heatwaves as notified disaster</strong></h2><p><br></p><ul><li>Suggested including heatwaves under notified disasters category</li><li>May allow financial assistance from <strong>SDRF</strong> and <strong>NDRF</strong></li><li>Helps states manage rising extreme heat conditions</li><li>Supports disaster relief and climate adaptation measures</li></ul>', '', '<h2><strong>16th Finance Commission recommends Heatwaves as Notified Disaster </strong></h2><p><br></p><p><strong>What is Finance Commission? ⭐</strong></p><ul><li>Finance Commission is a constitutional body in India.</li><li>Formed under:</li><li><strong>Article 280</strong> of the Constitution.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of Finance Commission ⭐</strong></p><ul><li>Recommends distribution of:</li><li>taxes</li><li>financial resources</li><li>between:</li><li>Central Government</li><li>State Governments.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Established ⭐</strong></p><ul><li>First Finance Commission established in:</li><li><strong>1951</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Appointed By ⭐</strong></p><ul><li>President of India appoints the Finance Commission.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Current Finance Commission ⭐</strong></p><ul><li><strong>16th Finance Commission</strong> ⭐</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Chairman of 16th Finance Commission ⭐</strong></p><ul><li><strong>Dr. Arvind Panagariya</strong> ⭐</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Main Functions ⭐</strong></p><ul><li>Tax distribution recommendations</li><li>Grants-in-aid to states</li><li>Fiscal stability suggestions</li><li>Disaster funding recommendations</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is a Heatwave? ⭐</strong></p><ul><li>Heatwave means:</li><li>prolonged period of extremely high temperatures.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>IMD Heatwave Criteria ⭐</strong></p><p>Heatwave declared when:</p><ul><li>temperature becomes unusually high compared to normal levels.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Causes of Heatwaves ⭐</strong></p><p><strong>1. Climate Change ⭐</strong></p><ul><li>Rising global temperatures increase heat events.</li></ul><p><strong>2. Deforestation</strong></p><ul><li>Fewer trees increase surface heating.</li></ul><p><strong>3. Urbanization</strong></p><ul><li>Concrete cities trap heat.</li></ul><p><strong>4. Dry Weather Conditions</strong></p><ul><li>Lack of rainfall increases temperature.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Effects of Heatwaves ⭐</strong></p><p><strong>Human Health</strong></p><ul><li>Dehydration</li><li>Heatstroke</li><li>Deaths in severe cases</li></ul><p><strong>Agriculture</strong></p><ul><li>Crop damage</li><li>Water shortage</li></ul><p><strong>Environment</strong></p><ul><li>Forest fires</li><li>Drought conditions</li></ul><p><strong>Economy</strong></p><ul><li>Reduced productivity</li><li>Increased electricity demand</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why recommend Heatwaves as “Notified Disaster”? ⭐</strong></p><p>Currently:</p><ul><li>heatwaves are not fully included as major notified disasters under disaster relief funding.</li></ul><p>Recommendation aims to:</p><ul><li>provide financial support to affected states.</li><li>improve disaster response and relief.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Notified Disaster Status ⭐</strong></p><p><strong>Financial Assistance</strong></p><ul><li>States can receive disaster relief funds.</li></ul><p><strong>Better Preparedness</strong></p><ul><li>Improve emergency planning and response.</li></ul><p><strong>Public Safety</strong></p><ul><li>More awareness and protection measures.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is SDRF? ⭐</strong></p><ul><li><strong>SDRF</strong> stands for:</li><li><strong>State Disaster Response Fund</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of SDRF ⭐</strong></p><ul><li>Used by state governments for:</li><li>disaster relief operations</li><li>emergency response</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is NDRF? ⭐</strong></p><ul><li><strong>NDRF</strong> stands for:</li><li><strong>National Disaster Response Fund</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of NDRF ⭐</strong></p><ul><li>Central government fund for:</li><li>severe disaster management</li><li>relief assistance&nbsp;</li></ul><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Heatwave Precautions ⭐</strong></p><p><strong>Personal Safety</strong></p><ul><li>Drink more water</li><li>Avoid direct sunlight</li><li>Wear light clothes</li></ul><p><strong>Government Measures</strong></p><ul><li>Heat action plans</li><li>Cooling centers</li><li>Public advisories&nbsp;</li></ul><p><br></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Disaster management</li><li>Climate change</li><li>Constitutional bodies</li></ul><p><strong>SSC / Railway / Banking</strong></p><ul><li>Finance Commission</li><li>SDRF/NDRF full forms</li><li>Heatwave GK</li></ul><p><br></p><p><br></p>', '', 'POLITY & GOVERNANCE, COMMITTEE & COMMISSIONS', '', '', NULL, 'active', 1, '2026-05-02 04:33:00', '2026-05-11 15:37:30', '2026-05-11 15:57:48');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(39, 'Citizenship (Amendment) Rules, 2026 notified ', '', '<h2><strong>Citizenship (Amendment) Rules, 2026 notified </strong></h2><p><br></p><ul><li><strong>Government notified new citizenship amendment rules </strong></li><li><strong>Focus on citizenship application and documentation process </strong></li><li><strong>Implemented by Ministry of Home Affairs (MHA) </strong></li><li><strong>Aims to simplify and digitize citizenship procedures</strong></li></ul><p><br></p>', '', '<h2><strong>Citizenship (Amendment) Rules, 2026 notified </strong></h2><p><br></p><p><strong>What is an Amendment in Polity? ⭐</strong></p><ul><li>Amendment means: </li><li>making changes or modifications in: </li><li>Constitution </li><li>laws </li><li>rules </li><li>Acts. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Constitutional Amendment ⭐</strong></p><ul><li>Changes made in the Constitution are called: </li><li>Constitutional Amendments. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Article Related to Amendment ⭐</strong></p><ul><li><strong>Article 368</strong> ⭐ </li><li>Deals with: </li><li>amendment procedure of the Indian Constitution. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>How is an Amendment Passed? ⭐</strong></p><p><strong>Step 1</strong></p><ul><li>Bill introduced in: </li><li>Parliament. </li></ul><p><strong>Step 2</strong></p><ul><li>Passed by: </li><li>Lok Sabha </li><li>Rajya Sabha </li></ul><p><strong>Step 3</strong></p><ul><li>Sent to: </li><li>President of India </li></ul><p><strong>Step 4</strong></p><ul><li>After President’s assent: </li><li>becomes law. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is an Act? ⭐</strong></p><ul><li>A bill passed by Parliament and approved by the President becomes: </li><li>an <strong>Act</strong>. </li></ul><p>Example:</p><ul><li>Citizenship Act, 1955 </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What are Rules? ⭐</strong></p><ul><li>Rules are detailed procedures made to: </li><li>implement an Act properly. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Citizenship? ⭐</strong></p><ul><li>Citizenship means: </li><li>legal membership of a country. </li></ul><p>Citizens receive:</p><ul><li>legal rights </li><li>protection </li><li>voting rights </li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is Citizenship (Amendment) Rules, 2026? ⭐</strong></p><ul><li>New rules notified by: </li><li><strong>Ministry of Home Affairs (MHA)</strong> ⭐ </li><li>Related to: </li><li>citizenship application </li><li>documentation </li><li>digital processing system </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Purpose of Citizenship (Amendment) Rules ⭐</strong></p><p><strong>1. Simplify Procedures</strong></p><ul><li>Easier citizenship application process. </li></ul><p><strong>2. Digital System</strong></p><ul><li>Online documentation and processing. </li></ul><p><strong>3. Faster Verification</strong></p><ul><li>Improves administrative efficiency. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Related Act ⭐</strong></p><ul><li>Based on: </li><li><strong>Citizenship Act, 1955</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Criteria for Citizenship in India ⭐</strong></p><p>Indian citizenship can be acquired by:</p><p><strong>1. Birth ⭐</strong></p><ul><li>Person born in India under specified conditions. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>2. Descent ⭐</strong></p><ul><li>Citizenship through Indian parents. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>3. Registration ⭐</strong></p><ul><li>Foreign nationals can apply through registration. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>4. Naturalization ⭐</strong></p><ul><li>Citizenship granted after living in India for a specified period. </li></ul><p class=\"ql-align-center\"><br></p><p><strong>5. Incorporation of Territory ⭐</strong></p><p>If new territory becomes part of India.&nbsp;</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Ministry Responsible ⭐</strong></p><ul><li><strong>Ministry of Home Affairs (MHA)</strong> </li></ul><p class=\"ql-align-center\"><br></p><p><strong>Why are Citizenship Rules Important? ⭐</strong></p><p><strong>Administrative Efficiency</strong></p><ul><li>Faster processing of applications. </li></ul><p><strong>Transparency</strong></p><ul><li>Digital records improve transparency. </li></ul><p><strong>National Security</strong></p><ul><li>Proper verification of applicants.&nbsp;</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>UPSC</strong></p><ul><li>Polity </li><li>Citizenship provisions </li><li>Constitutional amendments </li></ul><p><strong>SSC / Railway / Banking</strong></p><ul><li>Article 368 </li><li>Citizenship methods </li><li>MHA-related questions</li></ul><p><br></p><p><br></p>', '', 'AMENDMENTS & BILLS', '', '', NULL, 'active', 1, '2026-05-02 10:08:00', '2026-05-11 15:44:14', '2026-05-11 15:44:14');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(40, 'India launches National Quantum Mission projects ', '', '<h2><strong>India launches National Quantum Mission projects</strong> </h2><p><br></p><ul><li>India started projects under National Quantum Mission </li><li>Focus on quantum computing and secure communication technology </li><li>Aims to strengthen advanced research and innovation </li><li>Supports future digital and cybersecurity infrastructure</li></ul><p><br></p>', '', '<p><strong>What is National Quantum Mission (NQM)? ⭐</strong></p><p>The National Quantum Mission (NQM) is a major initiative launched by the Government of India to promote the development of advanced quantum technologies in the country. The mission focuses on building India’s capabilities in quantum computing, quantum communication, quantum sensors, and quantum materials. It was approved by the Union Cabinet to strengthen India’s position in emerging technologies and improve scientific innovation, cybersecurity, and digital infrastructure.</p><p><strong>Launched In ⭐</strong></p><p>The National Quantum Mission was approved in the year 2023. It marked a major step by India toward entering the global race in quantum technology research and development.</p><p><strong>Implemented By ⭐</strong></p><p>The mission is being implemented by the Department of Science and Technology (DST), which works under the Government of India to promote scientific research and technological advancement.</p><p><strong>Mission Period ⭐</strong></p><p>The National Quantum Mission will run from 2023 to 2031. During this period, India aims to establish strong research infrastructure, technological innovation, and skilled human resources in the field of quantum science.</p><p><strong>Budget ⭐</strong></p><p>The Government of India has allocated a budget of around ₹6,000 crore for the National Quantum Mission. This large investment reflects the country’s commitment to becoming a global leader in advanced technologies.</p><p><strong>Main Objectives of NQM ⭐</strong></p><p>The primary objective of the National Quantum Mission is to develop advanced quantum technologies such as quantum computers, quantum communication systems, quantum sensors, and quantum materials. The mission also aims to strengthen cybersecurity, scientific research, innovation, and India’s digital infrastructure. Through this mission, India plans to reduce technological dependence on foreign countries and build indigenous capabilities.</p><p><strong>What is Quantum Computing? ⭐</strong></p><p>Quantum computing is an advanced form of computing based on the principles of quantum mechanics. Unlike traditional computers that use binary bits, quantum computers use “qubits” as the basic unit of information. Quantum computers are capable of processing highly complex calculations much faster than classical computers, making them useful for scientific research, artificial intelligence, defence, healthcare, and financial systems.</p><p><strong>What is a Qubit? ⭐</strong></p><p>A qubit is the basic unit of a quantum computer. In a normal computer, a bit can store either 0 or 1 at a time. However, a qubit can store both 0 and 1 simultaneously due to a special property called superposition. This ability allows quantum computers to process multiple calculations at the same time and achieve extremely high computational speed.</p><p><strong>Important Quantum Concepts ⭐</strong></p><p>Quantum computing is based on several important scientific concepts. The first concept is superposition, where a qubit can exist in multiple states at the same time. The second concept is entanglement, in which qubits remain interconnected even across long distances, allowing instant coordination between them. Another important concept is quantum tunneling, where quantum particles can pass through barriers that would normally block them in classical physics.</p><p><strong>Why are Quantum Computers Powerful? ⭐</strong></p><p>Quantum computers are considered extremely powerful because they can solve highly complex mathematical and scientific problems much faster than classical supercomputers. Problems that may take years for ordinary computers to solve can potentially be solved within minutes or seconds using quantum computing technology.</p><p><strong>Uses of Quantum Computing ⭐</strong></p><p>Quantum computing has applications in many important sectors. In cybersecurity, it helps create highly secure communication systems. In artificial intelligence, it enables faster data processing and advanced machine learning. In healthcare, it can support drug discovery and medical research. Quantum computing is also useful in weather forecasting and climate simulations. In defence and space technology, it can improve secure military communication systems. In banking and finance, it helps in fraud detection, risk analysis, and complex financial modeling.</p><p><strong>What is Quantum Communication? ⭐</strong></p><p>Quantum communication is a highly secure communication technology based on the principles of quantum physics. It uses quantum properties to transfer information in a way that is extremely difficult to hack or intercept. This technology is considered important for national security, banking systems, and secure digital communication networks.</p><p><strong>How does NQM strengthen Research &amp; Innovation? ⭐</strong></p><p>The National Quantum Mission encourages advanced scientific research and technological innovation in India. It supports deep-tech startups working in quantum technologies and creates opportunities for the growth of new industries. The mission also promotes skill development by increasing demand for quantum scientists, engineers, and researchers. In addition, it helps build next-generation cybersecurity systems for protecting digital infrastructure.</p><p><strong>Is Quantum Computing a Boon? ⭐</strong></p><p>Quantum computing offers several major advantages. It enables extremely fast calculations, improves cybersecurity systems, supports medical breakthroughs, strengthens scientific research, and enhances artificial intelligence technologies. Due to these benefits, quantum computing is considered one of the most transformative technologies of the future.</p><p><strong>Challenges / Risks ⭐</strong></p><p>Despite its advantages, quantum computing also faces several challenges. Quantum technology is highly expensive and requires advanced cooling systems and large amounts of power. The development process is very complex and technically difficult. There are also cybersecurity risks because powerful quantum computers could potentially break existing encryption systems if misused.</p><p><strong>Types of Quantum Computers ⭐</strong></p><p>There are different types of quantum computers based on the technology used. Superconducting quantum computers use electrical circuits to process quantum information. Trapped ion quantum computers use ions controlled by lasers. Photonic quantum computers use light particles called photons, while quantum annealers are mainly designed for solving optimization problems.</p><p><strong>Fastest Quantum Computers ⭐</strong></p><p>Several countries and companies are leading in quantum computing development. IBM has developed advanced quantum systems such as Condor. Google developed the Sycamore quantum processor. China developed Jiuzhang, while D-Wave Systems is known for its quantum annealers.</p><p><strong>Quantum Speed ⭐</strong></p><p>Quantum computers can solve certain problems millions of times faster than traditional supercomputers. Tasks that may require years for classical computers can sometimes be completed in seconds or minutes by advanced quantum systems due to parallel processing capabilities.</p><p><strong>India’s Quantum Goals ⭐</strong></p><p>India aims to become a global leader in quantum technology, advanced computing, and cybersecurity through the National Quantum Mission. The country plans to strengthen indigenous research, develop secure communication systems, and build a strong scientific workforce in quantum science and technology.</p><p><strong>Other Important Facts ⭐</strong></p><p>The mission is officially called the National Quantum Mission and was approved in 2023. It is implemented by the Department of Science and Technology. The basic unit of quantum computing is the qubit, while the most important feature of quantum technology is superposition. The mission mainly focuses on quantum computing and quantum communication technologies.</p><p><strong>Importance for Exams ⭐</strong></p><p>The National Quantum Mission is highly important for competitive examinations such as UPSC, SSC, Railway, and Banking exams. Questions may be asked about quantum computing, qubits, superposition, cybersecurity, scientific missions, emerging technologies, and government initiatives related to science and technology.</p>', '', 'NATIONAL AFFAIRS', '', '', NULL, 'active', 1, '2026-05-03 12:12:00', '2026-05-11 17:46:28', '2026-05-11 17:46:28'),
(41, 'Digital India expansion reviewed by MeitY ', '', '<h2><strong>Digital India expansion reviewed by MeitY</strong> </h2><p><br></p><ul><li>Ministry of Electronics and Information Technology (MeitY) reviewed Digital India progress </li><li>Focus on Artificial Intelligence and digital governance </li><li>Aims to improve online public services and digital infrastructure </li><li>Supports technology-driven administration and digital economy</li></ul><p><br></p>', '', '<p><strong>What is Digital India? ⭐</strong></p><p>Digital India is a flagship programme launched by the Government of India to transform the country into a digitally empowered society and knowledge economy. The programme focuses on improving digital infrastructure, increasing internet connectivity, promoting e-governance, and expanding digital services across urban and rural areas. It aims to make government services easily accessible to citizens through technology and strengthen India’s digital economy.</p><p><strong>Launched On ⭐</strong></p><p>Digital India was officially launched on 1 July 2015. The programme marked a major step toward modernizing governance, improving digital access, and encouraging technology-driven development in India.</p><p><strong>Launched By ⭐</strong></p><p>The Digital India programme was launched by Narendra Modi, the Prime Minister of India. The initiative was introduced to promote digital connectivity, transparent governance, and technological innovation across the country.</p><p><strong>Ministry Responsible ⭐</strong></p><p>The programme is managed by the Ministry of Electronics and Information Technology (MeitY). This ministry is responsible for implementing digital governance policies, promoting electronics and IT industries, and developing India’s digital infrastructure.</p><p><strong>Main Objectives of Digital India ⭐</strong></p><p>The main objective of Digital India is to create strong digital infrastructure throughout the country. This includes high-speed internet connectivity, digital identity systems, and mobile access for citizens. Another major objective is digital governance through online government services and e-governance systems. The programme also promotes digital empowerment by encouraging digital literacy, online education, and a cashless economy.</p><p><strong>Important Initiatives under Digital India ⭐</strong></p><p>Several important initiatives have been launched under Digital India. DigiLocker provides secure digital storage for official documents. Unified Payments Interface (UPI) supports fast digital payments and cashless transactions. BharatNet aims to provide broadband internet connectivity in rural areas. UMANG offers multiple government services through a single mobile application. Aadhaar provides digital identity to citizens, while e-Hospital supports online healthcare services and hospital management systems.</p><p><strong>What is MeitY? ⭐</strong></p><p>Ministry of Electronics and Information Technology (MeitY) stands for the Ministry of Electronics and Information Technology. It is the central government ministry responsible for promoting digital governance, electronics manufacturing, cybersecurity, internet policy, artificial intelligence, and the growth of India’s IT sector.</p><p><strong>Formation ⭐</strong></p><p>MeitY was formed in the year 2016 to strengthen India’s digital governance framework and improve the management of information technology and electronics-related activities.</p><p><strong>Headquarters ⭐</strong></p><p>The headquarters of MeitY is located in New Delhi. From there, the ministry coordinates national digital programmes and technology-related policies.</p><p><strong>Current Minister ⭐</strong></p><p>As of 2026, the Union Minister for MeitY is Ashwini Vaishnaw. He oversees India’s digital transformation initiatives, electronics sector development, and information technology policies.</p><p><strong>Main Functions of MeitY ⭐</strong></p><p>The Ministry of Electronics and Information Technology performs several important functions. It manages digital governance systems, promotes electronics manufacturing, strengthens cybersecurity, develops internet policies, supports artificial intelligence research, and encourages the growth of India’s IT and startup sectors.</p><p><strong>What is AI Technology? ⭐</strong></p><p>Artificial Intelligence, commonly known as AI, is a technology that enables machines and computer systems to think, learn, analyze information, and solve problems like humans. AI systems can process large amounts of data, recognize patterns, and make decisions with minimal human intervention.</p><p><strong>Father / Inventor of AI ⭐</strong></p><p>John McCarthy is known as the Father of Artificial Intelligence. He coined the term “Artificial Intelligence” in the year 1956 and played a major role in developing AI as a scientific field.</p><p><strong>Types of AI ⭐</strong></p><p>There are different types of Artificial Intelligence. Narrow AI is designed to perform specific tasks such as voice assistants or chatbots. General AI refers to advanced human-like intelligence capable of performing multiple tasks. Generative AI is used to create new content such as text, images, audio, and videos.</p><p><strong>Uses of AI ⭐</strong></p><p>Artificial Intelligence is widely used in many sectors. AI powers chatbots and virtual assistants, improves healthcare diagnostics, supports banking and fraud detection, strengthens cybersecurity systems, enhances online education, and helps in the development of self-driving vehicles and automation technologies.</p><p><strong>How Digital India improves Public Services? ⭐</strong></p><p>Digital India has significantly improved public services by enabling online access to certificates, licenses, banking services, and tax systems. It reduces paperwork and administrative delays through faster digital processing. Digital records improve transparency and help reduce corruption. Rural internet connectivity supports development in remote areas, while digital payment systems such as UPI and online banking promote a cashless economy.</p><p><strong>What is Digital Governance? ⭐</strong></p><p>Digital governance refers to the use of digital technology for government administration and public service delivery. It is also known as e-governance. Through digital governance, citizens can access government services more efficiently, transparently, and quickly using online platforms.</p><p><strong>Benefits of Digital India ⭐</strong></p><p>Digital India provides several economic, social, and administrative benefits. Economically, it promotes startup growth, IT sector expansion, and the development of the digital economy. Socially, it supports online education, telemedicine, and financial inclusion. Administratively, it improves citizen access to services and ensures faster service delivery through digital platforms.</p><p><strong>Challenges ⭐</strong></p><p>Despite its success, Digital India faces several challenges. Cybersecurity threats continue to increase with digital expansion. There is also a digital divide between urban and rural regions due to unequal internet access. Remote areas still face connectivity problems, while concerns regarding data privacy and digital security remain important issues.</p><p><strong>Other Important Facts ⭐</strong></p><p>Digital India was launched in 2015 and is managed by MeitY. The Ministry of Electronics and Information Technology was formed in 2016. John McCarthy is recognized as the Father of Artificial Intelligence. The main goal of Digital India is to achieve nationwide digital transformation and improve digital access for all citizens.</p><p><strong>Importance for Exams ⭐</strong></p><p>Digital India and MeitY are important topics for competitive examinations such as UPSC, SSC, Railway, and Banking exams. Questions are commonly asked about e-governance, digital economy, artificial intelligence, government schemes, important full forms, digital initiatives, and basic AI concepts.</p>', '', 'NATIONAL AFFAIRS', '', '', NULL, 'active', 1, '2026-05-03 12:17:00', '2026-05-11 17:51:33', '2026-05-11 17:51:33');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(42, 'NITI Aayog releases urban development roadmap ', '', '<h2><strong>NITI Aayog releases urban development roadmap</strong> </h2><p><br></p><ul><li>NITI Aayog released roadmap for urban development in India </li><li>Focus on smart cities and sustainable infrastructure </li><li>Aims to improve urban planning, transport and digital services </li></ul><p>Supports sustainable and technology-driven city development</p>', '', '<p><strong>NITI Aayog releases Urban Development Roadmap ⭐</strong></p><p><strong>What is NITI Aayog? ⭐</strong></p><p><strong>NITI Aayog stands for National Institution for Transforming India. It is India’s top public policy think tank that provides advice and strategic guidance to the Government of India on economic, social, and technological development. NITI Aayog focuses on innovation, sustainable growth, cooperative federalism, and long-term development planning for the country.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Established ⭐</strong></p><p><strong>NITI Aayog was formed on 1 January 2015 by the Government of India. It was established to create a modern and flexible policy-making institution that could better address India’s developmental challenges and opportunities.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Replaced ⭐</strong></p><p><strong>NITI Aayog replaced the Planning Commission, which earlier handled centralized economic planning in India. The new institution was introduced to encourage cooperative federalism and policy innovation.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Established By ⭐</strong></p><p><strong>NITI Aayog was established by the Government of India through an executive resolution. It was not created through a constitutional amendment or a parliamentary law.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Chairman of NITI Aayog ⭐</strong></p><p><strong>The Prime Minister of India serves as the Ex-officio Chairman of NITI Aayog. As of 2026, the Chairman is Narendra Modi.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Vice Chairman ⭐</strong></p><p><strong>The Vice Chairman of NITI Aayog is appointed by the Government of India. The Vice Chairman assists in policy-making, development planning, and coordination between the Centre and States.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Headquarters ⭐</strong></p><p><strong>The headquarters of NITI Aayog is located in New Delhi. From here, the organization coordinates development strategies and public policy initiatives for the nation.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Ministry ⭐</strong></p><p><strong>NITI Aayog works directly under the Government of India. It is not a constitutional body or a statutory body but functions as an executive body that advises the government on policy and development matters.</strong></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Main Functions of NITI Aayog ⭐</strong></p><p><strong>NITI Aayog advises the government on economic, social, and technological policies. It promotes cooperative federalism by encouraging coordination and partnership between the Central Government and State Governments. The institution also focuses on sustainable growth, innovation, and the expansion of the digital economy in India.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Cooperative Federalism ⭐</strong></p><p><strong>One of the major objectives of NITI Aayog is to strengthen cooperative federalism. It encourages better coordination between the Centre and States so that policies and development programmes can be implemented more effectively across the country.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Development Planning ⭐</strong></p><p><strong>NITI Aayog focuses on long-term development planning with emphasis on sustainable growth, innovation, and digital transformation. It works toward improving economic development and modernizing governance systems in India.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>What is Urban Development? ⭐</strong></p><p><strong>Urban development refers to the planned growth and improvement of cities and urban infrastructure. It includes the development of roads, transport systems, housing facilities, digital services, sanitation, and public utilities to improve urban living standards.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Why did NITI Aayog release Urban Development Roadmap? ⭐</strong></p><p><strong>NITI Aayog released the Urban Development Roadmap to improve city infrastructure, sustainability, and urban governance. The roadmap aims to help Indian cities manage rapid urbanization and ensure better quality of life for urban populations.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Growing Urban Population ⭐</strong></p><p><strong>India’s cities are rapidly expanding because of migration, industrialization, and economic growth. As more people move to urban areas for jobs and better opportunities, the demand for housing, transportation, and digital services continues to increase.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Need for Smart Cities ⭐</strong></p><p><strong>Modern cities require digital infrastructure, clean energy systems, and efficient transport networks to manage growing populations effectively. Smart city development helps improve urban administration, public services, and environmental sustainability.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>What are Smart Cities? ⭐</strong></p><p><strong>Smart cities are cities that use technology, digital systems, and modern infrastructure to improve urban living. These cities focus on better governance, efficient transportation, public safety, environmental protection, and improved citizen services.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Focus Areas of Urban Development Roadmap ⭐</strong></p><p><strong>The Urban Development Roadmap focuses on smart infrastructure such as roads, drainage systems, housing, and electricity supply. It also emphasizes urban transport through metro systems, electric buses, and traffic management. Digital services like e-governance, smart surveillance, and online citizen services are important focus areas. Sustainable development through green energy, waste management, and pollution reduction is also a major priority.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>How does it improve Urban Planning? ⭐</strong></p><p><strong>The roadmap improves urban planning through better land use and organized city expansion. Smart transport systems help reduce traffic congestion, while improved drainage systems and emergency planning strengthen disaster preparedness in urban areas.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>How does it improve Transport? ⭐</strong></p><p><strong>The Urban Development Roadmap supports the expansion of public transport systems such as metro rail and electric mobility. It also promotes AI-based traffic management systems to reduce congestion and improve transportation efficiency. Cleaner transport solutions further help in reducing pollution.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>How does it improve Digital Services? ⭐</strong></p><p><strong>The roadmap improves digital services by promoting online government services such as digital certificates, tax payments, and utility services. Smart governance systems increase administrative efficiency and monitoring, while CCTV and digital emergency systems improve public safety.</strong></p><p class=\"ql-align-center\"><strong>  </strong></p><p><strong>Benefits of Urban Development Roadmap ⭐</strong></p><p><strong>The roadmap provides several economic, social, and environmental benefits. Economically, it supports investment growth, job creation, and business development. Socially, it improves living standards, healthcare access, and education services. Environmentally, it promotes cleaner cities and sustainable urban growth.</strong></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p><strong>For UPSC examinations, this topic is important for governance, urbanization, and public policy. For SSC, Railway, and Banking examinations, important areas include full forms, Smart Cities Mission, and important facts related to NITI Aayog and urban development policies.</strong></p><p><br></p>', '', 'NATIONAL AFFAIRS', '', '', NULL, 'active', 1, '2026-05-03 12:22:00', '2026-05-11 18:01:26', '2026-05-11 18:01:26');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(43, 'UN discusses global climate financing reforms ', '', '<h2><strong>UN discusses global climate financing reforms</strong> </h2><p><br></p><ul><li>United Nations held discussions on climate finance reforms </li><li>Developing countries demanded increased funding support </li><li>Focus on climate change adaptation and green development </li><li>Aims to help vulnerable nations manage climate challenges</li></ul><p><br></p>', '', '<p><strong>UN discusses Global Climate Financing Reforms ⭐</strong></p><p><strong>What is UN? ⭐</strong></p><p>The United Nations (UN) is the world’s largest international organization. It was created to promote international peace, security, cooperation, human rights, and sustainable development among nations across the world.</p><p class=\"ql-align-center\"><br></p><p><strong>Established ⭐</strong></p><p>The United Nations was founded on 24 October 1945 after the end of the Second World War. The organization was established to prevent future global conflicts and strengthen international cooperation.</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><p>The headquarters of the United Nations is located in New York City. Major meetings, international discussions, and global policy decisions are coordinated from there.</p><p class=\"ql-align-center\"><br></p><p><strong>Purpose of UN ⭐</strong></p><p>The main purpose of the United Nations is to maintain international peace and security. It also works to improve cooperation between countries, promote sustainable development, protect human rights, and support humanitarian assistance during global crises.</p><p class=\"ql-align-center\"><br></p><p><strong>Members ⭐</strong></p><p>The United Nations currently has 193 member countries. Almost every internationally recognized country in the world is a member of the organization.</p><p class=\"ql-align-center\"><br></p><p><strong>Current UN Secretary-General ⭐</strong></p><p>As of 2026, the Secretary-General of the United Nations is António Guterres from Portugal. The UN is led by the Secretary-General and does not have a chairman.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Climate Finance? ⭐</strong></p><p>Climate finance refers to financial support provided for climate change mitigation, adaptation, and green development. These funds help countries reduce greenhouse gas emissions, strengthen climate resilience, and promote sustainable development projects.</p><p class=\"ql-align-center\"><br></p><p><strong>What are Global Climate Financing Reforms? ⭐</strong></p><p>Global Climate Financing Reforms refer to proposed changes in international climate funding systems. The main goal is to provide greater financial support to developing countries so that they can effectively fight climate change and transition toward cleaner and sustainable development.</p><p class=\"ql-align-center\"><br></p><p><strong>Why are Climate Financing Reforms Needed? ⭐</strong></p><p>Climate financing reforms are needed because climate change impacts are increasing rapidly across the world. Countries are facing floods, droughts, cyclones, heatwaves, and rising sea levels. Developing nations require large amounts of financial support to build renewable energy systems, clean transport networks, and sustainable infrastructure.</p><p class=\"ql-align-center\"><br></p><p><strong>Climate Inequality ⭐</strong></p><p>Climate inequality is another major reason for demanding reforms. Developed countries historically produced most greenhouse gas emissions through industrialization, while poorer nations contributed much less but continue to suffer severe climate impacts. Therefore, developing countries demand fair financial support from richer nations.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Green Development? ⭐</strong></p><p>Green development refers to economic growth that protects the environment, reduces pollution, and promotes the use of clean and renewable energy sources. It aims to balance economic progress with environmental sustainability.</p><p class=\"ql-align-center\"><br></p><p><strong>Examples of Green Development ⭐</strong></p><p>Examples of green development include solar energy projects, electric vehicles, sustainable cities, green buildings, and renewable energy infrastructure. These initiatives help reduce pollution and support long-term environmental protection.</p><p class=\"ql-align-center\"><br></p><p><strong>What are Climate Challenges? ⭐</strong></p><p>Climate challenges are mainly caused by greenhouse gas emissions from burning coal, oil, and natural gas. Deforestation increases carbon dioxide levels in the atmosphere, while industrial pollution releases harmful gases. Rapid urbanization also increases pollution and puts pressure on natural resources.</p><p class=\"ql-align-center\"><br></p><p><strong>Effects of Climate Challenges ⭐</strong></p><p>Climate change creates serious environmental, economic, and social problems. Environmental impacts include global warming, glacier melting, and biodiversity loss. Agriculture faces crop damage and water shortages. Human health suffers from heat stress and climate-related diseases. Economically, countries experience infrastructure damage and major disaster-related losses.</p><p class=\"ql-align-center\"><br></p><p><strong>Which Developing Countries demand More Funding? ⭐</strong></p><p>Many developing countries and groups demand greater climate funding support. Major countries include India, Brazil, South Africa, and Indonesia. African nations and Small Island countries are also demanding increased climate finance because they are highly vulnerable to climate change impacts.</p><p class=\"ql-align-center\"><br></p><p><strong>Why do Developing Countries demand Funding? ⭐</strong></p><p>Developing countries require funding for climate adaptation measures such as climate-resistant agriculture, flood protection systems, and disaster management infrastructure. They also need financial support to shift from fossil fuels to renewable energy and gain access to clean technology and innovation.</p><p class=\"ql-align-center\"><br></p><p><strong>How do they demand Support? ⭐</strong></p><p>Developing countries demand climate support mainly through UN climate conferences and international negotiations. Important platforms include COP summits and UN climate negotiations. They also use global alliances such as the G77 group, BRICS, and Global South partnerships to strengthen their demands.</p><p class=\"ql-align-center\"><br></p><p><strong>What is COP? ⭐</strong></p><p>COP stands for Conference of Parties under the United Nations Framework Convention on Climate Change (UNFCCC). COP meetings are annual international climate conferences where countries discuss climate policies, emission reductions, and financial commitments.</p><p class=\"ql-align-center\"><br></p><p><strong>Paris Agreement ⭐</strong></p><p>The Paris Agreement is a global climate agreement signed in 2015 under the UN framework. Its main goal is to limit global warming and strengthen international cooperation against climate change.</p><p class=\"ql-align-center\"><br></p><p><strong>Climate Finance Target ⭐</strong></p><p>Developed countries promised to provide $100 billion annually to developing nations for climate action, green development, and adaptation projects. This funding commitment is an important part of global climate negotiations.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p>This topic is highly important for competitive examinations such as UPSC, SSC, Banking, and Railway exams. For UPSC, important areas include climate governance, international relations, and sustainable development. For SSC, Banking, and Railway exams, questions may be asked about UN facts, climate finance, green development, and important international agreements.</p><p><br></p>', '', 'INTERNATIONAL AFFAIRS', '', '', NULL, 'active', 1, '2026-05-03 12:32:00', '2026-05-11 18:08:24', '2026-05-11 18:08:24');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(44, 'India participates in Indo-Pacific security dialogue ', '', '<h2><strong>India participates in Indo-Pacific security dialogue</strong> </h2><p><br></p><ul><li>India joined Indo-Pacific security discussions </li><li>Focus on maritime cooperation and regional security </li><li>Topics included sea trade routes and strategic stability </li><li>Strengthens international defence and diplomatic partnerships</li></ul><p><br></p>', '', '<p><strong>India participates in Indo-Pacific Security Dialogue ⭐</strong></p><p><strong>What is Indo-Pacific? ⭐</strong></p><p>The Indo-Pacific is a major strategic and geographical region that includes the Indian Ocean and the Pacific Ocean. This region connects Asia, Africa, Australia, and Pacific countries through important maritime routes and trade networks. The Indo-Pacific has become one of the world’s most important geopolitical and economic regions.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is Indo-Pacific Important? ⭐</strong></p><p>The Indo-Pacific region is important because a major part of global sea trade passes through this area. It is strategically significant for defence, naval security, and energy transportation. The region is also economically important because it includes some of the world’s largest economies such as India, China, Japan, and the United States.</p><p class=\"ql-align-center\"><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Important Sea Routes ⭐</strong></p><p>Important sea routes in the Indo-Pacific region include the Strait of Malacca, the South China Sea, and Indian Ocean trade routes. These sea lanes are extremely important for oil transportation, international shipping, and global trade activities.</p><p class=\"ql-align-center\"><br></p><p><strong>Why does India participate in Indo-Pacific Security Dialogue? ⭐</strong></p><p>India participates in the Indo-Pacific Security Dialogue to strengthen maritime security and protect important sea trade routes. The dialogue also helps India maintain strategic balance in the region and counter emerging regional threats. Participation supports India’s economic interests by securing energy imports and exports. It also strengthens defence and diplomatic relations with partner countries in the Indo-Pacific region.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Maritime Cooperation? ⭐</strong></p><p>Maritime cooperation refers to collaboration among countries for naval security, anti-piracy operations, disaster response, and safe sea trade. Countries work together to ensure secure shipping routes, maintain peace in international waters, and respond effectively to maritime emergencies.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>What is QUAD? ⭐</strong></p><p>The Quadrilateral Security Dialogue (QUAD) is a strategic partnership involving India, the United States, Japan, and Australia. The group focuses on maintaining a free, open, and inclusive Indo-Pacific region while promoting maritime security, economic cooperation, and regional stability.</p><p class=\"ql-align-center\"><br></p><p><strong>How does Indo-Pacific Dialogue strengthen Defence Partnerships? ⭐</strong></p><p>The Indo-Pacific Dialogue strengthens defence partnerships through joint naval exercises such as the Malabar Exercise. Countries also cooperate in defence technology areas including cybersecurity, maritime surveillance, and AI-based defence systems. Intelligence sharing among partner nations further improves regional security and strategic coordination.</p><p class=\"ql-align-center\"><br></p><p><strong>How does it strengthen Diplomatic Partnerships? ⭐</strong></p><p>The Indo-Pacific Dialogue improves diplomatic partnerships through economic cooperation, trade agreements, and supply chain partnerships. Countries also coordinate on regional peace and stability issues. In addition, they cooperate in disaster management and provide humanitarian and emergency assistance during crises.</p><p class=\"ql-align-center\"><br></p><p><strong>Challenges in Indo-Pacific Region ⭐</strong></p><p>The Indo-Pacific region faces several challenges including territorial disputes in the South China Sea, piracy threats to shipping routes, and geopolitical competition among major global powers. These challenges increase strategic tensions and require greater international cooperation for maintaining regional stability.</p><p class=\"ql-align-center\"><br></p><p><strong>India’s Indo-Pacific Vision ⭐</strong></p><p>India supports a free, open, inclusive, and rules-based Indo-Pacific region. India’s vision focuses on maritime security, peaceful cooperation, international law, freedom of navigation, and sustainable regional development.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p>This topic is highly important for competitive examinations such as UPSC, SSC, Railway, and Banking exams. For UPSC, important areas include international relations, maritime security, and Indo-Pacific strategy. For SSC, Railway, and Banking exams, questions may be asked about QUAD members, capitals, currencies, international organizations, and important maritime groups.</p><p><br></p><p class=\"ql-align-center\"><br></p><p><br></p>', '', 'INTERNATIONAL AFFAIRS', '', '', NULL, 'active', 1, '2026-05-03 12:39:00', '2026-05-11 18:15:15', '2026-05-11 18:15:15');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(45, 'RBI reviews digital lending regulations ', '', '<p><br></p><h2><strong>RBI reviews digital lending regulations</strong> </h2><p><br></p><ul><li>Reserve Bank of India (RBI) reviewed digital lending rules</li><li>Focus on customer protection and fintech company oversight</li><li>Aims to improve transparency and reduce online loan fraud</li><li>Strengthens safe and regulated digital banking system</li></ul><p><br></p>', '', '<p><strong>RBI reviews Digital Lending Regulations ⭐</strong></p><p><strong>What is RBI? ⭐</strong></p><p>The Reserve Bank of India (RBI) is the central bank of India. It controls and regulates the country’s banking and monetary system. RBI is responsible for maintaining financial stability, controlling inflation, regulating banks, issuing currency notes, and ensuring the smooth functioning of the Indian economy. It is also known as the “Banker’s Bank” because commercial banks keep reserves with RBI and depend on it for financial support during emergencies. RBI also acts as the banker to the Government of India.</p><p class=\"ql-align-center\"><br></p><p><strong>Establishment of RBI ⭐</strong></p><p>The Reserve Bank of India was established on 1 April 1935 under the Reserve Bank of India Act, 1934. It was nationalized in 1949 after India’s independence. The headquarters of RBI is located in Mumbai.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Main Functions of RBI ⭐</strong></p><p>The Reserve Bank of India performs several important functions for India’s financial and banking system. As the monetary authority, RBI controls money supply, inflation, and interest rates through monetary policy. It acts as the banker to the Government of India by managing government accounts, loans, and treasury operations. RBI also functions as the Banker’s Bank, where commercial banks maintain reserves and receive financial assistance during crises. RBI issues Indian currency notes except the ₹1 note, which is issued by the Ministry of Finance. The central bank also regulates public sector banks, private banks, cooperative banks, and NBFCs to maintain financial discipline and stability.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Digital Lending? ⭐</strong></p><p>Digital lending refers to providing loans through mobile applications, websites, and online platforms without requiring physical paperwork or branch visits. Fintech companies and digital banking applications use technologies such as Artificial Intelligence (AI), data analytics, and online verification systems for loan approval and customer assessment.</p><p class=\"ql-align-center\"><br></p><p><strong>What are Digital Lending Rules? ⭐</strong></p><p>Digital lending rules are regulations introduced by RBI to control online loan applications, fintech lending companies, and digital loan platforms. These rules are designed to ensure customer safety, transparency, fair lending practices, and proper financial regulation in the digital lending sector.</p><p class=\"ql-align-center\"><br></p><p><strong>Why did RBI review Digital Lending Regulations? ⭐</strong></p><p>RBI reviewed digital lending regulations because several illegal loan applications and unregulated fintech companies were charging extremely high interest rates, misusing customer data, harassing borrowers, and committing online financial fraud. The review was conducted to strengthen consumer protection, improve cybersecurity, and increase transparency in digital financial services.</p><p class=\"ql-align-center\"><br></p><p><strong>Problems in Digital Lending Sector ⭐</strong></p><p>The digital lending sector faces several major problems. Fake online loan applications often cheat customers and steal money or personal data. Many platforms impose hidden charges and excessive interest rates on borrowers. Data privacy issues have also increased because some applications misuse customer contacts, photographs, and personal information. Illegal recovery practices and harassment by recovery agents have created serious public complaints and financial stress.</p><p class=\"ql-align-center\"><br></p><p><strong>How RBI improves Transparency in Digital Lending? ⭐</strong></p><p>RBI has introduced several measures to improve transparency in digital lending. Lenders are required to clearly disclose interest rates, repayment conditions, and penalties to customers. Only authorized and regulated entities are allowed to provide digital loans. RBI has also introduced customer consent rules, under which lending applications must take proper permission before accessing personal data. In addition, loan amounts must be transferred directly between the bank account and borrower account without unauthorized intermediaries.</p><p class=\"ql-align-center\"><br></p><p><strong>How RBI reduces Online Loan Fraud? ⭐</strong></p><p>RBI is strengthening cybersecurity monitoring of fintech platforms and digital financial transactions to reduce online loan fraud. Mandatory Know Your Customer (KYC) verification helps identify genuine users and prevent fraudulent activities. RBI and government agencies are also taking action against illegal loan applications by removing fake apps from digital platforms. Data protection regulations further help prevent misuse of customer information.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Fintech? ⭐</strong></p><p>Fintech stands for Financial Technology. It refers to technology-based financial services such as digital payments, online banking, digital lending, investment platforms, and financial applications. Fintech combines finance and technology to make banking and financial services faster, easier, and more accessible.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Digital Lending ⭐</strong></p><p>Digital lending provides several important benefits. Loan approvals become faster because applications are processed through digital systems. Digital lending also promotes financial inclusion by providing banking access to people living in remote areas. Paperless banking reduces physical documentation and improves convenience. Startups and MSMEs receive easier access to credit and business financing through online lending platforms.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p>For UPSC examinations, this topic is important in areas such as banking regulation, financial governance, digital economy, and fintech regulation. For SSC, Banking, and Railway examinations, important areas include RBI governors, banking terms, monetary policy tools, and digital lending regulations.</p><p class=\"ql-align-center\"><br></p><p><strong>One-Liner for Exams ⭐</strong></p><p>RBI reviewed digital lending regulations to improve customer protection, strengthen fintech oversight, and reduce online loan fraud in India’s rapidly growing digital banking sector.</p><p><br></p>', '', 'ECONOMY & BANKING', '', '', NULL, 'active', 1, '2026-05-03 12:47:00', '2026-05-11 18:28:39', '2026-05-11 18:28:39');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(46, 'UPI transactions record new growth milestone ', '', '<h2><strong>UPI transactions record new growth milestone</strong> </h2><p><br></p><ul><li>UPI transactions reached a new record in digital payments</li><li>Indicates rapid expansion of India’s digital payment ecosystem</li><li>Supports cashless economy and financial inclusion</li><li>Managed by National Payments Corporation of India (NPCI)</li></ul><p><br></p><p><br></p>', '', '<p><strong>UPI Transactions record new Growth Milestone ⭐</strong></p><p><strong>What is UPI? ⭐</strong></p><p>Unified Payments Interface (UPI) is a real-time digital payment system that allows users to send money, receive money, pay bills, and transfer funds instantly using mobile phones, bank accounts, and QR codes. UPI enables direct bank-to-bank transfers without requiring users to enter IFSC codes or bank account numbers for every transaction. It has become one of the most widely used digital payment systems in India.</p><p class=\"ql-align-center\"><br></p><p><strong>Launched In ⭐</strong></p><p>UPI was launched in the year 2016 to promote digital payments and support India’s transition toward a cashless economy.</p><p class=\"ql-align-center\"><br></p><p><strong>Developed &amp; Managed By ⭐</strong></p><p>UPI was developed and is managed by the National Payments Corporation of India (NPCI).</p><p class=\"ql-align-center\"><br></p><p><strong>What is NPCI? ⭐</strong></p><p>NPCI is the organization responsible for managing digital retail payment systems in India. It develops and operates payment infrastructure that supports safe, secure, and fast digital financial transactions across the country.</p><p class=\"ql-align-center\"><br></p><p><strong>Established ⭐</strong></p><p>NPCI was founded in 2008 to strengthen India’s digital payment ecosystem and modernize financial transaction systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Operates Under ⭐</strong></p><p>NPCI operates under the guidance of the Reserve Bank of India (RBI) and the Indian Banks’ Association (IBA).</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><p>The headquarters of NPCI is located in Mumbai.</p><p class=\"ql-align-center\"><br></p><p><strong>Chairman of NPCI ⭐</strong></p><p>As of 2026, the Chairman of NPCI is Biswamohan Mahapatra.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Purpose of UPI ⭐</strong></p><p>The primary objective of UPI is to promote a cashless economy, encourage fast digital payments, and improve financial inclusion. UPI has made digital transactions simple, secure, and accessible for millions of people across India.</p><p class=\"ql-align-center\"><br></p><p><strong>How does UPI Work? ⭐</strong></p><p>UPI works by linking a bank account with a mobile application. Users can transfer money instantly using mobile numbers, QR codes, UPI IDs, or bank account details. The system supports seamless digital payments through smartphones and internet connectivity.</p><p><br></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>What is Digital Payment? ⭐</strong></p><p>Digital payment refers to electronic payment methods that do not involve physical cash transactions. Payments are made using mobile phones, debit or credit cards, internet banking systems, and digital wallets. Digital payments make financial transactions faster, more convenient, and transparent.</p><p><br></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Benefits of Digital Payments over Cash Payments ⭐</strong></p><p>Digital payments provide several advantages over traditional cash payments. Transactions become faster because money can be transferred instantly. A cashless economy reduces dependence on physical currency and improves financial transparency because every transaction is digitally recorded. Digital payment systems also promote financial inclusion by providing banking access to people in rural and remote areas through smartphones. In addition, digital payments reduce the risk of theft since users do not need to carry large amounts of cash. Utility bill payments, shopping transactions, and online services also become easier and more convenient.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Financial Inclusion? ⭐</strong></p><p>Financial inclusion refers to providing banking and financial services to poor, rural, and unbanked populations. The objective is to ensure that every citizen has access to banking, savings, digital payments, and financial support systems.</p><p class=\"ql-align-center\"><br></p><p><strong>RBI Rules for Digital Payments ⭐</strong></p><p>The Reserve Bank of India has introduced several rules to strengthen digital payment security. Users must complete Know Your Customer (KYC) verification before accessing certain financial services. Banks are required to provide OTP verification, PIN protection, and cybersecurity measures for secure transactions. RBI also monitors suspicious transactions and fake payment applications to reduce online fraud. Customer financial data must remain protected under data privacy regulations.</p><p class=\"ql-align-center\"><br></p><p><strong>What does “UPI transactions reached a new record” mean? ⭐</strong></p><p>The statement means that more people are increasingly using UPI for daily financial transactions. India has witnessed massive growth in digital transfers, QR code payments, online shopping, and merchant transactions, making UPI one of the world’s largest digital payment systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is India’s Digital Payment Ecosystem expanding rapidly? ⭐</strong></p><p>India’s digital payment ecosystem is expanding rapidly because smartphone usage has increased significantly and affordable internet services have improved digital access. Government initiatives such as Digital India, Pradhan Mantri Jan Dhan Yojana, and the BHIM application have further promoted digital payment adoption. QR code payment systems are now widely accepted even by small shops and street vendors across the country.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of UPI Growth ⭐</strong></p><p>The rapid growth of UPI supports economic development by boosting online businesses, fintech companies, and the digital economy. Digital transaction records also improve tax transparency and reduce black money transactions. UPI additionally provides convenience because users can make payments quickly and easily using smartphones.</p><p><br></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p>For UPSC examinations, this topic is important in areas such as digital economy, fintech, and financial inclusion. For SSC, Banking, and Railway examinations, important areas include the full form of UPI, NPCI facts, digital payment systems, and RBI regulations related to digital transactions.</p><p class=\"ql-align-center\"><br></p><p><strong>One-Liner for Exams ⭐</strong></p><p>UPI transactions reached a new milestone, reflecting the rapid expansion of India’s digital payment ecosystem and the growth of the country’s cashless economy.</p><p><br></p><p><br></p>', '', 'ECONOMY & BANKING', '', '', NULL, 'active', 1, '2026-05-03 13:02:00', '2026-05-11 18:41:53', '2026-05-11 18:41:53');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(47, 'SEBI strengthens cyber security norms for brokers ', '', '<h2><strong>SEBI strengthens cyber security norms for brokers</strong> </h2><p><br></p><ul><li>SEBI introduced stricter cyber security rules for stock brokers</li><li>Focus on protecting investor data and online transactions</li><li>Aims to prevent cyber fraud and digital market threats</li><li>Strengthens safety and transparency in securities market</li></ul><p><br></p>', '', '<p><strong>SEBI strengthens Cyber Security Norms for Brokers ⭐</strong></p><p><strong>What is SEBI? ⭐</strong></p><p>Securities and Exchange Board of India (SEBI) is the main regulatory authority for India’s securities and stock market. It protects investors, traders, and overall market integrity by ensuring fair and transparent functioning of financial markets. SEBI regulates stock exchanges, brokers, mutual funds, and listed companies to maintain confidence in India’s financial system.</p><p class=\"ql-align-center\"><br></p><p><strong>Established ⭐</strong></p><p>SEBI was established in 1988 as a regulatory body for the securities market. It was later granted statutory powers in 1992 to strengthen its authority and legal framework.</p><p class=\"ql-align-center\"><br></p><p><strong>SEBI Act ⭐</strong></p><p>SEBI functions under the provisions of the SEBI Act, 1992, which gives the organization legal powers to regulate and supervise India’s securities market.</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters ⭐</strong></p><p>The headquarters of SEBI is located in Mumbai.</p><p class=\"ql-align-center\"><br></p><p><strong>Current Chairman ⭐</strong></p><p>As of 2026, the Chairman of SEBI is Tuhin Kanta Pandey.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Functions of SEBI ⭐</strong></p><p>SEBI performs several important functions to regulate and develop India’s securities market. It protects investors from fraud, manipulation, and unfair market practices. SEBI regulates stock exchanges, brokers, mutual funds, and listed companies to ensure proper functioning of the securities market. It also promotes transparent, efficient, and fair market development while monitoring trading activities to detect insider trading, illegal transactions, and market manipulation.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Stock Market? ⭐</strong></p><p>The stock market is a financial marketplace where shares, securities, and bonds are bought and sold. It allows companies to raise capital and investors to invest in businesses. Major stock exchanges in India include the Bombay Stock Exchange (BSE) and the National Stock Exchange (NSE).</p><p class=\"ql-align-center\"><br></p><p><strong>What are Stock Brokers? ⭐</strong></p><p>Stock brokers are registered financial intermediaries who help investors buy and sell shares in the stock market. They act as a link between investors and stock exchanges by facilitating online and offline trading activities.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>What is Cyber Security? ⭐</strong></p><p>Cyber security refers to the protection of computer systems, networks, and digital data from hacking, cyber attacks, malware, and online fraud. It helps secure sensitive information and ensures safe digital transactions in financial systems.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Cyber Fraud? ⭐</strong></p><p>Cyber fraud refers to cheating or criminal activities carried out through digital systems or the internet. Examples include fake trading applications, phishing scams, OTP fraud, hacking accounts, and financial data theft.</p><p class=\"ql-align-center\"><br></p><p><strong>What are Digital Market Threats? ⭐</strong></p><p>Digital market threats are risks affecting online trading systems and digital financial platforms. These threats include malware attacks, ransomware, data theft, hacking, and unauthorized access to trading accounts or financial systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Why did SEBI strengthen Cyber Security Norms? ⭐</strong></p><p>Online trading and digital investing have increased rapidly in India, leading to a rise in cyber attacks, financial fraud, and data breaches. SEBI strengthened cyber security norms to protect investors, secure digital financial transactions, and maintain trust in India’s securities market and online trading ecosystem.</p><p class=\"ql-align-center\"><br></p><p><strong>How does SEBI strengthen Cyber Security? ⭐</strong></p><p>SEBI has introduced stronger cyber security measures for brokers and financial intermediaries. Brokers are now required to secure investor information and transaction records through stronger data protection systems. Regular cyber security audits and security checks have become mandatory. Brokers must quickly report cyber attacks and data breaches to authorities. Additional security measures such as OTP verification and biometric authentication improve account safety. Advanced monitoring systems are also used to detect suspicious transactions and unusual market activities.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Strong Cyber Security Norms ⭐</strong></p><p>Strong cyber security norms improve investor safety by protecting money, personal information, and trading accounts from fraud. These measures also improve market stability by preventing large-scale digital disruptions. Greater transparency builds trust in stock exchanges, fintech platforms, and online trading systems. Stronger security regulations further help reduce fake investment schemes, scams, and cyber fraud.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Investor Protection? ⭐</strong></p><p>Investor protection refers to measures taken to safeguard investors’ interests, prevent cheating and fraud, and ensure fair market practices within the financial and securities market.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p>For UPSC examinations, this topic is important in areas such as financial regulation, cybersecurity governance, digital economy, and investor protection. For SSC, Banking, and Railway examinations, important areas include the full form of SEBI, stock market basics, cyber security concepts, and financial market regulation.</p><p class=\"ql-align-center\"><br></p><p><strong>One-Liner for Exams ⭐</strong></p><p>SEBI strengthened cyber security norms for stock brokers to improve investor safety, prevent cyber fraud, and secure India’s rapidly growing digital securities market.</p><p><br></p><p><br></p><p><br></p>', '', 'ECONOMY & BANKING', '', '', NULL, 'active', 1, '2026-05-03 13:14:00', '2026-05-11 18:55:23', '2026-05-11 18:55:23');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(48, 'India expands AI research partnerships globally ', '', '<h2><strong>India expands AI research partnerships globally</strong> </h2><p><br></p><ul><li>India increased global partnerships in Artificial Intelligence research</li><li>Focus on startup innovation and digital economy growth</li><li>Promotes technology collaboration and advanced AI development</li><li>Supports innovation, digital infrastructure and skilled employment</li></ul><p><br></p>', '', '<p><strong>India expands AI Research Partnerships Globally ⭐</strong></p><p><strong>What is AI? ⭐</strong></p><p>Artificial Intelligence (AI) is a technology that enables machines and computer systems to think, learn, analyze, and make decisions in a way similar to humans. AI systems use data, algorithms, and machine learning techniques to perform intelligent tasks automatically and efficiently. AI is considered one of the most important emerging technologies of the modern digital era.</p><p class=\"ql-align-center\"><br></p><p><strong>Father / Inventor of AI ⭐</strong></p><p>John McCarthy is known as the “Father of Artificial Intelligence.” He coined the term “Artificial Intelligence” in 1956 and played a major role in the development of AI as a scientific and technological field.</p><p class=\"ql-align-center\"><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Examples of AI ⭐</strong></p><p>Examples of Artificial Intelligence include ChatGPT, Google Assistant, self-driving vehicles, AI chatbots, and face recognition systems. These technologies are increasingly used in daily life and business operations.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is AI Important? ⭐</strong></p><p>Artificial Intelligence improves automation, speed, efficiency, and decision-making capabilities. AI has become important in sectors such as healthcare, banking, defence, education, agriculture, and cybersecurity. It helps organizations analyze large amounts of data, improve productivity, and provide smarter digital services.</p><p class=\"ql-align-center\"><br></p><p><strong>What does “India expands AI research partnerships globally” mean? ⭐</strong></p><p>The statement means that India is increasing cooperation with foreign countries, universities, technology companies, and international organizations for AI research, innovation, and advanced technology development. India is working to strengthen global collaboration in emerging digital technologies.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is India expanding AI Partnerships globally? ⭐</strong></p><p>India is expanding AI partnerships globally to become a leader in Artificial Intelligence, digital innovation, and advanced computing technologies. These partnerships help Indian startups, fintech companies, and research institutions gain access to advanced knowledge and global expertise. AI cooperation also supports the growth of India’s digital economy by improving automation, digital services, smart governance, and online businesses. Countries such as the United States, China, and Japan are investing heavily in AI, and India also aims to strengthen its technological competitiveness at the global level.</p><p class=\"ql-align-center\"><br></p><p><strong>How does India expand AI Research Partnerships? ⭐</strong></p><p>India expands AI research partnerships through international agreements such as Memorandums of Understanding (MoUs) and research collaborations with global institutions. India also collaborates with major technology companies including Google, Microsoft, IBM, and NVIDIA. Indian educational institutions and research centers work together with global universities and AI research laboratories. Government initiatives further support AI innovation, semiconductor development, and digital infrastructure expansion.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of AI Research Partnerships ⭐</strong></p><p>AI research partnerships provide several benefits for India’s economy and technology sector. Startups can develop smart applications, fintech platforms, healthcare technologies, and automation systems using AI. These partnerships create employment opportunities for AI engineers, data scientists, and software developers. AI also strengthens the digital economy, technology exports, and foreign investment inflow. Public services such as governance, healthcare, education, and transportation improve through AI-based systems. In addition, AI helps strengthen cybersecurity by detecting cyber attacks, online fraud, and digital threats.</p><p class=\"ql-align-center\"><br></p><p><strong>Is AI a Boon or Challenge? ⭐</strong></p><p>Artificial Intelligence provides many advantages such as faster work processes, better accuracy, automation, innovation growth, and smarter decision-making systems. However, AI also creates several challenges. Automation may reduce some traditional jobs, while cyber risks and misuse of AI systems remain major concerns. Data privacy issues and the high cost of advanced AI technologies are also important challenges.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams ⭐</strong></p><p>For UPSC examinations, this topic is important in areas such as emerging technologies, digital economy, international cooperation, and Artificial Intelligence governance. For SSC, Banking, and Railway examinations, important areas include the full form of AI, the Father of AI, government technology missions, and AI-related developments.</p><p class=\"ql-align-center\"><br></p><p><strong>One-Liner for Exams ⭐</strong></p><p>India expanded global AI research partnerships to promote startup innovation, advanced technology development, and the growth of the digital economy.</p><p><br></p><p><br></p><p><br></p><p><br></p>', '', 'SCIENCE & TECHNOLOGY', '', '', NULL, 'active', 1, '2026-05-03 13:28:00', '2026-05-11 19:08:31', '2026-05-11 19:08:31');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(49, 'DRDO develops advanced drone surveillance system ', '', '<h2><strong>DRDO develops advanced drone surveillance system</strong> </h2><p><br></p><ul><li>DRDO developed new advanced drone surveillance technology</li><li>Supports defence monitoring and border security</li><li>Helps real-time tracking and intelligence gathering</li><li>Strengthens India’s defence and surveillance capabilities</li></ul><p><br></p>', '', '<p><strong>DRDO develops Advanced Drone Surveillance System</strong></p><p><strong>What is DRDO?</strong></p><p>Defence Research and Development Organisation (DRDO) is India’s premier defence research agency responsible for developing military technology, weapons systems, defence equipment, and strategic research projects. DRDO creates advanced defence technologies for the Indian Army, Indian Navy, and Indian Air Force to strengthen India’s national security and defence preparedness.</p><p class=\"ql-align-center\"><br></p><p><strong>Established</strong></p><p>DRDO was founded in 1958 to promote indigenous defence technology and advanced military research in India.</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters</strong></p><p>The headquarters of DRDO is located in New Delhi.</p><p class=\"ql-align-center\"><br></p><p><strong>Ministry</strong></p><p>DRDO works under the Ministry of Defence.</p><p class=\"ql-align-center\"><br></p><p><strong>Current Chairman</strong></p><p>As of 2026, the Chairman of DRDO is Samir V. Kamat.</p><p class=\"ql-align-center\"><br></p><p><strong>Motto of DRDO</strong></p><p>The motto of DRDO is “Balasya Mulam Vigyanam,” which means “Strength’s Origin is Science.” The motto reflects the importance of scientific innovation and technological advancement in strengthening national defence capabilities.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Functions of DRDO</strong></p><p>DRDO performs several important functions for India’s defence sector. It develops missiles, drones, radars, combat systems, and electronic warfare technologies for military use. DRDO also conducts research in aerospace, Artificial Intelligence, cyber defence, and robotics. The organization plays a major role in improving India’s defence preparedness and strategic security.</p><h1><br></h1><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is a Drone?</strong></p><p>A drone, also called an Unmanned Aerial Vehicle (UAV), is an aircraft that operates without an onboard pilot. Drones can be controlled remotely or through autonomous systems using advanced software and sensors.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Drone Surveillance System?</strong></p><p>A drone surveillance system uses drones for monitoring, tracking, intelligence collection, and security observation. These systems use cameras, sensors, Artificial Intelligence, and thermal imaging technologies to gather real-time information and surveillance data.</p><p class=\"ql-align-center\"><br></p><p><strong>Why did DRDO develop Advanced Drone Surveillance System?</strong></p><p>DRDO developed the Advanced Drone Surveillance System to strengthen border security, coastal monitoring, and protection of sensitive defence zones. Modern warfare increasingly depends on drones, AI surveillance, and electronic intelligence systems. Advanced drones help identify infiltration attempts, enemy movement, and suspicious activities in real time, improving India’s defence monitoring capabilities.</p><p class=\"ql-align-center\"><br></p><p><strong>Features of Advanced Drone Surveillance System</strong></p><p>The Advanced Drone Surveillance System provides real-time monitoring and live surveillance data for defence operations. It uses Artificial Intelligence for object detection and movement analysis. Thermal imaging technology helps detect targets during night operations and poor weather conditions. The system also supports long-range surveillance and can quickly monitor large geographical regions.</p><p class=\"ql-align-center\"><br></p><p><strong>How does it support Defence Monitoring?</strong></p><p>The drone surveillance system strengthens defence monitoring by tracking activities near international borders and sensitive regions. It helps military intelligence agencies collect strategic information regarding enemy movement and suspicious operations. The system can also assist during natural disasters such as floods and earthquakes by supporting rescue and monitoring operations. In anti-terror operations, drone surveillance improves security in conflict zones and high-risk areas.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Advanced Drone Surveillance System</strong></p><p>The Advanced Drone Surveillance System improves India’s national security and defence readiness. It reduces risk to soldiers during dangerous surveillance missions by using unmanned systems. Faster threat detection helps security forces respond quickly to suspicious activities and infiltration attempts. Continuous monitoring also strengthens border protection and improves overall defence efficiency.</p><p class=\"ql-align-center\"><br></p><p><strong>How does it strengthen India’s Defence Capabilities?</strong></p><p>The system promotes indigenous defence technology and reduces India’s dependence on foreign military systems. It also encourages technological advancement in Artificial Intelligence, robotics, and defence innovation. Advanced surveillance systems provide India with a strategic advantage by improving military preparedness, intelligence gathering, and operational efficiency.</p><p class=\"ql-align-center\"><br></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>This topic is important for UPSC examinations in areas such as defence technology, national security, military modernization, indigenous defence systems, and emerging technologies.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>For SSC, Railway, and Banking examinations, important areas include the full form of DRDO, defence organizations, drone technology basics, and India’s defence research developments.</p><p class=\"ql-align-center\"><br></p><p><strong>One-Liner for Exams</strong></p><p>DRDO developed an advanced drone surveillance system to strengthen India’s border security, real-time defence monitoring, and strategic surveillance capabilities.</p><p><br></p><p><br></p><p><br></p>', '', 'SCIENCE & TECHNOLOGY', '', '', NULL, 'active', 1, '2026-05-02 23:56:00', '2026-05-12 05:39:07', '2026-05-12 05:39:07');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(50, 'Aditya-L1 solar mission shares new observations ', '', '<h2><strong>Aditya-L1 solar mission shares new observations</strong> </h2><p><br></p><ul><li>ISRO’s Aditya-L1 mission released new solar observation data</li><li>Mission studies Sun’s atmosphere and solar activities</li><li>Helps understand solar storms and space weather</li><li>Strengthens India’s space research capabilities</li></ul><p><br></p>', '', '<p><strong>Aditya-L1 Solar Mission shares New Observations</strong></p><p><strong>What is Aditya-L1 Mission?</strong></p><p>Aditya-L1 is India’s first dedicated solar mission launched by Indian Space Research Organisation. The mission studies the Sun, solar atmosphere, solar storms, and space weather. Aditya-L1 was designed to improve scientific understanding of solar activities and their impact on Earth and space systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Meaning of “L1”</strong></p><p>“L1” refers to Lagrange Point 1, which is a special location in space between the Earth and the Sun where gravitational forces remain balanced. At this point, a spacecraft can continuously observe the Sun without interruption.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is L1 Important?</strong></p><p>The L1 point is important because spacecraft placed there can continuously monitor solar activities without Earth blocking the view of the Sun. The L1 point is located around 1.5 million kilometers from Earth.</p><p class=\"ql-align-center\"><br></p><p><strong>Launch Date</strong></p><p>Aditya-L1 was launched on 2 September 2023.</p><p class=\"ql-align-center\"><br></p><p><strong>Launch Vehicle</strong></p><p>The mission was launched using PSLV-C57.</p><p class=\"ql-align-center\"><br></p><p><strong>Launch Site</strong></p><p>The launch took place from Satish Dhawan Space Centre located in Sriharikota, Andhra Pradesh.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Objective of Aditya-L1</strong></p><p>The main objective of Aditya-L1 is to study the solar corona, solar flares, solar winds, magnetic storms, and space weather. The mission helps scientists better understand the behavior and activities of the Sun.</p><p class=\"ql-align-center\"><br></p><p><strong>What is ISRO?</strong></p><p>Indian Space Research Organisation (ISRO) is India’s national space agency responsible for satellites, rockets, planetary missions, and space research. ISRO plays a major role in India’s scientific and technological development in the field of space exploration.</p><p class=\"ql-align-center\"><br></p><p><strong>Established</strong></p><p>ISRO was founded in 1969.</p><p class=\"ql-align-center\"><br></p><p><strong>Founder of ISRO</strong></p><p>Vikram Sarabhai is known as the founder of ISRO and is often called the “Father of the Indian Space Programme.”</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters</strong></p><p>The headquarters of ISRO is located in Bengaluru.</p><p class=\"ql-align-center\"><br></p><p><strong>Current Chairman</strong></p><p>As of 2026, the Chairman of ISRO is V. Narayanan.</p><p class=\"ql-align-center\"><br></p><p><strong>Motto of ISRO</strong></p><p>The motto of ISRO is “Space Technology in the Service of Humanity,” reflecting the organization’s goal of using space technology for national development and public welfare.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><strong>Achievements of ISRO</strong></p><p><strong>Chandrayaan-3</strong></p><p>Through Chandrayaan-3, India became the first country to land near the Moon’s south pole, marking a major achievement in global space exploration.</p><p class=\"ql-align-center\"><br></p><p><strong>Mars Orbiter Mission</strong></p><p>Through the Mars Orbiter Mission, India became the first Asian nation to successfully reach Mars orbit in its first attempt.</p><p class=\"ql-align-center\"><br></p><p><strong>PSLV Success</strong></p><p>The Polar Satellite Launch Vehicle (PSLV) is considered one of the world’s most reliable launch vehicles because of its high mission success rate.</p><p class=\"ql-align-center\"><br></p><p><strong>What are Solar Activities?</strong></p><p>Solar activities are events and processes occurring on the Sun such as solar flares, sunspots, coronal mass ejections, and solar winds. These activities release enormous amounts of energy into space.</p><p class=\"ql-align-center\"><br></p><p><strong>What are Solar Storms?</strong></p><p>Solar storms are powerful explosions and energy bursts from the Sun that release charged particles and radiation into space. These storms can affect satellites, communication systems, and Earth’s magnetic field.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>This topic is important for UPSC examinations in areas such as space technology, solar science, ISRO missions, and India’s scientific achievements.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Banking / Railway</strong></p><p>For SSC, Banking, and Railway examinations, important topics include ISRO facts, Aditya-L1 mission details, space weather, and PSLV launch vehicles.</p><p class=\"ql-align-center\"><br></p><p><strong>One-Liner for Exams</strong></p><p>Aditya-L1 is India’s first solar mission launched by ISRO to study the Sun, solar storms, and space weather from the L1 point in space.</p><p><br></p><p><br></p><p><br></p><p><br></p>', '', 'SPACE & ASTRONOMY', '', '', NULL, 'active', 1, '2026-05-03 00:11:00', '2026-05-12 05:49:44', '2026-05-12 05:49:44');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(51, 'India expands renewable energy infrastructure ', '', '<h2><strong>India expands renewable energy infrastructure</strong> </h2><p><br></p><ul><li>India accelerated solar and wind energy projects</li><li>Focus on clean and sustainable power generation</li><li>Supports green energy transition and energy security</li><li>Helps reduce carbon emissions and fossil fuel dependence</li></ul><p><br></p>', '', '<p><strong>India expands Renewable Energy Infrastructure</strong></p><p><strong>What is Renewable Energy?</strong></p><p>Renewable energy is energy produced from natural resources that are continuously replenished and environmentally friendly. These energy resources do not get exhausted quickly and can be used repeatedly for sustainable development and clean power generation.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Non-Renewable Energy?</strong></p><p>Non-renewable energy comes from limited natural resources that may finish over time because they cannot be replenished quickly. These energy sources are widely used for electricity generation, industries, and transportation.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Solar Energy?</strong></p><p>Solar energy is power generated using sunlight. Solar panels convert sunlight into electricity using photovoltaic technology. Solar energy is one of the fastest-growing renewable energy sources in India and across the world.</p><p class=\"ql-align-center\"><br></p><p><strong>How does Solar Power work?</strong></p><p><strong>Step 1</strong></p><p>Solar panels absorb sunlight and capture solar radiation for energy generation.</p><p class=\"ql-align-center\"><br></p><p><strong>Step 2</strong></p><p>Photovoltaic (PV) cells convert sunlight into electrical energy through the photovoltaic effect.</p><p class=\"ql-align-center\"><br></p><p><strong>Step 3</strong></p><p>The generated electricity is supplied to homes, industries, and power grids for daily use.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Wind Energy?</strong></p><p>Wind energy is electricity generated from wind movement. Wind turbines rotate because of wind force and generate electricity through mechanical and electrical systems.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Renewable Energy Infrastructure?</strong></p><p>Renewable energy infrastructure refers to the systems and facilities required for generation, transmission, and storage of renewable energy. Examples include solar parks, wind farms, transmission grids, and battery storage systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is India expanding Renewable Energy Infrastructure?</strong></p><p>India is expanding renewable energy infrastructure because the country’s growing population and industries require more electricity. Renewable energy helps reduce pollution and lowers carbon emissions. Expansion of renewable energy also improves energy security by reducing dependence on imported oil and fossil fuels. India is further promoting renewable energy to meet international climate change commitments and support green economic development through clean technology and sustainable industries.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Green Energy?</strong></p><p>Green energy refers to environmentally clean energy that causes minimal pollution and environmental damage. Most renewable energy sources are considered green energy sources because they produce lower greenhouse gas emissions.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Renewable Energy</strong></p><p><strong>Environmental Benefits</strong></p><p><strong>Reduced Air Pollution</strong></p><p>Renewable energy releases fewer harmful gases into the atmosphere and helps improve air quality.</p><p class=\"ql-align-center\"><br></p><p><strong>Lower Carbon Emissions</strong></p><p>Renewable energy helps control global warming and climate change by reducing greenhouse gas emissions.</p><p class=\"ql-align-center\"><br></p><p><strong>Economic Benefits</strong></p><p><strong>Job Creation</strong></p><p>Renewable energy projects create employment opportunities in solar manufacturing, wind energy projects, and green technology industries.</p><p class=\"ql-align-center\"><br></p><p><strong>Reduced Fuel Imports</strong></p><p>India can save foreign exchange reserves by reducing dependence on imported oil and fossil fuels.</p><p class=\"ql-align-center\"><br></p><p><strong>Social Benefits</strong></p><p><strong>Rural Electrification</strong></p><p>Renewable energy projects provide electricity access to remote and rural regions.</p><p class=\"ql-align-center\"><br></p><p><strong>Sustainable Development</strong></p><p>Renewable energy supports long-term environmental protection and sustainable economic growth.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>International Solar Alliance (ISA)</strong></p><p>International Solar Alliance is a global initiative led by India and France for promoting solar energy cooperation and clean energy development worldwide.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Carbon Emission?</strong></p><p>Carbon emission refers to the release of gases such as carbon dioxide (CO₂) into the atmosphere due to activities like fossil fuel burning, industrial production, and transportation systems.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>India’s Renewable Energy Targets</strong></p><p>India aims to become a global leader in clean energy, solar power, and green hydrogen production. The country is rapidly increasing investments in renewable energy infrastructure to support sustainable development and energy security.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>This topic is important for UPSC examinations in areas such as climate change, sustainable development, renewable energy policy, and energy security.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Banking / Railway</strong></p><p>For SSC, Banking, and Railway examinations, important topics include renewable energy types, solar missions, green energy concepts, and government renewable energy initiatives.</p><p class=\"ql-align-center\"><br></p><p><strong>One-Liner for Exams</strong></p><p>India expanded renewable energy infrastructure by accelerating solar and wind projects to promote clean energy, reduce pollution, and strengthen energy security.</p><p><br></p><p><br></p>', '', 'ENVIRONMENT', '', '', NULL, 'active', 1, '2026-05-03 00:21:00', '2026-05-12 05:59:12', '2026-05-12 05:59:12');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(52, 'Indian Navy conducts maritime security exercise ', '', '<h2><strong>Indian Navy conducts maritime security exercise</strong> </h2><p><br></p><ul><li>Indian Navy carried out maritime security exercise in Indo-Pacific region</li><li>Focus on naval coordination and sea security operations</li><li>Strengthens Indo-Pacific defence cooperation and strategic partnerships</li><li>Enhances surveillance, disaster response and maritime safety</li></ul><p><br></p>', '', '<p><strong>Indian Navy conducts Maritime Security Exercise</strong></p><p><strong>What is Indian Navy?</strong></p><p>The Indian Navy is the naval warfare branch of the Indian Armed Forces. It protects India’s maritime borders, sea routes, coastal regions, and national security interests in oceans and surrounding waters. The Indian Navy plays a major role in maintaining maritime security and protecting India’s strategic interests in the Indo-Pacific region.</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters</strong></p><p>The headquarters of the Indian Navy is located in New Delhi.</p><p class=\"ql-align-center\"><br></p><p><strong>Ministry</strong></p><p>The Indian Navy works under the Ministry of Defence.</p><p class=\"ql-align-center\"><br></p><p><strong>Supreme Commander</strong></p><p>The President of India is the Supreme Commander of the Indian Armed Forces.</p><p class=\"ql-align-center\"><br></p><p><strong>Chief of Naval Staff</strong></p><p>As of 2026, the Chief of Naval Staff of the Indian Navy is Dinesh K. Tripathi. The Indian Navy is headed by the Chief of Naval Staff and does not have a chairman.</p><p class=\"ql-align-center\"><br></p><p><strong>Motto of Indian Navy</strong></p><p>The motto of the Indian Navy is “Sham No Varunah,” which means “May the Lord of the Oceans be auspicious unto us.” The motto reflects the Navy’s connection with maritime strength and protection.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Functions of Indian Navy</strong></p><p>The Indian Navy performs several important functions for national defence and maritime protection. It protects territorial waters, the Exclusive Economic Zone (EEZ), and major sea trade routes. The Navy also guards India’s coastline against infiltration, piracy, and smuggling activities. During natural disasters such as cyclones, floods, and tsunamis, the Navy provides humanitarian assistance and rescue operations. It also supports India’s strategic deterrence and national defence strategy.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Maritime Security?</strong></p><p>Maritime security refers to the protection of oceans, ports, ships, and sea trade routes from piracy, terrorism, illegal activities, and military threats. It is essential for maintaining safe international trade and national security.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Indo-Pacific Region?</strong></p><p>The Indo-Pacific is a strategic region covering the Indian Ocean and the Pacific Ocean. It connects Asia, Australia, Africa, and Pacific nations, making it one of the most important regions for global trade and defence cooperation.</p><p class=\"ql-align-center\"><br></p><p><strong>Importance of Indo-Pacific Region</strong></p><p><strong>Global Trade Route</strong></p><p>A large portion of global trade passes through Indo-Pacific sea routes, making the region highly important for international commerce and shipping.</p><p class=\"ql-align-center\"><br></p><p><strong>Strategic Importance</strong></p><p>The Indo-Pacific region is important for defence operations, naval security, shipping activities, and energy transportation.</p><p class=\"ql-align-center\"><br></p><p><strong>Economic Importance</strong></p><p>The region includes major economies such as India, United States, Japan, China, and Australia.</p><p class=\"ql-align-center\"><br></p><p><strong>Why did Indian Navy conduct Maritime Security Exercise?</strong></p><p>The Indian Navy conducted the maritime security exercise to strengthen naval preparedness and improve readiness against maritime threats and emergencies. The exercise also helps improve international cooperation with friendly nations, secure important shipping lanes and trade routes, and prepare naval forces for rescue operations and humanitarian missions.</p><p class=\"ql-align-center\"><br></p><p><strong>How does it strengthen Indo-Pacific Cooperation?</strong></p><p>Maritime security exercises strengthen Indo-Pacific cooperation through coordinated naval operations, joint sea patrols, and military drills among participating countries. Countries also exchange intelligence related to piracy, terrorism, and suspicious maritime activities. These exercises improve strategic partnerships, defence cooperation, and diplomatic relations among participating nations.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Malabar Exercise?</strong></p><p>Malabar Exercise is a major naval exercise involving India, the United States, Japan, and Australia. The exercise focuses on maritime security, naval cooperation, military coordination, and maintaining stability in the Indo-Pacific region.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Benefits of Maritime Security Exercises</strong></p><p><strong>National Security</strong></p><p>Maritime exercises help protect India’s maritime interests and strengthen defence preparedness.</p><p class=\"ql-align-center\"><br></p><p><strong>Better Coordination</strong></p><p>These exercises improve operational coordination and cooperation among participating navies.</p><p class=\"ql-align-center\"><br></p><p><strong>Technology Sharing</strong></p><p>Countries exchange defence technologies, operational tactics, and maritime strategies during such exercises.</p><p class=\"ql-align-center\"><br></p><p><strong>Economic Protection</strong></p><p>Secure sea routes help protect international trade and energy transportation systems.</p><p><br></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>This topic is important for UPSC examinations in areas such as maritime security, Indo-Pacific strategy, international defence cooperation, and strategic affairs.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Banking / Railway</strong></p><p>For SSC, Banking, and Railway examinations, important topics include naval exercises, Indo-Pacific basics, Navy Chief, and maritime security concepts.</p><p class=\"ql-align-center\"><br></p><p><br></p><p><br></p>', '', 'DEFENCE & SECURITY', '', '', NULL, 'active', 1, '2026-05-03 00:29:00', '2026-05-12 06:08:21', '2026-05-12 06:08:21');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(53, 'Border infrastructure projects reviewed by MoD ', '', '<h2><strong>Border infrastructure projects reviewed by MoD</strong> </h2><p><br></p><ul><li>Ministry of Defence (MoD) reviewed border infrastructure projects</li><li>Focus on strategic connectivity in border areas</li><li>Includes roads, bridges and military logistics development</li><li>Aims to strengthen national security and faster troop movement</li></ul><p><br></p>', '', '<p><strong>Border Infrastructure Projects reviewed by MoD</strong></p><p><strong>What is MoD?</strong></p><p><strong>MoD</strong> stands for:</p><ul><li><strong>Ministry of Defence</strong></li></ul><p>It is the ministry of Government of India responsible for national defence, armed forces, military administration, defence policy and border security coordination. The ministry manages the Indian Army, Indian Navy, Indian Air Force and various defence organizations that work to strengthen India’s national security and defence preparedness.</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters</strong></p><ul><li><strong>New Delhi</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Current Defence Minister</strong></p><ul><li>Rajnath Singh <em>(2026)</em></li></ul><p><em>(The Ministry of Defence does not have a chairman; it is headed by the Defence Minister.)</em></p><p class=\"ql-align-center\"><br></p><p><strong>Works Under</strong></p><ul><li>Government of India</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Main Responsibilities of MoD</strong></p><p><strong>National Security</strong></p><p>The Ministry of Defence protects India from external threats, military aggression and border conflicts. It coordinates defence planning and ensures the safety of the country’s territorial integrity through military preparedness and strategic planning.</p><p class=\"ql-align-center\"><br></p><p><strong>Defence Policy</strong></p><p>MoD frames defence strategies and military modernization policies to strengthen India’s armed forces and improve technological advancement in defence systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Border Infrastructure Development</strong></p><p>The ministry develops roads, tunnels, bridges and airfields near border regions to improve military movement, logistics, communication and strategic connectivity in sensitive areas.</p><p class=\"ql-align-center\"><br></p><p><strong>Coordination of Armed Forces</strong></p><p>MoD supervises the operations of the Army, Navy and Air Force and ensures coordination among all defence services during national security operations and emergencies.</p><p class=\"ql-align-center\"><br></p><p><strong>What are Border Infrastructure Projects?</strong></p><p>Border infrastructure projects are projects developed near international borders for military movement, logistics, communication and connectivity. These projects improve defence preparedness and strengthen India’s strategic presence in border regions.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Why did MoD review Border Infrastructure Projects?</strong></p><p><strong>Strategic Security Needs</strong></p><p>India shares borders with China, Pakistan, Nepal, Bhutan, Bangladesh and Myanmar. Border infrastructure is important for defence preparedness, surveillance and rapid military deployment in sensitive border areas.</p><p class=\"ql-align-center\"><br></p><p><strong>Faster Military Response</strong></p><p>Roads and transport systems help quick troop deployment and faster equipment movement during emergencies, military operations and border tensions.</p><p class=\"ql-align-center\"><br></p><p><strong>Difficult Terrain</strong></p><p>Many border areas are mountainous, remote and snow-covered. Infrastructure projects improve accessibility and help defence forces operate efficiently even in difficult geographical conditions.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Strategic Connectivity?</strong></p><p>Strategic connectivity means transport and communication systems developed for defence, security and rapid military operations. These systems help armed forces move quickly and maintain effective coordination in border areas.</p><p class=\"ql-align-center\"><br></p><p><strong>How does Border Infrastructure strengthen National Security?</strong></p><p><strong>Better Border Monitoring</strong></p><p>Improved roads and communication systems strengthen surveillance and patrolling activities near international borders.</p><p class=\"ql-align-center\"><br></p><p><strong>Rapid Defence Deployment</strong></p><p>Troops and weapons can move quickly during emergencies, improving military response capabilities and operational efficiency.</p><p class=\"ql-align-center\"><br></p><p><strong>Stronger Territorial Control</strong></p><p>Infrastructure projects enhance security presence in sensitive regions and strengthen India’s territorial control along border areas.</p><p class=\"ql-align-center\"><br></p><p><strong>Disaster Support</strong></p><p>Border infrastructure also helps rescue and relief operations during floods, earthquakes and landslides by improving transport and communication access in remote regions.</p><p class=\"ql-align-center\"><br></p><p><strong>How does it help Faster Troop Movement?</strong></p><p><strong>All-Weather Roads</strong></p><p>All-weather roads allow military movement even during snowfall, rain and harsh climatic conditions, ensuring continuous defence operations.</p><p class=\"ql-align-center\"><br></p><p><strong>Bridges for Heavy Vehicles</strong></p><p>Strong bridges support the movement of tanks, artillery and military trucks used during defence operations.</p><p class=\"ql-align-center\"><br></p><p><strong>Reduced Travel Time</strong></p><p>Improved connectivity reduces travel time and helps troops reach border areas much faster during emergencies.</p><p class=\"ql-align-center\"><br></p><p><strong>Air Connectivity</strong></p><p>Military aircraft can quickly transport soldiers, supplies and emergency equipment to remote border regions through advanced air connectivity systems.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is BRO?</strong></p><p><strong>BRO</strong> stands for:</p><ul><li><strong>Border Roads Organisation</strong></li></ul><p>It constructs roads, tunnels and bridges in border regions to improve strategic connectivity and support defence operations in difficult terrains.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Benefits of Border Infrastructure</strong></p><p><strong>Defence Benefits</strong></p><p>Border infrastructure improves military readiness, strengthens surveillance systems and enables faster mobilization of troops and defence equipment.</p><p class=\"ql-align-center\"><br></p><p><strong>Economic Benefits</strong></p><p>Improved roads and connectivity promote better transport systems, regional development and tourism growth in border areas.</p><p class=\"ql-align-center\"><br></p><p><strong>Social Benefits</strong></p><p>Infrastructure development improves connectivity for remote villages and provides better access to healthcare, education and emergency services.</p><p class=\"ql-align-center\"><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><ul><li>Border security</li><li>Defence infrastructure</li><li>Strategic affairs</li></ul><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><ul><li>Full forms</li><li>Defence organizations</li><li>Important tunnels &amp; projects</li></ul><p><br></p>', '', 'DEFENCE & SECURITY', '', '', NULL, 'active', 1, '2026-05-03 00:49:00', '2026-05-12 06:30:41', '2026-05-12 06:30:41');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(54, 'India wins medals at international shooting event ', '', '<h2><strong>India wins medals at international shooting event</strong> </h2><p><br></p><ul><li>Indian shooters won medals at an international shooting competition</li><li>NRAI athletes delivered strong performances in multiple events</li><li>Highlights India’s growing success in shooting sports</li><li>Boosts India’s reputation in international sports competitions</li></ul><p><br></p>', '', '<p><strong>India wins Medals at International Shooting Event</strong></p><p><strong>What is an International Shooting Event?</strong></p><p>An international shooting event is a global sports competition where athletes compete in rifle shooting, pistol shooting and shotgun events. These competitions are organized under international sports bodies and involve shooters from different countries competing at the highest level of shooting sports.</p><p class=\"ql-align-center\"><br></p><p><strong>Main International Shooting Organization</strong></p><p>The major global governing body for shooting sports is:</p><ul><li>International Shooting Sport Federation (ISSF)</li></ul><p>The ISSF regulates international shooting competitions, prepares rules for events and promotes shooting sports worldwide.</p><p class=\"ql-align-center\"><br></p><p><strong>ISSF Headquarters</strong></p><ul><li>Munich, Germany</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Established</strong></p><ul><li>1907</li></ul><p class=\"ql-align-center\"><br></p><p><strong>What is NRAI?</strong></p><p><strong>NRAI</strong> stands for:</p><ul><li><strong>National Rifle Association of India</strong></li></ul><p>It is the main organization responsible for shooting sports in India. NRAI manages national shooting competitions, athlete training and India’s participation in international shooting tournaments.</p><p class=\"ql-align-center\"><br></p><p><strong>Established</strong></p><ul><li>1951</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Headquarters</strong></p><ul><li>New Delhi</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Current President of NRAI</strong></p><ul><li>Kalikesh Narayan Singh Deo <em>(2026)</em></li></ul><p class=\"ql-align-center\"><br></p><p><strong>What happened in this Current Affair?</strong></p><p>Indian shooters performed strongly at an international shooting competition and won medals in rifle and pistol categories. This achievement highlighted India’s improving position in global shooting sports and demonstrated the growing strength of Indian athletes in international competitions.</p><p class=\"ql-align-center\"><br></p><p><strong>Where are International Shooting Events held?</strong></p><p>Major shooting competitions are held in countries like Germany, Azerbaijan, Egypt, China, South Korea and India. These nations regularly host international championships and ISSF tournaments.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Why is India performing strongly in Shooting?</strong></p><p><strong>Better Training Facilities</strong></p><p>India has improved shooting academies, sports infrastructure and coaching systems. Advanced training facilities and professional coaching have helped Indian shooters perform better at the international level.</p><p class=\"ql-align-center\"><br></p><p><strong>Government Support</strong></p><p>Programs like Khelo India and the TOPS scheme provide financial support, training opportunities and international exposure to athletes preparing for global competitions.</p><p class=\"ql-align-center\"><br></p><p><strong>International Exposure</strong></p><p>Indian shooters regularly participate in global tournaments and training camps, helping them gain experience and improve their competitive performance.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of International Medals</strong></p><p><strong>National Pride</strong></p><p>Winning medals improves India’s global sports reputation and increases national pride among citizens.</p><p class=\"ql-align-center\"><br></p><p><strong>Olympic Preparation</strong></p><p>Athletes gain valuable experience for major events like the Olympics, Asian Games and World Championships through participation in international shooting competitions.</p><p class=\"ql-align-center\"><br></p><p><strong>Youth Inspiration</strong></p><p>Successful performances encourage young athletes to participate in shooting sports and pursue careers in competitive sports.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Khelo India?</strong></p><p>Khelo India is a government sports development program aimed at identifying young talent and improving sports infrastructure across India. The program supports athletes through training, scholarships and competition opportunities.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><ul><li>Sports governance</li><li>International competitions</li><li>Youth development</li></ul><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><ul><li>NRAI full form</li><li>ISSF facts</li><li>Indian medal winners</li></ul><p><br></p><p><br></p>', '', 'GAMES & SPORTS', '', '', NULL, 'active', 1, '2026-05-03 01:03:00', '2026-05-12 06:41:15', '2026-05-12 06:41:15');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(55, 'National innovation awards announced ', '', '<h2><strong>National innovation awards announced</strong> </h2><p><br></p><ul><li>National innovation awards were announced in India</li><li>Recognizes achievements in technology and startup sectors</li><li>Encourages research, entrepreneurship and innovation</li><li>Promotes development of new ideas and digital technologies</li></ul><p><br></p>', '', '<p><strong>National Innovation Awards announced</strong></p><p><strong>What are National Innovation Awards?</strong></p><p>National Innovation Awards are awards given to innovators, scientists, startups, entrepreneurs and researchers for outstanding achievements in technology, innovation, digital solutions and startup development. These awards encourage creativity, scientific thinking, entrepreneurship and research culture in India and promote the development of advanced technologies and innovative ideas.</p><p class=\"ql-align-center\"><br></p><p><strong>Purpose of National Innovation Awards</strong></p><p><strong>Promote Innovation</strong></p><p>The awards encourage the development of new technologies, scientific solutions and modern products that improve efficiency and solve real-world problems through innovation and research.</p><p class=\"ql-align-center\"><br></p><p><strong>Support Startups</strong></p><p>The awards recognize successful startup companies, entrepreneurs and innovators who contribute to India’s growing technology and business ecosystem through creative ideas and digital solutions.</p><p class=\"ql-align-center\"><br></p><p><strong>Encourage Research</strong></p><p>The awards motivate students, researchers and scientists to create innovative solutions and contribute to scientific advancement and technological development in India.</p><p class=\"ql-align-center\"><br></p><p><strong>Strengthen Digital Economy</strong></p><p>The awards support sectors such as Artificial Intelligence, fintech, digital infrastructure and advanced technology industries that contribute to India’s digital economy and technological growth.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Innovation?</strong></p><p>Innovation means introducing new ideas, technologies and methods or improving existing systems for better results. Innovation helps increase productivity, efficiency and technological progress in different sectors of the economy.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is a Startup?</strong></p><p>A startup is a newly established business focused on innovation, technology and scalable growth. Startups usually develop digital services, mobile applications, new products and technology-based solutions that solve problems and create business opportunities.</p><p class=\"ql-align-center\"><br></p><p><strong>Why are National Innovation Awards Important?</strong></p><p><strong>Economic Growth</strong></p><p>Innovation increases industrial growth, productivity and investment opportunities, helping strengthen the economy and improve technological competitiveness.</p><p class=\"ql-align-center\"><br></p><p><strong>Employment Generation</strong></p><p>Technology startups and innovation-driven companies create new jobs and increase demand for skilled professionals in emerging sectors.</p><p class=\"ql-align-center\"><br></p><p><strong>Global Competitiveness</strong></p><p>Innovation helps India compete in global technology markets and strengthens India’s position in advanced research and digital industries.</p><p class=\"ql-align-center\"><br></p><p><strong>Scientific Development</strong></p><p>The awards encourage advanced research and support the development of indigenous technologies and scientific solutions.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Government Support for Innovation</strong></p><p><strong>Startup India</strong></p><p>Startup India was launched to support entrepreneurs, startup funding and India’s innovation ecosystem through policy support and financial assistance.</p><p class=\"ql-align-center\"><br></p><p><strong>Digital India</strong></p><p>Digital India promotes digital governance, online public services and technology infrastructure to strengthen India’s digital transformation.</p><p class=\"ql-align-center\"><br></p><p><strong>Atal Innovation Mission</strong></p><p>Atal Innovation Mission operates under NITI Aayog and encourages innovation, incubation centers and entrepreneurship across India.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Atal Innovation Mission (AIM)?</strong></p><p>Atal Innovation Mission is a government initiative aimed at promoting innovation culture, startup ecosystems and technological research in schools, colleges and industries.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Entrepreneurship?</strong></p><p>Entrepreneurship means starting and managing a business with innovation, leadership and risk-taking abilities. Entrepreneurs develop new business ideas and create employment opportunities through innovative products and services.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Innovation Awards</strong></p><p><strong>Recognition</strong></p><p>The awards provide national recognition to innovators, researchers and entrepreneurs for their contributions to science, technology and startup development.</p><p class=\"ql-align-center\"><br></p><p><strong>Investment Opportunities</strong></p><p>Award-winning startups and innovators attract investors, venture capital funding and business partnerships that support business expansion and technological growth.</p><p class=\"ql-align-center\"><br></p><p><strong>Technology Development</strong></p><p>The awards promote indigenous innovation, scientific research and the development of advanced technologies in India.</p><p class=\"ql-align-center\"><br></p><p><strong>Motivation for Youth</strong></p><p>The awards encourage young people to pursue careers in science, research, technology and entrepreneurship and inspire innovation among students and professionals.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>India’s Growing Innovation Ecosystem</strong></p><p>India is becoming a major global hub for startups, fintech, Artificial Intelligence and digital technology. The country is among the world’s leading nations in startup growth and technological innovation due to increasing government support and digital expansion.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><ul><li>Innovation policy</li><li>Startup ecosystem</li><li>Digital economy</li></ul><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><ul><li>Startup India</li><li>Atal Innovation Mission</li></ul><p>Innovation terminology</p><p><br></p><p><br></p>', '', 'AWARDS & HONOURS', '', '', NULL, 'active', 1, '2026-05-03 01:12:00', '2026-05-12 06:48:01', '2026-05-12 06:48:01');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(56, 'PM-KUSUM solar scheme expansion approved ', '', '<h2><strong>PM-KUSUM solar scheme expansion approved</strong> </h2><p><br></p><ul><li>Government approved expansion of PM-KUSUM scheme</li><li>Supports farmers through solar energy solutions and irrigation support</li><li>Promotes renewable energy use in agriculture sector</li><li>Helps reduce electricity costs and dependence on diesel pumps</li></ul><p><br></p>', '', '<p>PM-KUSUM Solar Scheme Expansion approved</p><p><strong>What is PM-KUSUM Scheme?</strong></p><p><strong>PM-KUSUM</strong> stands for:</p><ul><li><strong>Pradhan Mantri Kisan Urja Suraksha evam Utthaan Mahabhiyan</strong></li></ul><p>It is a Government of India scheme launched to promote solar energy in agriculture, support farmers with solar pumps and reduce dependence on diesel and traditional electricity. The scheme encourages clean energy use in rural areas and supports sustainable farming practices across India.</p><p class=\"ql-align-center\"><br></p><p><strong>Launched In</strong></p><ul><li><strong>2019</strong></li></ul><p>The PM-KUSUM scheme was launched by the Government of India to increase the use of renewable energy in the agricultural sector and improve farmers’ access to reliable irrigation facilities.</p><p class=\"ql-align-center\"><br></p><p><strong>Ministry</strong></p><p>Implemented by:</p><ul><li>Ministry of New and Renewable Energy (MNRE)</li></ul><p>The Ministry of New and Renewable Energy is responsible for implementing and monitoring renewable energy programs in India including solar, wind and green energy projects.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Aim of PM-KUSUM</strong></p><p>The main objective of PM-KUSUM is to provide solar-powered irrigation systems and renewable energy support to farmers. It also aims to reduce agricultural dependence on diesel pumps and lower electricity subsidy burdens on states.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Why was PM-KUSUM Expanded?</strong></p><p>The government expanded the PM-KUSUM scheme to increase solar energy use in agriculture, help more farmers access clean energy, reduce electricity subsidy burden and improve irrigation support in rural areas. The expansion also supports India’s renewable energy goals and sustainable development targets.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Solar Energy?</strong></p><p>Solar energy is energy obtained from sunlight. Solar panels convert sunlight into electrical energy using photovoltaic technology. Solar energy is considered one of the cleanest and most sustainable sources of renewable energy.</p><p class=\"ql-align-center\"><br></p><p><strong>How does Solar Power work?</strong></p><p><strong>Step 1</strong></p><p>Solar panels absorb sunlight and capture solar radiation from the Sun.</p><p class=\"ql-align-center\"><br></p><p><strong>Step 2</strong></p><p>Photovoltaic (PV) cells convert sunlight into electricity through a chemical and electrical process.</p><p class=\"ql-align-center\"><br></p><p><strong>Step 3</strong></p><p>The generated electricity powers:</p><ul><li>pumps</li><li>homes</li><li>irrigation systems</li></ul><p>This electricity can also be connected to the power grid for additional energy supply.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Renewable Energy?</strong></p><p>Renewable energy is energy generated from natural resources that are naturally replenished and environmentally friendly. These resources can be used repeatedly without getting exhausted quickly.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Non-Renewable Energy?</strong></p><p>Non-renewable energy is energy obtained from limited natural resources that may get exhausted over time. These energy sources are widely used but contribute heavily to pollution and carbon emissions.</p><p>Examples include:</p><ul><li>coal</li><li>petroleum</li><li>natural gas</li></ul><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Why is Renewable Energy Important?</strong></p><p><strong>Reduce Pollution</strong></p><p>Renewable energy produces lower:</p><ul><li>carbon emissions</li><li>air pollution</li></ul><p>This helps reduce environmental degradation and climate change.</p><p class=\"ql-align-center\"><br></p><p><strong>Energy Security</strong></p><p>Renewable energy reduces dependence on imported fuels and strengthens India’s energy independence.</p><p class=\"ql-align-center\"><br></p><p><strong>Sustainable Development</strong></p><p>Renewable energy supports long-term environmental protection and green economic growth.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of PM-KUSUM Scheme</strong></p><p><strong>1. Benefits Farmers</strong></p><p>The scheme provides reliable irrigation support and improves agricultural productivity in rural areas.</p><p class=\"ql-align-center\"><br></p><p><strong>2. Reduces Diesel Use</strong></p><p>Farmers no longer depend heavily on:</p><ul><li>diesel pumps</li></ul><p>This reduces fuel costs and pollution.</p><p class=\"ql-align-center\"><br></p><p><strong>3. Lower Electricity Cost</strong></p><p>Solar energy reduces electricity expenses for farmers and rural communities.</p><p class=\"ql-align-center\"><br></p><p><strong>4. Additional Income</strong></p><p>Farmers can sell extra solar power generated from solar plants to the electricity grid and earn additional income.</p><p class=\"ql-align-center\"><br></p><p><strong>5. Environment Protection</strong></p><p>The scheme promotes clean and green energy while reducing carbon emissions from traditional fuel usage.</p><p class=\"ql-align-center\"><br></p><p><strong>How does PM-KUSUM help Agriculture?</strong></p><p><strong>Better Irrigation</strong></p><p>The scheme ensures continuous water supply for farming through solar-powered pumps.</p><p class=\"ql-align-center\"><br></p><p><strong>Reduced Operational Cost</strong></p><p>Farmers save money on fuel and electricity expenses due to solar energy use.</p><p class=\"ql-align-center\"><br></p><p><strong>Energy Access in Rural Areas</strong></p><p>PM-KUSUM supports villages with limited electricity supply and improves rural infrastructure.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Green Energy?</strong></p><p>Green energy refers to environmentally clean energy that causes minimal pollution. Most renewable energy sources such as solar and wind energy are considered green energy sources.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is National Solar Mission?</strong></p><p>The National Solar Mission is a major government initiative launched to increase solar power generation capacity in India and promote large-scale adoption of solar energy technologies.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Green Hydrogen Mission?</strong></p><p>The Green Hydrogen Mission focuses on producing clean hydrogen fuel using renewable energy sources. It aims to reduce carbon emissions and promote sustainable industrial growth.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>India’s Renewable Energy Goals</strong></p><p>India aims to become a global leader in:</p><ul><li>solar power</li><li>green energy</li><li>sustainable development</li></ul><p>The country is rapidly expanding renewable energy infrastructure to achieve climate and energy security goals.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important topics include:</p><ul><li>Renewable energy</li><li>Sustainable agriculture</li><li>Climate change policy</li></ul><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important areas include:</p><ul><li>PM-KUSUM full form</li><li>Renewable energy types</li><li>Government schemes</li></ul><p><br></p>', '', 'SCHEMES & GOVT. POLICIES', '', '', NULL, 'active', 1, '2026-05-03 01:21:00', '2026-05-12 07:05:23', '2026-05-12 07:05:23');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(57, 'Skill India digital training initiative expanded ', '', '<h2><strong>Skill India digital training initiative expanded</strong> </h2><p><br></p><ul><li>Government expanded Skill India digital training programmes</li><li>Focus on AI, digital skills and emerging technologies</li><li>Aims to improve employability and industry-ready workforce</li><li>Supports youth skill development and digital economy growth</li></ul><p><br></p>', '', '<p>Skill India Digital Training Initiative Expanded</p><p><strong>What is Skill India?</strong></p><p><strong>Skill India Mission</strong> is a Government of India initiative launched to develop employable skills among youth, improve workforce quality and increase employment opportunities. The mission focuses on vocational training, technical education, digital skills and industry-based learning to prepare young people for modern employment needs.</p><p class=\"ql-align-center\"><br></p><p><strong>Launched In</strong></p><ul><li><strong>2015</strong></li></ul><p>The Skill India Mission was launched in 2015 to strengthen India’s workforce and improve the employability of youth across different sectors of the economy.</p><p class=\"ql-align-center\"><br></p><p><strong>Launched By</strong></p><ul><li>Narendra Modi</li></ul><p>The initiative was launched by Prime Minister Narendra Modi as part of the government’s focus on skill development and employment generation.</p><p class=\"ql-align-center\"><br></p><p><strong>Ministry</strong></p><p>Implemented by:</p><ul><li>Ministry of Skill Development and Entrepreneurship (MSDE)</li></ul><p>The Ministry of Skill Development and Entrepreneurship is responsible for promoting vocational training, entrepreneurship and skill-based education across India.</p><p class=\"ql-align-center\"><br></p><p><strong>Current Minister</strong></p><ul><li>Jayant Chaudhary <em>(2026)</em></li></ul><p>The ministry works to improve workforce quality and align skill development programs with industry requirements.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Objective of Skill India</strong></p><p>The main objective of Skill India is to train youth with job-oriented skills, digital knowledge and technical expertise for better employment opportunities and entrepreneurship development. The mission aims to create a skilled and competitive workforce for India’s growing economy.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Digital Training?</strong></p><p>Digital training means learning through online platforms and technology tools. It allows students and workers to gain knowledge using internet-based systems and digital devices.</p><p>Training may include:</p><ul><li>coding</li><li>AI</li><li>computer applications</li><li>cybersecurity</li><li>digital communication</li></ul><p>Digital training supports flexible and technology-based education systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Why was the Digital Training Initiative Expanded?</strong></p><p>The government expanded the digital training initiative because modern industries increasingly require digital skills, AI and technology sectors are growing rapidly and the digital economy needs a skilled workforce. The expansion also aims to improve employment opportunities in technology-driven sectors.</p><p class=\"ql-align-center\"><br></p><p><strong>What is AI?</strong></p><p><strong>AI (Artificial Intelligence)</strong> is technology that enables machines and software to:</p><ul><li>learn</li><li>think</li><li>analyze</li><li>make decisions like humans</li></ul><p>AI systems use data and machine learning algorithms to perform intelligent tasks and automation.</p><p class=\"ql-align-center\"><br></p><p><strong>Father of AI</strong></p><ul><li>John McCarthy</li></ul><p>John McCarthy is known as the “Father of Artificial Intelligence” because he coined the term Artificial Intelligence in 1956.</p><p class=\"ql-align-center\"><br></p><p><strong>Examples of AI</strong></p><p>Examples of AI include:</p><ul><li>ChatGPT</li><li>Voice assistants</li><li>Face recognition</li><li>Self-driving systems</li><li>AI chatbots</li></ul><p>These technologies are widely used in industries such as healthcare, banking, education and cybersecurity.</p><p class=\"ql-align-center\"><br></p><p><strong>What are Digital Skills?</strong></p><p>Digital skills are abilities needed to use computers, operate digital tools, work with internet technology and manage online systems. These skills are important for employment in modern industries and digital services.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What are Emerging Technologies?</strong></p><p>Emerging technologies are new and advanced technologies shaping future industries and economies.</p><p>Examples include:</p><ul><li>Artificial Intelligence</li><li>Robotics</li><li>Quantum Computing</li><li>Blockchain</li><li>Internet of Things (IoT)</li></ul><p>These technologies are transforming manufacturing, healthcare, communication and financial systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Why are AI and Digital Skills Important?</strong></p><p><strong>Future Jobs</strong></p><p>Modern industries increasingly require:</p><ul><li>digital knowledge</li><li>technical expertise</li></ul><p>Technology-based jobs are expanding rapidly across the world.</p><p class=\"ql-align-center\"><br></p><p><strong>Economic Growth</strong></p><p>Technology sectors contribute to:</p><ul><li>digital economy</li><li>innovation</li><li>productivity</li></ul><p>Digital industries improve efficiency and create new business opportunities.</p><p class=\"ql-align-center\"><br></p><p><strong>Global Competition</strong></p><p>Countries compete in:</p><ul><li>AI</li><li>software</li><li>advanced technology industries</li></ul><p>Strong digital capabilities help countries remain globally competitive.</p><p class=\"ql-align-center\"><br></p><p><strong>How does AI support Digital Training?</strong></p><p><strong>Personalized Learning</strong></p><p>AI systems analyze student performance and provide:</p><ul><li>customized learning content</li></ul><p>This improves learning speed and skill development.</p><p class=\"ql-align-center\"><br></p><p><strong>Smart Assessment</strong></p><p>AI helps evaluate:</p><ul><li>progress</li><li>skill gaps</li><li>performance</li></ul><p>This allows better monitoring of student learning outcomes.</p><p class=\"ql-align-center\"><br></p><p><strong>Virtual Training</strong></p><p>AI-powered platforms provide:</p><ul><li>online classes</li><li>simulations</li><li>digital practice systems</li></ul><p>These tools improve accessibility and remote learning opportunities.</p><p class=\"ql-align-center\"><br></p><p><strong>How does Skill India support Youth Skill Development?</strong></p><p><strong>Job-Oriented Training</strong></p><p>Skill India provides practical industry skills that help youth become employable and industry-ready.</p><p class=\"ql-align-center\"><br></p><p><strong>Industry Collaboration</strong></p><p>Training programs match:</p><ul><li>market requirements</li><li>industrial needs</li></ul><p>This ensures that trainees develop relevant professional skills.</p><p class=\"ql-align-center\"><br></p><p><strong>Entrepreneurship Support</strong></p><p>The mission encourages startups and self-employment opportunities through innovation and business training.</p><p class=\"ql-align-center\"><br></p><p><strong>Rural Skill Development</strong></p><p>Training programs reach:</p><ul><li>villages</li><li>small towns</li><li>underdeveloped regions</li></ul><p>This supports inclusive development and employment generation in rural India.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is PMKVY?</strong></p><p><strong>Pradhan Mantri Kaushal Vikas Yojana</strong> provides free skill training, certification and employment support. It aims to improve employability and provide industry-relevant training to youth.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Skill India Digital Expansion</strong></p><p><strong>Better Employment</strong></p><p>Youth become industry-ready and gain skills required for modern workplaces.</p><p class=\"ql-align-center\"><br></p><p><strong>Digital Economy Growth</strong></p><p>The initiative supports the technology sector, startups and digital business ecosystem.</p><p class=\"ql-align-center\"><br></p><p><strong>Increased Productivity</strong></p><p>A skilled workforce improves industrial efficiency and economic output.</p><p class=\"ql-align-center\"><br></p><p><strong>Innovation Support</strong></p><p>The programme encourages:</p><ul><li>research</li><li>technology development</li><li>entrepreneurship</li></ul><p>This strengthens India’s innovation ecosystem.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important topics include:</p><ul><li>Human resource development</li><li>Digital economy</li><li>Skill development policy</li></ul><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important areas include:</p><ul><li>Skill India facts</li><li>PMKVY</li><li>AI basics</li></ul><p><br></p>', '', 'SCHEMES & GOVT. POLICIES', '', '', NULL, 'active', 1, '2026-05-03 01:37:00', '2026-05-12 07:15:18', '2026-05-12 07:15:18');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(58, 'Global Renewable Energy Summit held', '', '<h2><strong>Global Renewable Energy Summit held</strong></h2><p><strong><span class=\"ql-cursor\">﻿</span></strong></p><ul><li>International summit focused on renewable and green energy development</li><li>Discussions held on clean energy investments and sustainability</li><li>Countries highlighted solar, wind and green hydrogen projects</li><li>Promotes global cooperation against climate change</li></ul><p><br></p>', '', '<p>Global Renewable Energy Summit held</p><p><strong>What is Renewable Energy?</strong></p><p>Renewable energy is energy generated from natural resources that are naturally replenished and do not exhaust quickly. These energy sources are eco-friendly, sustainable and produce low levels of pollution compared to fossil fuels. Renewable energy plays an important role in reducing environmental damage and supporting clean economic growth.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Green Energy?</strong></p><p>Green energy means clean energy that causes minimal environmental pollution. Most renewable energy sources are considered green energy sources because they produce lower greenhouse gas emissions and reduce environmental harm.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Non-Renewable Energy?</strong></p><p>Non-renewable energy is energy obtained from limited natural resources that may get exhausted over time.</p><p>Examples include:</p><ul><li>coal</li><li>petroleum</li><li>natural gas</li></ul><p>These fuels are widely used for industrial and transportation purposes but contribute heavily to pollution and climate change.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is Renewable Energy Important?</strong></p><p><strong>Reduce Pollution</strong></p><p>Renewable energy produces less:</p><ul><li>carbon dioxide</li><li>greenhouse gases</li></ul><p>This helps improve air quality and reduce environmental pollution.</p><p class=\"ql-align-center\"><br></p><p><strong>Fight Climate Change</strong></p><p>Renewable energy helps reduce:</p><ul><li>global warming</li><li>environmental damage</li></ul><p>By lowering fossil fuel use, countries can decrease greenhouse gas emissions.</p><p class=\"ql-align-center\"><br></p><p><strong>Energy Security</strong></p><p>Renewable energy reduces dependence on imported fossil fuels and strengthens long-term energy independence.</p><p class=\"ql-align-center\"><br></p><p><strong>What is the Global Renewable Energy Summit?</strong></p><p>The Global Renewable Energy Summit is an international summit where countries, organizations and companies discuss renewable energy, green investments, climate solutions and sustainable development. The summit focuses on global cooperation for clean energy transition and strategies to achieve climate goals.</p><p class=\"ql-align-center\"><br></p><p><strong>Where was the Summit held?</strong></p><p>Recent global renewable and climate-energy discussions in 2026 were organized in:</p><ul><li>Abu Dhabi, UAE</li><li>Bonn, Germany</li><li>New York, USA</li></ul><p>These meetings were held under various international renewable energy and climate forums involving governments, climate organizations and industry leaders.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What was discussed in the Summit?</strong></p><p><strong>Green Energy Investments</strong></p><p>Countries discussed:</p><ul><li>solar projects</li><li>wind farms</li><li>green hydrogen</li><li>clean technology funding</li></ul><p>The discussions focused on increasing investments in renewable infrastructure and sustainable technologies.</p><p class=\"ql-align-center\"><br></p><p><strong>Climate Change Solutions</strong></p><p>Strategies were discussed to reduce:</p><ul><li>carbon emissions</li><li>fossil fuel dependence</li></ul><p>Countries emphasized the need for cleaner energy systems and global environmental cooperation.</p><p class=\"ql-align-center\"><br></p><p><strong>Sustainable Development</strong></p><p>The summit focused on:</p><ul><li>eco-friendly economic growth</li><li>renewable infrastructure</li></ul><p>Participants discussed balancing economic progress with environmental protection.</p><p class=\"ql-align-center\"><br></p><p><strong>Why are Global Renewable Energy Summits needed?</strong></p><p><strong>Climate Crisis</strong></p><p>Rising global temperatures and pollution require:</p><ul><li>urgent environmental action</li></ul><p>International cooperation is essential to address climate-related challenges.</p><p class=\"ql-align-center\"><br></p><p><strong>Increasing Energy Demand</strong></p><p>Countries need:</p><ul><li>sustainable and affordable energy</li></ul><p>Renewable energy helps meet growing electricity demand without increasing pollution.</p><p class=\"ql-align-center\"><br></p><p><strong>International Cooperation</strong></p><p>Climate change affects all nations globally, making international coordination necessary for effective solutions.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Climate Change?</strong></p><p>Climate change refers to long-term changes in Earth’s temperature, rainfall and weather patterns mainly caused by greenhouse gas emissions from human activities such as fossil fuel burning and industrial pollution.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What are Greenhouse Gases?</strong></p><p>Greenhouse gases are gases that trap heat in Earth’s atmosphere.</p><p>Examples include:</p><ul><li>Carbon dioxide (CO₂)</li><li>Methane</li><li>Nitrous oxide</li></ul><p>These gases are major contributors to global warming and climate change.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is COP?</strong></p><p>COP means:</p><ul><li>Conference of the Parties</li></ul><p>It is the annual global climate meeting organized under the:</p><ul><li>UN Framework Convention on Climate Change (UNFCCC)</li></ul><p>COP meetings discuss international climate agreements and environmental policies.</p><p class=\"ql-align-center\"><br></p><p><strong>India’s Role in Renewable Energy</strong></p><p><strong>International Solar Alliance (ISA)</strong></p><p>The International Solar Alliance is a joint initiative by:</p><ul><li>India and France</li></ul><p>It promotes global solar energy cooperation and supports solar projects in different countries.</p><p class=\"ql-align-center\"><br></p><p><strong>National Solar Mission</strong></p><p>The National Solar Mission promotes solar power generation and expansion of renewable energy infrastructure in India.</p><p class=\"ql-align-center\"><br></p><p><strong>Green Hydrogen Mission</strong></p><p>The Green Hydrogen Mission supports the development of clean hydrogen fuel using renewable energy technologies.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Global Renewable Cooperation</strong></p><p><strong>Technology Sharing</strong></p><p>Countries exchange:</p><ul><li>renewable technologies</li><li>research</li><li>innovation</li></ul><p>This improves clean energy development and scientific progress.</p><p class=\"ql-align-center\"><br></p><p><strong>Investment Growth</strong></p><p>Global cooperation supports clean energy funding and renewable infrastructure expansion.</p><p class=\"ql-align-center\"><br></p><p><strong>Environmental Protection</strong></p><p>Renewable cooperation helps reduce:</p><ul><li>pollution</li><li>carbon emissions</li></ul><p>This contributes to climate protection and cleaner ecosystems.</p><p class=\"ql-align-center\"><br></p><p><strong>Sustainable Future</strong></p><p>Renewable energy cooperation promotes long-term energy security and sustainable development.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important topics include:</p><ul><li>Climate diplomacy</li><li>Renewable energy policy</li><li>Sustainable development</li></ul><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important areas include:</p><ul><li>Renewable energy sources</li><li>COP meetings</li><li>Climate organizations</li></ul><p><br></p><p><br></p><p><br></p>', '', 'SUMMITS & CONFERENCES', '', '', NULL, 'active', 1, '2026-05-03 01:49:00', '2026-05-12 07:32:16', '2026-05-12 07:32:16');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(59, 'Data Protection compliance framework updated ', '', '<h2><strong>Data Protection compliance framework updated</strong> </h2><p><br></p><ul><li>Government updated data protection compliance framework</li><li>Focus on strengthening digital privacy and data security norms</li><li>Aims to improve protection of personal and online information</li><li>Supports safe and transparent digital governance</li></ul><p><br></p>', '', '<p><strong>Data Protection Compliance Framework Updated</strong></p><p><strong>What is Data?</strong></p><p>Data means raw facts, information and records collected in digital or physical form. Data can include names, phone numbers, bank details, photos, emails, passwords and online activity. In today’s digital world, data has become extremely valuable because governments, companies and individuals depend heavily on digital systems for communication, banking, shopping and online services.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Data Protection?</strong></p><p>Data protection means safeguarding data from misuse, theft, unauthorized access and cyber attacks. It ensures privacy, security and safe use of personal information. Data protection is important because personal and financial information stored online can be misused if proper security systems are not maintained.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is Data Protection Needed?</strong></p><p><strong>Rising Digital Usage</strong></p><p>People increasingly use online banking, social media, e-commerce and digital payments. As digital services expand rapidly, large amounts of personal information are stored on online platforms, increasing the need for stronger protection systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Cyber Crime Increase</strong></p><p>Online fraud and hacking incidents are increasing globally. Cyber criminals target digital systems to steal financial information, passwords and confidential records.</p><p class=\"ql-align-center\"><br></p><p><strong>Personal Privacy</strong></p><p>Citizens’ personal information must remain secure. Data protection laws help individuals maintain control over how their information is collected and used.</p><p class=\"ql-align-center\"><br></p><p><strong>National Security</strong></p><p>Sensitive government and defence data require protection. Cyber attacks on important systems may threaten national security and public safety.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Digital Privacy?</strong></p><p>Digital privacy means protection of personal information shared online. It gives individuals control over how their data is collected, stored, shared and used. Digital privacy is becoming increasingly important as people use mobile apps, social media and online services daily.</p><p class=\"ql-align-center\"><br></p><p><strong>Examples of Digital Privacy</strong></p><p>Examples of digital privacy include protecting passwords, securing social media accounts, safe online transactions and protection of private communication. Individuals must use secure systems to prevent misuse of their personal information.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Data Security?</strong></p><p>Data security means protecting digital information from hacking, cyber attacks, data leakage and unauthorized access. Organizations use advanced security technologies to ensure that sensitive information remains protected.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Cyber Security?</strong></p><p>Cyber security means protection of computer systems, networks and digital platforms from cyber threats. It includes technologies and practices designed to prevent cyber attacks and protect digital infrastructure.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is Data Protection Compliance Framework?</strong></p><p>A Data Protection Compliance Framework is a set of laws, rules and guidelines that organizations must follow to protect user data, ensure digital privacy and maintain cyber security. It helps companies and institutions securely manage user information and prevent misuse.</p><p class=\"ql-align-center\"><br></p><p><strong>Why was the Compliance Framework Updated?</strong></p><p><strong>Growing Digital Economy</strong></p><p>India’s digital services and online transactions are increasing rapidly. Expansion of fintech, e-commerce and digital governance requires stronger protection systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Data Breach Risks</strong></p><p>Many organizations face cyber attacks, data leaks and online fraud. Updated rules help improve security standards and reduce digital risks.</p><p class=\"ql-align-center\"><br></p><p><strong>Better User Protection</strong></p><p>The government aims to strengthen digital rights, online safety and data privacy for citizens using digital platforms and online services.</p><p class=\"ql-align-center\"><br></p><p><strong>What is the DPDP Act?</strong></p><p><strong>DPDP Act</strong> stands for <strong>Digital Personal Data Protection Act, 2023</strong>. It is India’s major law for personal data protection and digital privacy regulation. The Act provides legal safeguards for handling personal data and establishes rules for organizations collecting user information.</p><p class=\"ql-align-center\"><br></p><p><strong>What Bill was Passed related to Data Protection?</strong></p><p>The <strong>Digital Personal Data Protection Bill, 2023</strong> was passed by Parliament and later became the <strong>Digital Personal Data Protection Act, 2023</strong>. This is an important polity-based topic for exams because it relates to citizens’ right to privacy, digital governance and constitutional protections in India.</p><p>The law was passed to regulate collection, storage and processing of personal data by companies, institutions and digital platforms. It also provides penalties for misuse of personal information and strengthens user rights in the digital ecosystem.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Features of DPDP Act</strong></p><p><strong>User Consent</strong></p><p>Organizations must take permission before collecting personal data. Users must be informed about how their data will be used.</p><p class=\"ql-align-center\"><br></p><p><strong>Right to Privacy</strong></p><p>Citizens can control use of their personal data and request correction or deletion of information when required.</p><p class=\"ql-align-center\"><br></p><p><strong>Data Protection Obligations</strong></p><p>Companies must securely store user information and maintain strong cyber security systems to prevent data breaches.</p><p class=\"ql-align-center\"><br></p><p><strong>Penalties</strong></p><p>Heavy fines can be imposed for data misuse, unauthorized sharing and security violations.</p><p class=\"ql-align-center\"><br></p><p><strong>Importance of Digital Privacy</strong></p><p><strong>Protects Individuals</strong></p><p>Digital privacy prevents identity theft, financial fraud and misuse of personal information. Secure systems protect citizens from online scams.</p><p class=\"ql-align-center\"><br></p><p><strong>Builds Trust</strong></p><p>People feel safer using digital platforms, online banking and e-governance services when proper privacy rules exist.</p><p class=\"ql-align-center\"><br></p><p><strong>Supports Digital Economy</strong></p><p>Secure systems encourage online business, fintech growth and digital payments, helping India’s digital economy expand safely.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Strong Data Protection</strong></p><p><strong>Safer Online Transactions</strong></p><p>Strong data protection safeguards digital payments, internet banking and online financial services.</p><p class=\"ql-align-center\"><br></p><p><strong>Reduced Cyber Fraud</strong></p><p>Cyber security systems reduce hacking, scams and unauthorized access to digital platforms.</p><p class=\"ql-align-center\"><br></p><p><strong>Better Governance</strong></p><p>Secure digital systems improve e-governance and help government departments safely manage public information.</p><p class=\"ql-align-center\"><br></p><p><strong>International Standards</strong></p><p>Strong data protection laws help India align with global digital privacy standards followed by developed countries.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Data protection, digital governance, cyber laws and right to privacy are important topics for governance and polity preparation.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important areas include DPDP Act, cyber security basics, digital privacy and important government organizations related to data protection.</p><p><br></p>', '', 'AMENDMENTS & BILLS', '', '', NULL, 'active', 1, '2026-05-03 02:07:00', '2026-05-12 09:08:10', '2026-05-12 09:08:10');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(60, 'New CBDT chairman appointed ', 'नए सीबीडीटी अध्यक्ष नियुक्त', '<h2><strong>New CBDT chairman appointed</strong></h2><p><br></p><ul><li>New Chairman appointed to CBDT (Central Board of Direct Taxes)</li><li>Focus on strengthening tax and revenue administration</li><li>Aims to improve income tax governance and compliance</li><li>Supports transparent and efficient tax collection system</li></ul>', '<h2><strong>नए सीबीडीटी अध्यक्ष नियुक्त</strong></h2><p><br></p><ul><li>सीबीडीटी (केंद्रीय प्रत्यक्ष कर बोर्ड) में नया अध्यक्ष नियुक्त</li><li>कर और राजस्व प्रशासन को मजबूत करने पर ध्यान दें</li><li>इसका उद्देश्य आयकर प्रशासन और अनुपालन में सुधार करना है</li><li>पारदर्शी और कुशल कर संग्रह प्रणाली का समर्थन करता है</li></ul>', '<p><strong>New CBDT Chairman appointed</strong></p><p><strong>What is CBDT?</strong></p><p><strong>CBDT</strong> stands for <strong>Central Board of Direct Taxes</strong>. It is the highest authority responsible for administration of direct taxes in India. CBDT works under the Ministry of Finance, specifically under the Department of Revenue. It plays an important role in India’s taxation system by managing tax policies, tax collection and implementation of direct tax laws across the country.</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters</strong></p><ul><li><strong>New Delhi</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>Established</strong></p><ul><li><strong>1964</strong></li></ul><p>under:</p><ul><li>Central Boards of Revenue Act, 1963.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Current Chairman</strong></p><ul><li>Ravi Agrawal <em>(2026)</em></li></ul><p class=\"ql-align-center\"><br></p><p><strong>What are Direct Taxes?</strong></p><p>Direct taxes are taxes paid directly by individuals or organizations to the government. The burden of tax cannot be transferred to another person. These taxes are imposed mainly on income, profits and wealth earned by individuals and companies.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What are Indirect Taxes?</strong></p><p>Indirect taxes are taxes collected by intermediaries and paid indirectly by consumers. In this system, the burden of tax can be transferred from one person to another through prices of goods and services.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Main Functions of CBDT</strong></p><p><strong>Tax Administration</strong></p><p>CBDT manages direct tax collection, tax policies and implementation of taxation systems in India. It supervises smooth functioning of direct tax administration.</p><p class=\"ql-align-center\"><br></p><p><strong>Income Tax Regulation</strong></p><p>CBDT supervises the Income Tax Department and ensures proper tax compliance systems for individuals and businesses.</p><p class=\"ql-align-center\"><br></p><p><strong>Anti-Tax Evasion</strong></p><p>CBDT controls black money, tax fraud and illegal tax avoidance activities through investigations and monitoring systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Policy Formulation</strong></p><p>CBDT advises the government on taxation reforms, tax laws and revenue policies to improve India’s financial governance and economic administration.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Revenue Administration?</strong></p><p>Revenue administration means management and collection of taxes and government income. It ensures smooth tax collection, financial governance and economic regulation. Efficient revenue administration helps governments fund welfare schemes, infrastructure and development projects.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is CBDT Important?</strong></p><p><strong>Government Revenue</strong></p><p>Taxes are major sources of government income. CBDT ensures efficient tax collection which supports national expenditure and public welfare programmes.</p><p class=\"ql-align-center\"><br></p><p><strong>Economic Development</strong></p><p>Tax revenue funds infrastructure, education, defence and welfare schemes. Proper tax administration supports economic growth and development activities.</p><p class=\"ql-align-center\"><br></p><p><strong>Financial Stability</strong></p><p>CBDT supports fiscal management and national budgeting by maintaining stable revenue collection systems for the government.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Major Functions of Income Tax Department</strong></p><p><strong>Tax Collection</strong></p><p>The Income Tax Department collects income taxes from individuals, businesses and corporations according to tax laws and regulations.</p><p class=\"ql-align-center\"><br></p><p><strong>Tax Investigation</strong></p><p>The department investigates tax evasion, financial fraud and undisclosed income to maintain transparency and legal compliance.</p><p class=\"ql-align-center\"><br></p><p><strong>Return Processing</strong></p><p>It processes Income Tax Returns (ITR) filed by taxpayers through digital and online systems.</p><p class=\"ql-align-center\"><br></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Recent Reforms in Tax Administration</strong></p><p><strong>Faceless Assessment</strong></p><p>Online tax assessment systems reduce physical interaction and improve transparency in tax administration.</p><p class=\"ql-align-center\"><br></p><p><strong>Digital Tax Filing</strong></p><p>Online ITR filing systems have improved convenience, efficiency and speed of tax return processing.</p><p class=\"ql-align-center\"><br></p><p><strong>AI-Based Monitoring</strong></p><p>Technology and Artificial Intelligence are increasingly used for fraud detection, data analysis and tax compliance monitoring.</p><p class=\"ql-align-center\"><br></p><p><strong>Benefits of Strong Tax Administration</strong></p><p><strong>Better Revenue Collection</strong></p><p>Efficient tax administration supports government development projects and public expenditure.</p><p class=\"ql-align-center\"><br></p><p><strong>Transparency</strong></p><p>Strong systems reduce corruption, illegal transactions and tax fraud.</p><p class=\"ql-align-center\"><br></p><p><strong>Digital Governance</strong></p><p>Digital tax services improve efficiency, accessibility and taxpayer convenience through online systems.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important topics include tax administration, fiscal governance, revenue systems and economic management.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important areas include CBDT full form, direct taxes, tax terminology and functions of tax authorities.</p><p><br></p>', '<p><strong>नए सीबीडीटी अध्यक्ष नियुक्त</strong></p><p><strong>सीबीडीटी क्या है?</strong></p><p><strong>सीबीडीटी</strong>के लिए खड़ा है<strong>केन्द्रीय प्रत्यक्ष कर बोर्ड</strong>. यह भारत में प्रत्यक्ष करों के प्रशासन के लिए जिम्मेदार सर्वोच्च प्राधिकरण है। सीबीडीटी वित्त मंत्रालय, विशेष रूप से राजस्व विभाग के तहत काम करता है। यह देश भर में कर नीतियों, कर संग्रह और प्रत्यक्ष कर कानूनों के कार्यान्वयन का प्रबंधन करके भारत की कराधान प्रणाली में एक महत्वपूर्ण भूमिका निभाता है।</p><p class=\"ql-align-center\"><br></p><p><strong>मुख्यालय</strong></p><ul><li><strong>नई दिल्ली</strong></li></ul><p class=\"ql-align-center\"><br></p><p><strong>स्थापित</strong></p><ul><li><strong>1964</strong></li></ul><p>अंतर्गत:</p><ul><li>केंद्रीय राजस्व बोर्ड अधिनियम, 1963।</li></ul><p class=\"ql-align-center\"><br></p><p><strong>वर्तमान अध्यक्ष</strong></p><ul><li>रवि अग्रवाल<em>(2026)</em></li></ul><p class=\"ql-align-center\"><br></p><p><strong>प्रत्यक्ष कर क्या हैं?</strong></p><p>प्रत्यक्ष कर व्यक्तियों या संगठनों द्वारा सरकार को सीधे भुगतान किये जाने वाले कर हैं। कर का बोझ किसी अन्य व्यक्ति पर स्थानांतरित नहीं किया जा सकता। ये कर मुख्य रूप से व्यक्तियों और कंपनियों द्वारा अर्जित आय, मुनाफे और धन पर लगाए जाते हैं।</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>अप्रत्यक्ष कर क्या हैं?</strong></p><p>अप्रत्यक्ष कर बिचौलियों द्वारा एकत्र किए गए कर हैं और उपभोक्ताओं द्वारा अप्रत्यक्ष रूप से भुगतान किए जाते हैं। इस प्रणाली में कर का बोझ वस्तुओं और सेवाओं की कीमतों के माध्यम से एक व्यक्ति से दूसरे व्यक्ति पर स्थानांतरित किया जा सकता है।</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>सीबीडीटी के मुख्य कार्य</strong></p><p><strong>कर प्रशासन</strong></p><p>सीबीडीटी भारत में प्रत्यक्ष कर संग्रह, कर नीतियों और कराधान प्रणालियों के कार्यान्वयन का प्रबंधन करता है। यह प्रत्यक्ष कर प्रशासन के सुचारू कामकाज की निगरानी करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>आयकर विनियमन</strong></p><p>सीबीडीटी आयकर विभाग की निगरानी करता है और व्यक्तियों और व्यवसायों के लिए उचित कर अनुपालन प्रणाली सुनिश्चित करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>कर चोरी विरोधी</strong></p><p>सीबीडीटी जांच और निगरानी प्रणालियों के माध्यम से काले धन, कर धोखाधड़ी और अवैध कर बचाव गतिविधियों को नियंत्रित करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>नीति निर्धारण</strong></p><p>सीबीडीटी भारत के वित्तीय प्रशासन और आर्थिक प्रशासन में सुधार के लिए कराधान सुधारों, कर कानूनों और राजस्व नीतियों पर सरकार को सलाह देता है।</p><p class=\"ql-align-center\"><br></p><p><strong>राजस्व प्रशासन क्या है?</strong></p><p>राजस्व प्रशासन का अर्थ है करों और सरकारी आय का प्रबंधन और संग्रहण। यह सुचारू कर संग्रह, वित्तीय प्रशासन और आर्थिक विनियमन सुनिश्चित करता है। कुशल राजस्व प्रशासन सरकारों को कल्याणकारी योजनाओं, बुनियादी ढांचे और विकास परियोजनाओं को निधि देने में मदद करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>सीबीडीटी क्यों महत्वपूर्ण है?</strong></p><p><strong>सरकारी राजस्व</strong></p><p>कर सरकारी आय के प्रमुख स्रोत हैं। सीबीडीटी कुशल कर संग्रह सुनिश्चित करता है जो राष्ट्रीय व्यय और लोक कल्याण कार्यक्रमों का समर्थन करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>आर्थिक विकास</strong></p><p>कर राजस्व बुनियादी ढांचे, शिक्षा, रक्षा और कल्याण योजनाओं को निधि देता है। उचित कर प्रशासन आर्थिक वृद्धि और विकास गतिविधियों का समर्थन करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>वित्तीय स्थिरता</strong></p><p>सीबीडीटी सरकार के लिए स्थिर राजस्व संग्रह प्रणाली बनाए रखकर राजकोषीय प्रबंधन और राष्ट्रीय बजट का समर्थन करता है।</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>आयकर विभाग के प्रमुख कार्य</strong></p><p><strong>कर संग्रहण</strong></p><p>आयकर विभाग कर कानूनों और विनियमों के अनुसार व्यक्तियों, व्यवसायों और निगमों से आयकर एकत्र करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>कर जांच</strong></p><p>विभाग पारदर्शिता और कानूनी अनुपालन बनाए रखने के लिए कर चोरी, वित्तीय धोखाधड़ी और अघोषित आय की जांच करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>वापसी प्रसंस्करण</strong></p><p>यह करदाताओं द्वारा दाखिल आयकर रिटर्न (आईटीआर) को डिजिटल और ऑनलाइन सिस्टम के माध्यम से संसाधित करता है।</p><p class=\"ql-align-center\"><br></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>कर प्रशासन में हालिया सुधार</strong></p><p><strong>फेसलेस असेसमेंट</strong></p><p>ऑनलाइन कर मूल्यांकन प्रणाली भौतिक संपर्क को कम करती है और कर प्रशासन में पारदर्शिता में सुधार करती है।</p><p class=\"ql-align-center\"><br></p><p><strong>डिजिटल टैक्स फाइलिंग</strong></p><p>ऑनलाइन आईटीआर फाइलिंग सिस्टम ने टैक्स रिटर्न प्रोसेसिंग की सुविधा, दक्षता और गति में सुधार किया है।</p><p class=\"ql-align-center\"><br></p><p><strong>एआई-आधारित निगरानी</strong></p><p>धोखाधड़ी का पता लगाने, डेटा विश्लेषण और कर अनुपालन निगरानी के लिए प्रौद्योगिकी और आर्टिफिशियल इंटेलिजेंस का तेजी से उपयोग किया जा रहा है।</p><p class=\"ql-align-center\"><br></p><p><strong>मजबूत कर प्रशासन के लाभ</strong></p><p><strong>बेहतर राजस्व संग्रहण</strong></p><p>कुशल कर प्रशासन सरकारी विकास परियोजनाओं और सार्वजनिक व्यय का समर्थन करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>पारदर्शिता</strong></p><p>मजबूत प्रणालियाँ भ्रष्टाचार, अवैध लेनदेन और कर धोखाधड़ी को कम करती हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>डिजिटल शासन</strong></p><p>डिजिटल कर सेवाएं ऑनलाइन सिस्टम के माध्यम से दक्षता, पहुंच और करदाता सुविधा में सुधार करती हैं।</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>परीक्षा के लिए महत्व</strong></p><p><strong>यूपीएससी</strong></p><p>महत्वपूर्ण विषयों में कर प्रशासन, राजकोषीय प्रशासन, राजस्व प्रणाली और आर्थिक प्रबंधन शामिल हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>एसएससी/रेलवे/बैंकिंग</strong></p><p>महत्वपूर्ण क्षेत्रों में सीबीडीटी का पूर्ण रूप, प्रत्यक्ष कर, कर शब्दावली और कर अधिकारियों के कार्य शामिल हैं।</p>', 'APPOINTMENTS NEWS', '', '', NULL, 'active', 1, '2026-05-02 22:12:00', '2026-05-12 09:24:19', '2026-05-13 06:28:29');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(61, 'World Economic Outlook updated by IMF ', '', '<h2><strong>World Economic Outlook updated by IMF</strong> </h2><p><br></p><ul><li>International Monetary Fund (IMF) released updated World Economic Outlook report</li><li>Global and country-wise economic growth projections were revised</li><li>Report analyzes inflation, trade and financial conditions</li><li>Helps governments and investors understand global economic trends</li></ul><p><br></p>', '', '<p><strong>World Economic Outlook updated by IMF</strong></p><p><strong>What is IMF?</strong></p><p><strong>IMF</strong> stands for <strong>International Monetary Fund</strong>. It is an international financial organization that works to maintain global economic stability, support international trade, provide financial assistance to countries and monitor global economic growth. IMF plays an important role in maintaining stability in the international financial system and helping countries facing economic difficulties.</p><p class=\"ql-align-center\"><br></p><p><strong>Established</strong></p><ul><li><strong>1944</strong></li></ul><p>during:</p><ul><li>Bretton Woods Conference.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Headquarters</strong></p><ul><li>Washington D.C., USA.</li></ul><p class=\"ql-align-center\"><br></p><p><strong>Member Countries</strong></p><ul><li><strong>190+ countries</strong> participate in IMF.</li></ul><p>India is also a member. IMF membership allows countries to cooperate on international financial and economic matters.</p><p class=\"ql-align-center\"><br></p><p><strong>Current Managing Director (Head of IMF)</strong></p><ul><li>Kristalina Georgieva <em>(2026)</em></li></ul><p><em>(IMF does not use the term “chairman”; its top executive is called Managing Director.)</em></p><p class=\"ql-align-center\"><br></p><p><strong>Why was IMF Created?</strong></p><p>IMF was established after World War II to ensure international monetary cooperation, economic stability and balanced global trade. The organization was created to prevent financial crises and promote stable international economic relations.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Objectives of IMF</strong></p><p><strong>Global Financial Stability</strong></p><p>IMF works to maintain a stable international financial system and reduce risks of economic crises.</p><p class=\"ql-align-center\"><br></p><p><strong>Economic Growth</strong></p><p>The organization supports sustainable economic development and financial stability among member countries.</p><p class=\"ql-align-center\"><br></p><p><strong>International Trade</strong></p><p>IMF promotes smooth global trade and investment by encouraging stable exchange rates and economic cooperation.</p><p class=\"ql-align-center\"><br></p><p><strong>Financial Assistance</strong></p><p>IMF provides loans to countries facing economic crisis, debt problems or foreign exchange shortages.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>What is World Economic Outlook (WEO)?</strong></p><p>The <strong>World Economic Outlook Report</strong> is an important IMF publication that analyzes global economic conditions, growth trends, inflation, unemployment and trade performance. It provides forecasts and economic analysis for countries and regions around the world.</p><p class=\"ql-align-center\"><br></p><p><strong>Purpose of World Economic Outlook Report</strong></p><p><strong>Economic Forecasting</strong></p><p>The report predicts future economic growth of countries, regions and the world economy using economic data and financial indicators.</p><p class=\"ql-align-center\"><br></p><p><strong>Policy Guidance</strong></p><p>The report helps governments make economic policies, financial decisions and reform strategies for economic stability.</p><p class=\"ql-align-center\"><br></p><p><strong>Global Market Analysis</strong></p><p>The IMF studies inflation, trade, investment trends and global financial conditions through the report.</p><p class=\"ql-align-center\"><br></p><p><strong>What was updated in the IMF Report?</strong></p><p>IMF revised global GDP growth projections, inflation estimates and trade outlook based on changing economic conditions. The report reflects recent developments such as inflation trends, geopolitical tensions, energy prices and international trade conditions affecting the global economy.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Economic Growth Projection?</strong></p><p>An economic growth projection is an estimate of how much a country’s economy may grow during a certain period. It is usually measured using GDP growth rate and helps governments and investors understand future economic performance.</p><p class=\"ql-align-center\"><br></p><p><strong>What is GDP?</strong></p><p><strong>GDP (Gross Domestic Product)</strong> means the total value of goods and services produced within a country. It indicates the economic performance and productive capacity of a nation.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Inflation?</strong></p><p>Inflation means increase in prices of goods and services over time. High inflation reduces purchasing power because people can buy fewer goods and services with the same amount of money.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Why are IMF Reports Important?</strong></p><p><strong>For Governments</strong></p><p>IMF reports help governments in policy planning, budgeting and economic reforms by providing global economic analysis and forecasts.</p><p class=\"ql-align-center\"><br></p><p><strong>For Investors</strong></p><p>Investors use IMF reports to understand market conditions, financial risks and future economic trends before making investment decisions.</p><p class=\"ql-align-center\"><br></p><p><strong>For Global Institutions</strong></p><p>International organizations and financial institutions use IMF analysis for global financial coordination and economic planning.</p><p class=\"ql-align-center\"><br></p><p><strong>IMF Financial Assistance</strong></p><p>IMF gives loans to countries facing economic crisis, debt problems and currency instability. These loans help countries stabilize their economies and manage financial difficulties.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Currency Instability?</strong></p><p>Currency instability is a situation where the value of a currency changes sharply, causing economic uncertainty, inflation and financial difficulties in trade and investment.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important topics include global economy, international organizations, economic governance and financial institutions.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important areas include IMF full form, IMF headquarters, GDP basics, inflation and global financial organizations.</p><p><br></p><p><br></p><p><br></p>', '', 'REPORTS & INDEXES', '', '', NULL, 'active', 1, '2026-05-03 04:01:00', '2026-05-12 09:41:14', '2026-05-12 09:41:14');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(62, 'India launches National Manufacturing Mission implementation roadmap ', '', '<p>• National Manufacturing Mission (NMM) launched by the Government of India in 2026 to boost manufacturing, electronics and green industries in India. </p><p>• Focuses on semiconductors, MSMEs, AI, EVs and industrial infrastructure under Make in India and Atmanirbhar Bharat initiatives.</p><p>• Aim: Increase exports, create jobs, reduce imports and make India a global manufacturing hub.</p>', '', '<p>National Manufacturing Mission (NMM) Roadmap</p><p><strong>What is National Manufacturing Mission?</strong></p><p>The National Manufacturing Mission (NMM) is a Government of India initiative launched to strengthen India’s manufacturing sector, increase industrial production, promote advanced technology and make India a global manufacturing hub. The mission focuses on improving domestic manufacturing capabilities and making India internationally competitive in industrial production. It mainly gives importance to electronics manufacturing, semiconductor production, green manufacturing, MSME growth, industrial infrastructure and export promotion. The mission also supports the broader national visions of Make in India and Atmanirbhar Bharat by encouraging self-reliance and reducing dependence on imports in important industrial sectors.</p><p class=\"ql-align-center\"><br></p><p><strong>Who launched it?</strong></p><p>The implementation roadmap of the National Manufacturing Mission was launched by the Government of India in May 2026. The mission is being implemented with the support of major ministries and departments including the Ministry of Commerce &amp; Industry, DPIIT (Department for Promotion of Industry and Internal Trade) and the Ministry of Electronics &amp; Information Technology (MeitY). These ministries are responsible for industrial policy planning, investment promotion, infrastructure development and technology advancement under the mission.</p><p class=\"ql-align-center\"><br></p><p><strong>Why was National Manufacturing Mission launched?</strong></p><p>The National Manufacturing Mission was launched to increase India’s manufacturing strength and reduce dependence on imported industrial and electronic products. The government aims to make India a global manufacturing hub by expanding industrial production and improving competitiveness in the international market. The mission also seeks to increase exports, attract foreign direct investment (FDI), create employment opportunities and strengthen supply chains. Another important reason behind the mission is to promote self-reliance in technology and electronics manufacturing and enable India to compete with countries such as China and Vietnam in global manufacturing.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Objectives of National Manufacturing Mission</strong></p><p><strong>1. Increase Manufacturing Contribution in GDP</strong></p><p>One of the major objectives of the mission is to increase the contribution of manufacturing in India’s GDP through industrial expansion, investment and production growth. The government aims to strengthen the industrial sector and accelerate economic growth through manufacturing-led development.</p><p class=\"ql-align-center\"><br></p><p><strong>2. Employment Generation</strong></p><p>The National Manufacturing Mission is expected to create large-scale employment opportunities in sectors such as electronics, semiconductor manufacturing, green energy, MSMEs and advanced technology industries. This can generate jobs for skilled workers, engineers, technicians and youth across the country.</p><p class=\"ql-align-center\"><br></p><p><strong>3. Boost Exports</strong></p><p>The mission supports export-oriented manufacturing industries to improve India’s position in global trade. By increasing domestic production and improving industrial competitiveness, India aims to become a major exporter of electronics, industrial goods and advanced technology products.</p><p class=\"ql-align-center\"><br></p><p><strong>4. Promote Advanced Technology</strong></p><p>The roadmap focuses on promoting advanced technologies such as Artificial Intelligence (AI), robotics, automation and smart manufacturing systems. The use of these technologies can improve industrial efficiency, productivity and innovation in manufacturing sectors.</p><p class=\"ql-align-center\"><br></p><p><strong>5. Strengthen Industrial Infrastructure</strong></p><p>The mission also emphasizes the development of industrial infrastructure including industrial corridors, smart manufacturing hubs, logistics infrastructure and semiconductor parks. Improved infrastructure can strengthen production capacity, transportation networks and supply chain systems.</p><p class=\"ql-align-center\"><br></p><p><strong>How does it boost Electronics Manufacturing?</strong></p><p>The National Manufacturing Mission gives special importance to electronics manufacturing and semiconductor sectors because they are critical for technological and industrial growth. The roadmap encourages the development of semiconductor fabrication units (FABs), expansion of chip assembly and packaging facilities and promotion of domestic chip production. This can help India build a strong semiconductor ecosystem and reduce dependence on imported chips.</p><p>The mission also supports the Production Linked Incentive (PLI) Scheme under which the government provides incentives to electronics companies for increasing manufacturing activities in India. The roadmap promotes the manufacturing of smartphones, telecom equipment, electronic components and consumer electronics within the country.</p><p>India currently imports a large quantity of electronic components from foreign countries. The mission aims to reduce this import dependence through increased domestic manufacturing and self-reliance in electronics production.</p><p class=\"ql-align-center\"><br></p><p><strong>How does it promote Green Manufacturing?</strong></p><p>Green manufacturing refers to environment-friendly industrial production with lower pollution and carbon emissions. The National Manufacturing Mission promotes green manufacturing by encouraging industries to adopt sustainable and energy-efficient production methods.</p><p>The roadmap encourages industries to use renewable energy sources such as solar energy, wind energy and green power systems. This can reduce environmental damage and dependence on fossil fuels.</p><p>The mission also supports the Electric Vehicle (EV) ecosystem including EV manufacturing, battery production and EV charging infrastructure. These initiatives can strengthen clean transportation and sustainable industrial growth in India.</p><p>Another important aspect is the integration of the Green Hydrogen Mission. Green hydrogen is considered a clean industrial fuel and can help reduce carbon emissions in industries. The mission further promotes sustainable industrial practices such as energy-efficient factories, waste reduction and low-carbon production systems.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Green Manufacturing?</strong></p><p>Green manufacturing is the process of producing goods using environmentally friendly methods that reduce pollution, energy consumption and carbon emissions. It focuses on sustainable industrial production through efficient use of resources, renewable energy and cleaner technologies.</p><p class=\"ql-align-center\"><br></p><p><strong>What are Semiconductors?</strong></p><p>Semiconductors are materials used in electronic devices and computer chips. They are essential components in products such as mobile phones, computers, cars, telecom systems, defence equipment and AI technologies. Since semiconductors are extremely important for modern technology industries, building a strong domestic semiconductor ecosystem is a major priority under the National Manufacturing Mission.</p><p class=\"ql-align-center\"><br></p><p><strong>Expected Benefits of National Manufacturing Mission</strong></p><p>The National Manufacturing Mission is expected to provide several economic and industrial benefits to India. Industrial expansion under the mission can increase GDP and overall economic activity. Large-scale manufacturing projects can create employment opportunities for youth and skilled workers in different sectors.</p><p>The mission can also improve export growth by making India a major exporter of electronics and industrial products. Another important benefit is technological advancement through the promotion of innovation, automation and high-tech manufacturing industries.</p><p>The roadmap also supports self-reliance by reducing dependence on imported electronics, semiconductors and industrial technology products. This can strengthen India’s economic security and industrial independence.</p><p class=\"ql-align-center\"><br></p><p><strong>Important Terms Related to the Mission</strong></p><p><strong>Make in India</strong></p><p>Make in India is a Government of India initiative launched in 2014 to promote manufacturing, industrial growth and investment within the country. It encourages companies to manufacture products in India and strengthen domestic industries.</p><p class=\"ql-align-center\"><br></p><p><strong>Atmanirbhar Bharat</strong></p><p>Atmanirbhar Bharat is a national mission aimed at making India self-reliant in important sectors such as manufacturing, defence and technology. It focuses on reducing import dependence and improving domestic production capabilities.</p><p class=\"ql-align-center\"><br></p><p><strong>PLI Scheme (Production Linked Incentive)</strong></p><p>The Production Linked Incentive (PLI) Scheme is a government incentive program that rewards companies for increasing production and manufacturing activities in India. The scheme plays an important role in promoting electronics and semiconductor manufacturing under the National Manufacturing Mission.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>The National Manufacturing Mission is important for UPSC examination from topics such as Indian Economy, Industrial Policy, Manufacturing Sector, Green Economy, Government Schemes and Semiconductor Ecosystem. Questions may be asked about industrial growth, self-reliance, semiconductor production and green manufacturing initiatives.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>For SSC, Railway, Banking and State Exams, important areas include the full form of National Manufacturing Mission, electronics manufacturing, semiconductor ecosystem, green manufacturing, PLI Scheme, Make in India, Atmanirbhar Bharat and industrial growth and exports.</p><p><br></p>', '', 'NATIONAL AFFAIRS', '', '', NULL, 'active', 1, '2026-05-04 04:37:00', '2026-05-13 10:11:01', '2026-05-13 10:11:01');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(63, 'Ministry of Education expands PM SHRI Schools initiative ', '', '<p>• Ministry of Education expands PM SHRI Schools initiative </p><p>• Focus on smart classrooms, digital education and modern school infrastructure.</p><p>• Promotes NEP 2020 implementation and technology-based learning.</p><p>• Improves quality education, teacher training and skill development facilities.</p>', '', '<p><strong>PM SHRI Schools Initiative</strong></p><p><strong>What is PM SHRI?</strong></p><p>PM SHRI stands for PM Schools for Rising India. It is a centrally sponsored scheme launched by the Government of India to develop model schools across the country based on the principles of the National Education Policy (NEP) 2020. The scheme focuses on providing modern education, smart classrooms, digital learning, skill-based education and green infrastructure in schools.</p><p class=\"ql-align-center\"><br></p><p><strong>Launched By</strong></p><p>The PM SHRI Schools initiative was launched by the Government of India under the Ministry of Education.</p><p class=\"ql-align-center\"><br></p><p><strong>Launch Year</strong></p><p>The PM SHRI scheme was launched in 2022.</p><p class=\"ql-align-center\"><br></p><p><strong>Objective of PM SHRI Scheme</strong></p><p>The main objective of PM SHRI Schools is to transform selected schools into modern model schools that provide high-quality education and become examples for other schools across India. The scheme also focuses on improving learning outcomes and creating future-ready students.</p><p class=\"ql-align-center\"><br></p><p><strong>Smart Classrooms and Digital Learning</strong></p><p>PM SHRI schools are equipped with smart classrooms, digital boards, modern laboratories and technology-enabled teaching systems. The initiative promotes digital learning and modern educational methods to improve classroom experience and student participation.</p><p class=\"ql-align-center\"><br></p><p><strong>NEP 2020 Implementation</strong></p><p>PM SHRI Schools are developed according to the recommendations of the National Education Policy (NEP) 2020. The schools focus on experiential learning, competency-based education, practical understanding and holistic development of students.</p><p class=\"ql-align-center\"><br></p><p><strong>Green School Infrastructure</strong></p><p>The initiative promotes environment-friendly schools through solar energy usage, water conservation systems, waste management practices and green campus development.</p><p class=\"ql-align-center\"><br></p><p><strong>Skill-Based Education</strong></p><p>Students in PM SHRI schools receive vocational education, coding knowledge, digital literacy and practical learning opportunities to improve employability and modern skills.</p><p class=\"ql-align-center\"><br></p><p><strong>Teacher Training</strong></p><p>Teachers are provided modern teaching training, digital tools and innovative teaching methods to improve classroom education and learning quality.</p><p class=\"ql-align-center\"><br></p><p><strong>What is NEP 2020?</strong></p><p>NEP stands for National Education Policy 2020. It is India’s new education policy approved in 2020 to reform the education system from school level to higher education. The policy focuses on quality education, skill development and technology-based learning.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Objectives of NEP 2020</strong></p><p>The National Education Policy 2020 aims to improve the quality of education, promote skill-based learning, increase digital education, encourage multilingual learning and reduce rote memorization.</p><p class=\"ql-align-center\"><br></p><p><strong>Important Features of NEP 2020</strong></p><p>The policy introduced the new 5+3+3+4 education structure replacing the old 10+2 system. It also promotes vocational education, digital learning, coding, multidisciplinary education and conceptual understanding.</p><p class=\"ql-align-center\"><br></p><p><strong>Funding Pattern of PM SHRI</strong></p><p>PM SHRI is a Centrally Sponsored Scheme where funding is shared between the Central Government and State Governments.</p><p class=\"ql-align-center\"><br></p><p><strong>Importance of PM SHRI Schools</strong></p><p>PM SHRI Schools improve the quality of government schools, support digital education, encourage skill-based learning and help implement the National Education Policy 2020 effectively across India.</p><h1><br></h1><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important for education reforms, government schemes, NEP 2020 and social sector development.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important facts include PM SHRI full form, launch year 2022, Ministry of Education, smart classroom initiative and NEP 2020 implementation.</p><p><br></p>', '<p><strong>पीएम श्री स्कूल पहल</strong></p><p><strong>पीएम श्री क्या हैं?</strong></p><p>पीएम श्री का मतलब पीएम स्कूल्स फॉर राइजिंग इंडिया है। यह राष्ट्रीय शिक्षा नीति (एनईपी) 2020 के सिद्धांतों के आधार पर देश भर में मॉडल स्कूल विकसित करने के लिए भारत सरकार द्वारा शुरू की गई एक केंद्र प्रायोजित योजना है। यह योजना स्कूलों में आधुनिक शिक्षा, स्मार्ट क्लासरूम, डिजिटल लर्निंग, कौशल-आधारित शिक्षा और हरित बुनियादी ढांचा प्रदान करने पर केंद्रित है।</p><p class=\"ql-align-center\"><br></p><p><strong>द्वारा लॉन्च किया गया</strong></p><p>पीएम एसएचआरआई स्कूल पहल भारत सरकार द्वारा शिक्षा मंत्रालय के तहत शुरू की गई थी।</p><p class=\"ql-align-center\"><br></p><p><strong>लॉन्च वर्ष</strong></p><p>PM SHRI योजना 2022 में शुरू की गई थी।</p><p class=\"ql-align-center\"><br></p><p><strong>पीएम श्री योजना का उद्देश्य</strong></p><p>पीएम एसएचआरआई स्कूलों का मुख्य उद्देश्य चयनित स्कूलों को आधुनिक मॉडल स्कूलों में बदलना है जो उच्च गुणवत्ता वाली शिक्षा प्रदान करते हैं और भारत भर के अन्य स्कूलों के लिए उदाहरण बन जाते हैं। यह योजना सीखने के परिणामों में सुधार लाने और भविष्य के लिए तैयार छात्र तैयार करने पर भी केंद्रित है।</p><p class=\"ql-align-center\"><br></p><p><strong>स्मार्ट क्लासरूम और डिजिटल लर्निंग</strong></p><p>पीएम श्री स्कूल स्मार्ट कक्षाओं, डिजिटल बोर्ड, आधुनिक प्रयोगशालाओं और प्रौद्योगिकी-सक्षम शिक्षण प्रणालियों से सुसज्जित हैं। यह पहल कक्षा के अनुभव और छात्र भागीदारी को बेहतर बनाने के लिए डिजिटल शिक्षण और आधुनिक शैक्षिक तरीकों को बढ़ावा देती है।</p><p class=\"ql-align-center\"><br></p><p><strong>एनईपी 2020 कार्यान्वयन</strong></p><p>पीएम श्री स्कूल राष्ट्रीय शिक्षा नीति (एनईपी) 2020 की सिफारिशों के अनुसार विकसित किए गए हैं। स्कूल अनुभवात्मक शिक्षा, योग्यता-आधारित शिक्षा, व्यावहारिक समझ और छात्रों के समग्र विकास पर ध्यान केंद्रित करते हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>ग्रीन स्कूल इन्फ्रास्ट्रक्चर</strong></p><p>यह पहल सौर ऊर्जा के उपयोग, जल संरक्षण प्रणालियों, अपशिष्ट प्रबंधन प्रथाओं और हरित परिसर विकास के माध्यम से पर्यावरण-अनुकूल स्कूलों को बढ़ावा देती है।</p><p class=\"ql-align-center\"><br></p><p><strong>कौशल आधारित शिक्षा</strong></p><p>पीएम एसएचआरआई स्कूलों में छात्रों को रोजगारपरकता और आधुनिक कौशल में सुधार के लिए व्यावसायिक शिक्षा, कोडिंग ज्ञान, डिजिटल साक्षरता और व्यावहारिक सीखने के अवसर प्राप्त होते हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>शिक्षक प्रशिक्षण</strong></p><p>कक्षा की शिक्षा और सीखने की गुणवत्ता में सुधार के लिए शिक्षकों को आधुनिक शिक्षण प्रशिक्षण, डिजिटल उपकरण और नवीन शिक्षण विधियाँ प्रदान की जाती हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>एनईपी 2020 क्या है?</strong></p><p>एनईपी का मतलब राष्ट्रीय शिक्षा नीति 2020 है। यह स्कूल स्तर से उच्च शिक्षा तक शिक्षा प्रणाली में सुधार के लिए 2020 में अनुमोदित भारत की नई शिक्षा नीति है। यह नीति गुणवत्तापूर्ण शिक्षा, कौशल विकास और प्रौद्योगिकी-आधारित शिक्षा पर केंद्रित है।</p><p class=\"ql-align-center\"><br></p><p><strong>एनईपी 2020 के मुख्य उद्देश्य</strong></p><p>राष्ट्रीय शिक्षा नीति 2020 का उद्देश्य शिक्षा की गुणवत्ता में सुधार करना, कौशल-आधारित शिक्षा को बढ़ावा देना, डिजिटल शिक्षा को बढ़ाना, बहुभाषी शिक्षा को प्रोत्साहित करना और रटकर याद करने की प्रक्रिया को कम करना है।</p><p class=\"ql-align-center\"><br></p><p><strong>एनईपी 2020 की महत्वपूर्ण विशेषताएं</strong></p><p>नीति ने पुरानी 10+2 प्रणाली की जगह नई 5+3+3+4 शिक्षा संरचना पेश की। यह व्यावसायिक शिक्षा, डिजिटल लर्निंग, कोडिंग, बहु-विषयक शिक्षा और वैचारिक समझ को भी बढ़ावा देता है।</p><p class=\"ql-align-center\"><br></p><p><strong>पीएम श्री का फंडिंग पैटर्न</strong></p><p>पीएम श्री एक केंद्र प्रायोजित योजना है जहां केंद्र सरकार और राज्य सरकारों के बीच धन साझा किया जाता है।</p><p class=\"ql-align-center\"><br></p><p><strong>पीएम श्री स्कूलों का महत्व</strong></p><p>पीएम श्री स्कूल सरकारी स्कूलों की गुणवत्ता में सुधार करते हैं, डिजिटल शिक्षा का समर्थन करते हैं, कौशल-आधारित शिक्षा को प्रोत्साहित करते हैं और पूरे भारत में राष्ट्रीय शिक्षा नीति 2020 को प्रभावी ढंग से लागू करने में मदद करते हैं।</p><p><br></p><h1><br></h1><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>परीक्षा के लिए महत्व</strong></p><p><strong>यूपीएससी</strong></p><p>शिक्षा सुधार, सरकारी योजनाओं, एनईपी 2020 और सामाजिक क्षेत्र के विकास के लिए महत्वपूर्ण।</p><p class=\"ql-align-center\"><br></p><p><strong>एसएससी/रेलवे/बैंकिंग</strong></p><p>महत्वपूर्ण तथ्यों में पीएम एसएचआरआई का पूर्ण रूप, लॉन्च वर्ष 2022, शिक्षा मंत्रालय, स्मार्ट क्लासरूम पहल और एनईपी 2020 कार्यान्वयन शामिल हैं।</p>', 'NATIONAL AFFAIRS', '', '', NULL, 'active', 1, '2026-05-04 04:41:00', '2026-05-13 10:19:19', '2026-05-13 10:19:19');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(64, 'Government launches National Cooperative Database Portal', '', '<h2> Government launches National Cooperative Database Portal</h2><p><br></p><p>• Creates digital database of cooperative societies across India.</p><p>• Improves transparency, governance and data management in cooperative sector.</p>', '', '<p><strong>PM SHRI Schools Initiative</strong></p><p><strong>What is PM SHRI?</strong></p><p>PM SHRI stands for PM Schools for Rising India. It is a centrally sponsored scheme launched by the Government of India to develop model schools across the country based on the principles of the National Education Policy (NEP) 2020. The scheme focuses on providing modern education, smart classrooms, digital learning, skill-based education and green infrastructure in schools.</p><p class=\"ql-align-center\"><br></p><p><strong>Launched By</strong></p><p>The PM SHRI Schools initiative was launched by the Government of India under the Ministry of Education.</p><p class=\"ql-align-center\"><br></p><p><strong>Launch Year</strong></p><p>The PM SHRI scheme was launched in 2022.</p><p class=\"ql-align-center\"><br></p><p><strong>Objective of PM SHRI Scheme</strong></p><p>The main objective of PM SHRI Schools is to transform selected schools into modern model schools that provide high-quality education and become examples for other schools across India. The scheme also focuses on improving learning outcomes and creating future-ready students.</p><p class=\"ql-align-center\"><br></p><p><strong>Smart Classrooms and Digital Learning</strong></p><p>PM SHRI schools are equipped with smart classrooms, digital boards, modern laboratories and technology-enabled teaching systems. The initiative promotes digital learning and modern educational methods to improve classroom experience and student participation.</p><p class=\"ql-align-center\"><br></p><p><strong>NEP 2020 Implementation</strong></p><p>PM SHRI Schools are developed according to the recommendations of the National Education Policy (NEP) 2020. The schools focus on experiential learning, competency-based education, practical understanding and holistic development of students.</p><p class=\"ql-align-center\"><br></p><p><strong>Green School Infrastructure</strong></p><p>The initiative promotes environment-friendly schools through solar energy usage, water conservation systems, waste management practices and green campus development.</p><p class=\"ql-align-center\"><br></p><p><strong>Skill-Based Education</strong></p><p>Students in PM SHRI schools receive vocational education, coding knowledge, digital literacy and practical learning opportunities to improve employability and modern skills.</p><p class=\"ql-align-center\"><br></p><p><strong>Teacher Training</strong></p><p>Teachers are provided modern teaching training, digital tools and innovative teaching methods to improve classroom education and learning quality.</p><p class=\"ql-align-center\"><br></p><p><strong>What is NEP 2020?</strong></p><p>NEP stands for National Education Policy 2020. It is India’s new education policy approved in 2020 to reform the education system from school level to higher education. The policy focuses on quality education, skill development and technology-based learning.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Objectives of NEP 2020</strong></p><p>The National Education Policy 2020 aims to improve the quality of education, promote skill-based learning, increase digital education, encourage multilingual learning and reduce rote memorization.</p><p class=\"ql-align-center\"><br></p><p><strong>Important Features of NEP 2020</strong></p><p>The policy introduced the new 5+3+3+4 education structure replacing the old 10+2 system. It also promotes vocational education, digital learning, coding, multidisciplinary education and conceptual understanding.</p><p class=\"ql-align-center\"><br></p><p><strong>Funding Pattern of PM SHRI</strong></p><p>PM SHRI is a Centrally Sponsored Scheme where funding is shared between the Central Government and State Governments.</p><p class=\"ql-align-center\"><br></p><p><strong>Importance of PM SHRI Schools</strong></p><p>PM SHRI Schools improve the quality of government schools, support digital education, encourage skill-based learning and help implement the National Education Policy 2020 effectively across India.</p><h1><br></h1><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important for education reforms, government schemes, NEP 2020 and social sector development.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important facts include PM SHRI full form, launch year 2022, Ministry of Education, smart classroom initiative and NEP 2020 implementation.</p><p><strong>National Cooperative Database Portal</strong></p><p><br></p><p><br></p><p><br></p>', '', 'NATIONAL AFFAIRS', '', '', NULL, 'active', 1, '2026-05-04 04:50:00', '2026-05-13 10:26:34', '2026-05-13 10:26:34');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(65, '•United Nations reviews Sustainable Development Goals (SDGs) progress', '', '<h2>•United Nations reviews Sustainable Development Goals (SDGs) progress</h2><p><br></p><p>• Focus on climate finance, poverty reduction and sustainable development targets.</p><p>• Highlights global efforts toward health, education and environmental protection.</p>', '', '<p>United Nations Reviews Sustainable Development Goals (SDGs) Progress</p><p><strong>What is United Nations (UN)?</strong></p><p>The United Nations (UN) is an international organization formed to maintain international peace and security, promote friendly relations among countries and support global development and cooperation. The organization works in various important areas such as peace and security, human rights, climate action, poverty reduction, health and education and sustainable development. The United Nations plays a major role in promoting cooperation among countries and solving global challenges through dialogue and collective action.</p><p class=\"ql-align-center\"><br></p><p><strong>Established</strong></p><p>The United Nations was established on 24 October 1945 after the end of World War II. The organization was created to prevent future global conflicts, maintain peace and encourage international cooperation among countries. The establishment of the UN marked an important step toward creating a stable and peaceful international system after the destruction caused by the war.</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters</strong></p><p>The headquarters of the United Nations is located in New York City, USA. The headquarters serves as the central administrative office where major meetings, discussions and international diplomatic activities take place.</p><p class=\"ql-align-center\"><br></p><p><strong>Member Countries</strong></p><p>The United Nations currently has 193 member countries. Almost all sovereign nations of the world are members of the organization. India is also a founding member of the United Nations and has actively participated in various UN activities related to peacekeeping, sustainable development and international cooperation.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Organs of United Nations</strong></p><p>The United Nations has six principal organs that perform different functions related to global governance and international cooperation. These organs include the United Nations General Assembly (UNGA), United Nations Security Council (UNSC), Economic and Social Council (ECOSOC), International Court of Justice (ICJ), UN Secretariat and Trusteeship Council. Each organ plays an important role in maintaining peace, promoting development and solving international disputes.</p><p class=\"ql-align-center\"><br></p><p><strong>Current Secretary-General of United Nations</strong></p><p>The current Secretary-General of the United Nations in 2026 is António Guterres. The Secretary-General is the chief administrative officer and spokesperson of the organization. The head of the United Nations is called the Secretary-General and not Chairman.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Objectives of United Nations</strong></p><p><strong>International Peace and Security</strong></p><p>One of the main objectives of the United Nations is to maintain international peace and security. The organization works to prevent wars, resolve international conflicts and support peacekeeping operations in conflict-affected regions across the world.</p><p class=\"ql-align-center\"><br></p><p><strong>Human Rights Protection</strong></p><p>The United Nations promotes equality, justice and protection of human rights globally. It works to ensure that people around the world receive basic freedoms, dignity and equal treatment regardless of nationality, race or gender.</p><p class=\"ql-align-center\"><br></p><p><strong>Economic and Social Development</strong></p><p>The organization supports poverty reduction, healthcare improvement, education and economic development in different countries. Through various agencies and programs, the UN works to improve living standards and support sustainable economic growth.</p><p class=\"ql-align-center\"><br></p><p><strong>Climate and Environment Protection</strong></p><p>The United Nations also promotes sustainable development and climate action worldwide. It encourages countries to reduce environmental damage, fight climate change and protect natural resources for future generations.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Sustainable Development?</strong></p><p>Sustainable development means development that meets the needs of the present generation without harming the ability of future generations to meet their own needs. It focuses on maintaining balance among economic growth, social development and environmental protection. Sustainable development aims to ensure long-term progress without causing damage to natural resources and ecosystems.</p><p class=\"ql-align-center\"><br></p><p><strong>What are Sustainable Development Goals (SDGs)?</strong></p><p>The Sustainable Development Goals (SDGs) are 17 global goals adopted by the United Nations in 2015 under the 2030 Agenda for Sustainable Development. These goals were introduced to improve the quality of life and create a sustainable future for all countries. The SDGs provide a global framework for reducing poverty, improving healthcare and education, protecting the environment and promoting equality and sustainable economic growth.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Goals of SDGs</strong></p><p>The Sustainable Development Goals include several important objectives such as No Poverty, Zero Hunger, Good Health and Well-being, Quality Education, Gender Equality, Clean Water and Sanitation, Affordable and Clean Energy, Climate Action, Sustainable Cities and Communities, Life Below Water and Life on Land. These goals aim to address major global challenges and improve human well-being worldwide.</p><p class=\"ql-align-center\"><br></p><p><strong>Why are SDGs Important?</strong></p><p>The SDGs are important because they help countries work together to reduce poverty, improve healthcare and education, protect the environment, reduce inequality and promote sustainable economic growth. The goals encourage global cooperation and provide a common framework for achieving balanced and inclusive development across the world.</p><p class=\"ql-align-center\"><br></p><p><strong>What was reviewed by the United Nations?</strong></p><p>The United Nations recently reviewed global progress on the Sustainable Development Goals and highlighted several major challenges related to climate finance, poverty reduction, environmental protection, economic inequality and sustainable growth. The review emphasized that many countries are still facing difficulties in achieving SDG targets and that stronger international cooperation is required to accelerate progress.</p><p>The review also stressed the need for greater financial support and technical assistance for developing countries so that they can effectively implement sustainable development programs and climate-related initiatives.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Climate Finance?</strong></p><p>Climate finance refers to financial support provided for activities related to climate change mitigation and adaptation. It helps countries invest in renewable energy, green technology, climate-resilient infrastructure and environmental protection projects. Climate finance is especially important for developing countries that require financial assistance to transition toward sustainable and low-carbon economies.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Poverty Reduction?</strong></p><p>Poverty reduction refers to efforts made by governments and organizations to improve income, employment opportunities, healthcare, education and living standards of poor people. Poverty reduction programs aim to provide better economic opportunities and social welfare support to disadvantaged communities and reduce inequality in society.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>The topic is important for UPSC examination from areas such as international organizations, sustainable development, climate change, global governance and Sustainable Development Goals. Questions may be asked about the role of the United Nations, SDGs, climate finance and international cooperation in sustainable development.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>For SSC, Railway, Banking and other competitive examinations, important facts include the establishment year of the United Nations, UN headquarters, current Secretary-General, full form of SDGs, total Sustainable Development Goals and concepts such as climate finance and poverty reduction.</p><p><br></p><p><br></p>', '', 'INTERNATIONAL AFFAIRS', '', '', NULL, 'active', 1, '2026-05-04 05:00:00', '2026-05-13 10:36:56', '2026-05-13 10:36:56');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(66, 'RBI strengthens framework for digital fraud prevention', '', '<h2>RBI strengthens framework for digital fraud prevention</h2><p><br></p><p>• Focus on secure online banking and digital payment ecosystem.</p><p>• Enhances cyber security, customer protection and fraud monitoring systems.</p>', '', '<p>RBI Strengthens Framework for Digital Fraud Prevention</p><p><strong>What is RBI?</strong></p><p>The Reserve Bank of India (RBI) is the central bank of India. It is the main financial authority responsible for regulating the country’s banking system and maintaining monetary and financial stability. RBI controls the issue and supply of currency, regulates banks and financial institutions and ensures the smooth functioning of India’s payment and financial systems.</p><p>The RBI also plays a major role in controlling inflation, managing foreign exchange reserves and promoting economic growth through monetary policy measures. It acts as the banker to the Government of India and also serves as the banker’s bank for commercial banks operating in the country.</p><p class=\"ql-align-center\"><br></p><p><strong>Establishment of RBI</strong></p><p>The Reserve Bank of India was established on 1 April 1935 under the Reserve Bank of India Act, 1934. Initially, the RBI was privately owned but it was nationalized in 1949 after India’s independence so that the Government of India could have full control over the country’s monetary system and banking regulation.</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters of RBI</strong></p><p>The headquarters of the Reserve Bank of India is located in Mumbai, Maharashtra.</p><p class=\"ql-align-center\"><br></p><p><strong>Current Governor of RBI</strong></p><p>The current Governor of the Reserve Bank of India in 2026 is Sanjay Malhotra. The Governor is the chief executive head of RBI and is responsible for implementing monetary policies, banking regulations and financial supervision in the country.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Functions of RBI</strong></p><p><strong>Monetary Policy Regulation</strong></p><p>The RBI controls inflation and economic stability through monetary policy tools such as repo rate, reverse repo rate and cash reserve ratio (CRR). These tools help regulate money supply and interest rates in the economy.</p><p class=\"ql-align-center\"><br></p><p><strong>Currency Issuance</strong></p><p>The Reserve Bank of India has the authority to issue currency notes in India except one rupee notes and coins, which are issued by the Government of India.</p><p class=\"ql-align-center\"><br></p><p><strong>Regulation of Banks</strong></p><p>RBI regulates and supervises commercial banks, cooperative banks and financial institutions to ensure financial stability and protect depositors’ interests.</p><p class=\"ql-align-center\"><br></p><p><strong>Foreign Exchange Management</strong></p><p>The RBI manages India’s foreign exchange reserves and regulates foreign exchange transactions under FEMA (Foreign Exchange Management Act).</p><p class=\"ql-align-center\"><br></p><p><strong>Payment and Settlement Systems</strong></p><p>The RBI ensures smooth functioning of digital payments and banking systems such as UPI, NEFT, RTGS and IMPS.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Digital Fraud?</strong></p><p>Digital fraud refers to illegal or fraudulent activities carried out using digital platforms, online banking systems, mobile applications or electronic payment methods to steal money, personal information or financial data.</p><p>Fraudsters use technology and cyber methods to cheat users and gain unauthorized access to bank accounts, payment systems or confidential information.</p><p class=\"ql-align-center\"><br></p><p><strong>Common Types of Digital Fraud</strong></p><p>Some common forms of digital fraud include phishing attacks, fake banking calls, OTP fraud, QR code scams, fake mobile applications, identity theft, online shopping fraud and unauthorized UPI transactions.</p><p>Cybercriminals often trick users into sharing passwords, OTPs, debit card details or banking credentials through fake websites, SMS messages or phone calls.</p><p class=\"ql-align-center\"><br></p><p><strong>Why did RBI strengthen the framework for digital fraud prevention?</strong></p><p>The RBI strengthened the framework for digital fraud prevention due to the rapid growth of online banking and digital payment systems in India. With the increasing use of UPI, mobile banking and digital wallets, cyber fraud and online financial crimes have also increased.</p><p>The RBI aims to improve customer protection, strengthen cybersecurity systems and ensure safe digital financial transactions. The framework also supports India’s growing digital economy and promotes trust in online banking and digital payment systems.</p><p class=\"ql-align-center\"><br></p><p><strong>How does RBI prevent Digital Fraud?</strong></p><p><strong>Strong Authentication Systems</strong></p><p>The RBI promotes secure authentication methods such as two-factor authentication (2FA), OTP verification and biometric verification for online banking and digital payments. These measures help reduce unauthorized access to bank accounts.</p><p class=\"ql-align-center\"><br></p><p><strong>Cybersecurity Guidelines for Banks</strong></p><p>The RBI issues cybersecurity guidelines and security standards for banks and financial institutions. Banks are required to regularly update their security systems, monitor suspicious activities and strengthen digital infrastructure.</p><p class=\"ql-align-center\"><br></p><p><strong>Real-Time Fraud Monitoring</strong></p><p>Banks and payment companies use real-time fraud detection systems to identify unusual transactions and suspicious payment activities. This helps prevent fraud before major financial loss occurs.</p><p class=\"ql-align-center\"><br></p><p><strong>Customer Awareness Programs</strong></p><p>The RBI and banks conduct awareness campaigns to educate customers about cyber fraud, phishing scams and safe digital banking practices. Public awareness is important for reducing online fraud risks.</p><p class=\"ql-align-center\"><br></p><p><strong>Secure Payment Ecosystem</strong></p><p>The RBI promotes secure payment systems such as UPI, tokenization and encrypted digital transactions to improve payment security and protect customer data.</p><p class=\"ql-align-center\"><br></p><p><strong>Reporting and Complaint Mechanisms</strong></p><p>The RBI has strengthened fraud reporting systems and grievance redressal mechanisms to help customers quickly report unauthorized transactions and cyber fraud cases.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is RBI focusing on secure online banking and digital payment ecosystem?</strong></p><p>India has experienced rapid growth in digital payments due to increased smartphone usage, internet access and government initiatives like Digital India. Millions of people now use UPI, internet banking and mobile wallets for daily transactions.</p><p>As digital financial services increase, the risk of cyberattacks and online fraud also rises. Therefore, RBI is focusing on creating a secure online banking and digital payment ecosystem to protect users, maintain trust in financial systems and support safe growth of the digital economy.</p><p>A secure digital payment ecosystem helps improve financial inclusion, encourages cashless transactions and strengthens confidence in online financial services.</p><p class=\"ql-align-center\"><br></p><p><strong>How can Digital Banking be secured?</strong></p><p>Digital banking can be made safer through strong passwords, secure mobile applications, regular software updates and awareness about cyber threats.</p><p>Users should never share OTPs, PINs or passwords with anyone. Customers should also avoid clicking suspicious links, downloading unknown applications or responding to fake banking messages and calls.</p><p>Banks should continuously improve cybersecurity infrastructure, use AI-based fraud monitoring systems and strengthen customer verification systems to reduce cyber risks.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Cyber Security?</strong></p><p>Cyber security refers to the protection of computer systems, networks, digital platforms and data from cyberattacks, hacking, malware and unauthorized access.</p><p>Cyber security aims to protect sensitive information, financial systems and online services from digital threats and cybercriminals.</p><p>It includes technologies, security practices and monitoring systems designed to prevent data theft, cyber fraud and system damage.</p><p class=\"ql-align-center\"><br></p><p><strong>Importance of Cyber Security</strong></p><p>Cyber security is extremely important because governments, banks, businesses and individuals depend heavily on digital systems and internet-based services.</p><p>Strong cyber security helps protect:</p><p>• banking systems</p><p> • personal data</p><p> • digital payments</p><p> • government databases</p><p> • online transactions</p><p> • business networks</p><p>Effective cyber security also helps maintain trust in digital services and supports the safe growth of the digital economy.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"><img src=\"data:image/png;base64,\">    </p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>This topic is important for UPSC examination from areas such as Indian Economy, Banking System, Financial Regulation, Cyber Security, Digital Economy and RBI policies. Questions may also be asked regarding digital payment systems, financial fraud prevention and cyber security measures.</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important facts for SSC, Railway, Banking and other competitive exams include:</p><p>• Full form of RBI</p><p> • Establishment year of RBI</p><p> • RBI headquarters</p><p> • Current RBI Governor</p><p> • Meaning of digital fraud</p><p> • Cyber security concepts</p><p> • Digital payment systems like UPI, RTGS and NEFT</p><p> • RBI’s role in fraud prevention and banking regulation</p><p><br></p><p><br></p>', '', 'ECONOMY & BANKING', '', '', NULL, 'active', 1, '2026-05-04 05:08:00', '2026-05-13 10:48:28', '2026-05-13 10:48:28');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(67, '•India’s GST collections remain above ₹2 lakh crore', '', '<h2>•India’s GST collections remain above ₹2 lakh crore</h2><p><br></p><p>• Indicates strong tax compliance and rising economic activity.</p><p>• Reflects growth in business transactions and government revenue.</p>', '', '<p>India’s GST Collections Remain Above ₹2 Lakh Crore</p><p><strong>What is GST?</strong></p><p>GST stands for Goods and Services Tax. It is an indirect tax imposed on the supply of goods and services in India. GST replaced multiple indirect taxes such as VAT, service tax, excise duty and several state taxes with a single unified tax system.</p><p>GST is considered one of the biggest tax reforms in India because it created a “One Nation, One Tax” system. The tax is collected at every stage of value addition but the final burden is borne by the end consumer.</p><p class=\"ql-align-center\"><br></p><p><strong>When was GST implemented?</strong></p><p>GST was implemented in India on 1 July 2017.</p><p>It was launched during a special midnight session of Parliament on 30 June–1 July 2017.</p><p class=\"ql-align-center\"><br></p><p><strong>Constitutional Provision Related to GST</strong></p><p>GST was introduced through the:</p><p>• 101st Constitutional Amendment Act, 2016</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p class=\"ql-align-center\"><br></p><p><strong>Ministry Related to GST</strong></p><p>GST comes under:</p><p>• Ministry of Finance</p><p>The Department of Revenue under the Ministry of Finance manages GST administration at the central level.</p><p class=\"ql-align-center\"><br></p><p><strong>What is GST Council?</strong></p><p>The GST Council is the main decision-making body for GST in India. It recommends GST rates, rules and tax reforms.</p><p><strong>Established Under</strong></p><p>• Article 279A</p><p><strong>Chairman of GST Council</strong></p><p>• Union Finance Minister of India</p><p><strong>Members</strong></p><p>• Finance Ministers of all States and Union Territories</p><p>The GST Council decides tax slabs, exemptions and policy changes related to GST.</p><p class=\"ql-align-center\"><br></p><p><strong>Types of GST</strong></p><p><strong>CGST (Central GST)</strong></p><p>CGST is collected by the Central Government on intra-state sales of goods and services.</p><p>Example: Goods sold within the same state.</p><p class=\"ql-align-center\"><br></p><p><strong>SGST (State GST)</strong></p><p>SGST is collected by the State Government on intra-state transactions.</p><p>Both CGST and SGST are charged together on sales within a state.</p><p class=\"ql-align-center\"><br></p><p><strong>IGST (Integrated GST)</strong></p><p>IGST is charged on inter-state trade and commerce.</p><p>It is collected by the Central Government and later distributed between Centre and States.</p><p class=\"ql-align-center\"><br></p><p><strong>UTGST (Union Territory GST)</strong></p><p>UTGST applies in Union Territories without legislatures.</p><p>Example: Chandigarh, Lakshadweep.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Features of GST</strong></p><p><strong>One Nation, One Tax</strong></p><p>GST unified multiple indirect taxes into a single taxation system across India.</p><p class=\"ql-align-center\"><br></p><p><strong>Destination-Based Tax</strong></p><p>GST is collected in the state where goods or services are consumed, not where they are produced.</p><p class=\"ql-align-center\"><br></p><p><strong>Input Tax Credit (ITC)</strong></p><p>Businesses can claim credit for tax already paid on inputs, reducing tax burden and avoiding double taxation.</p><p class=\"ql-align-center\"><br></p><p><strong>Digital Tax System</strong></p><p>GST registration, return filing and tax payments are done online through the GST portal.</p><p class=\"ql-align-center\"><br></p><p><strong>What does “GST collections remain above ₹2 lakh crore” mean?</strong></p><p>It means the government collected more than ₹2 lakh crore in GST revenue during a month. This indicates strong tax compliance, increased business activity and higher consumption in the economy.</p><p>Higher GST collections generally reflect:</p><p>• strong economic growth</p><p> • increased industrial production</p><p> • higher consumer spending</p><p> • better tax administration</p><p> • reduction in tax evasion</p><p class=\"ql-align-center\"><br></p><p><strong>Why are high GST collections important?</strong></p><p>High GST collections are important because they increase government revenue which can be used for:</p><p>• infrastructure development</p><p> • welfare schemes</p><p> • healthcare</p><p> • education</p><p> • defence spending</p><p> • economic growth programs</p><p>Strong GST revenue also shows improvement in formalization of the economy and digital tax compliance.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Tax Compliance?</strong></p><p>Tax compliance means individuals and businesses correctly paying taxes on time according to government rules and regulations.</p><p>Good tax compliance helps increase government revenue and reduces black money and tax evasion.</p><p class=\"ql-align-center\"><br></p><p><strong>What factors increased GST collections?</strong></p><p>Several factors contributed to higher GST collections:</p><p><strong>Economic Growth</strong></p><p>Improvement in industrial production and business activity increased taxable transactions.</p><p class=\"ql-align-center\"><br></p><p><strong>Digital Monitoring</strong></p><p>The government strengthened digital tracking and e-invoicing systems to reduce tax evasion.</p><p class=\"ql-align-center\"><br></p><p><strong>Better Compliance</strong></p><p>More businesses are filing GST returns regularly and paying taxes properly.</p><p class=\"ql-align-center\"><br></p><p><strong>Increased Consumption</strong></p><p>Higher spending by consumers increased GST revenue collection.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Advantages of GST</strong></p><p><strong>Simplified Tax System</strong></p><p>GST replaced multiple taxes with one unified system.</p><p class=\"ql-align-center\"><br></p><p><strong>Reduced Cascading Effect</strong></p><p>Input Tax Credit reduced tax-on-tax burden.</p><p class=\"ql-align-center\"><br></p><p><strong>Boost to Business</strong></p><p>Uniform taxation improved ease of doing business.</p><p class=\"ql-align-center\"><br></p><p><strong>Increased Transparency</strong></p><p>Digital filing and invoicing improved transparency in taxation.</p><p class=\"ql-align-center\"><br></p><p><strong>Challenges of GST</strong></p><p>Some challenges include:</p><p>• technical issues in filing returns</p><p> • compliance burden for small businesses</p><p> • complex tax structure for some sectors</p><p> • dependence on digital systems</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important for:</p><p>• Indian Economy</p><p> • Taxation System</p><p> • Fiscal Policy</p><p> • GST Reforms</p><p> • Economic Development</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important facts include:</p><p>• GST full form</p><p> • Implementation year</p><p> • 101st Constitutional Amendment</p><p> • GST Council</p><p> • Types of GST</p><p> • Ministry of Finance</p><p> • Meaning of GST collections</p><p> • Input Tax Credit (ITC)</p><p> • One Nation, One Tax system</p><p><br></p><p><br></p>', '', 'ECONOMY & BANKING', '', '', NULL, 'active', 1, '2026-05-04 09:44:00', '2026-05-13 15:20:38', '2026-05-13 15:20:38');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(68, ' NPCI expands UPI international payment connectivity', '', '<h2> NPCI expands UPI international payment connectivity</h2><p><br></p><p>• Enables cross-border digital payments using UPI.</p><p>• Improves global acceptance of India’s digital payment system.</p><p>• Supports secure and faster international transactions.</p>', '', '<p>NPCI Expands UPI International Payment Connectivity</p><p><strong>What is NPCI?</strong></p><p>NPCI stands for National Payments Corporation of India. It is an umbrella organization for operating retail payment and settlement systems in India. NPCI was established to create a secure, efficient and technology-driven payment infrastructure in the country.</p><p>NPCI plays a major role in promoting digital payments and cashless transactions in India. It develops and manages many important payment systems such as UPI, RuPay, IMPS, FASTag and BHIM.</p><p>The organization works to make digital payments simple, secure, fast and accessible for all citizens.</p><p class=\"ql-align-center\"><br></p><p><strong>Establishment of NPCI</strong></p><p>NPCI was established in 2008 under the guidance of:</p><p>• Reserve Bank of India (RBI)</p><p> • Indian Banks’ Association (IBA)</p><p>It was incorporated under the Companies Act, 1956 as a not-for-profit organization.</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters of NPCI</strong></p><p>The headquarters of NPCI is located in Mumbai, Maharashtra.</p><p class=\"ql-align-center\"><br></p><p><strong>Current Leadership of NPCI</strong></p><p><strong>Chairman of NPCI</strong></p><p>• Biswamohan Mahapatra (2026)</p><p><strong>Managing Director and CEO</strong></p><p>• Dilip Asbe (2026)</p><p>The CEO manages daily operations and expansion of digital payment systems in India.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Objectives of NPCI</strong></p><p>NPCI was created to:</p><p>• promote digital payments</p><p> • develop retail payment systems</p><p> • improve financial inclusion</p><p> • reduce dependence on cash</p><p> • strengthen secure payment infrastructure</p><p> • support innovation in banking technology</p><p class=\"ql-align-center\"><br></p><p><strong>Major Payment Systems Operated by NPCI</strong></p><p><strong>UPI (Unified Payments Interface)</strong></p><p>UPI is India’s real-time instant payment system that allows money transfer between bank accounts using mobile phones.</p><p>It supports:</p><p>• QR code payments</p><p> • mobile number payments</p><p> • bank account transfers</p><p> • merchant payments</p><p> • peer-to-peer transfers</p><p>UPI is one of the most successful digital payment systems in the world.</p><p class=\"ql-align-center\"><br></p><p><strong>IMPS (Immediate Payment Service)</strong></p><p>IMPS provides instant 24×7 bank fund transfer services through mobile banking, internet banking and ATMs.</p><p class=\"ql-align-center\"><br></p><p><strong>RuPay</strong></p><p>RuPay is India’s domestic card payment network developed by NPCI. It is similar to Visa and Mastercard.</p><p>RuPay cards are used for:</p><p>• ATM withdrawals</p><p> • shopping</p><p> • online payments</p><p> • banking transactions</p><p class=\"ql-align-center\"><br></p><p><strong>FASTag</strong></p><p>FASTag is an electronic toll collection system that allows automatic toll payment on highways using RFID technology.</p><p class=\"ql-align-center\"><br></p><p><strong>BHIM App</strong></p><p>BHIM stands for Bharat Interface for Money. It is a UPI-based digital payment application developed by NPCI.</p><p class=\"ql-align-center\"><br></p><p><strong>Popular UPI Payment Apps in India</strong></p><p>Many payment applications use NPCI’s UPI infrastructure.</p><p><strong>NPCI-Related UPI Apps</strong></p><p>• BHIM</p><p> • PhonePe</p><p> • Google Pay</p><p> • Paytm</p><p> • Amazon Pay</p><p> • Cred</p><p> • Mobikwik</p><p>These apps connect users’ bank accounts through UPI for instant digital payments.</p><p class=\"ql-align-center\"><br></p><p><strong>What is UPI?</strong></p><p>UPI stands for Unified Payments Interface.</p><p>It is a real-time digital payment system developed by NPCI that enables instant money transfer between bank accounts using mobile devices.</p><p>UPI allows users to:</p><p>• send money instantly</p><p> • receive money</p><p> • pay bills</p><p> • scan QR codes</p><p> • make online purchases</p><p> • transfer money 24×7</p><p>UPI transactions are completed using UPI ID, mobile number or QR code without requiring bank account details every time.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Features of UPI</strong></p><p><strong>Instant Transfer</strong></p><p>Money is transferred instantly between bank accounts.</p><p class=\"ql-align-center\"><br></p><p><strong>24×7 Availability</strong></p><p>UPI works throughout the year including holidays.</p><p class=\"ql-align-center\"><br></p><p><strong>Secure Transactions</strong></p><p>UPI uses PIN verification, encryption and banking authentication for security.</p><p class=\"ql-align-center\"><br></p><p><strong>Low-Cost Digital Payment</strong></p><p>UPI transactions are mostly free for users.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Who regulates digital payment systems in India?</strong></p><p>Digital payment systems are mainly regulated by:</p><p>• Reserve Bank of India (RBI)</p><p>The RBI issues guidelines related to:</p><p>• payment security</p><p> • transaction limits</p><p> • cyber security</p><p> • banking regulations</p><p> • digital fraud prevention</p><p>NPCI operates payment systems but functions under RBI supervision.</p><p class=\"ql-align-center\"><br></p><p><strong>Other Digital Payment Methods in India</strong></p><p>India has several digital payment methods besides UPI.</p><p><strong>NEFT (National Electronic Funds Transfer)</strong></p><p>A nationwide electronic bank transfer system for transferring money between banks.</p><p>Regulated by:</p><p>• RBI</p><p class=\"ql-align-center\"><br></p><p><strong>RTGS (Real Time Gross Settlement)</strong></p><p>Used for large-value instant bank transfers.</p><p>Regulated by:</p><p>• RBI</p><p class=\"ql-align-center\"><br></p><p><strong>IMPS</strong></p><p>Instant interbank transfer service.</p><p>Operated by:</p><p>• NPCI</p><p>Regulated by:</p><p>• RBI</p><p class=\"ql-align-center\"><br></p><p><strong>Debit Cards and Credit Cards</strong></p><p>Used for online and offline digital payments.</p><p>Networks include:</p><p>• RuPay</p><p> • Visa</p><p> • Mastercard</p><p>Regulated by:</p><p>• RBI</p><p class=\"ql-align-center\"><br></p><p><strong>Mobile Wallets</strong></p><p>Examples:</p><p>• Paytm Wallet</p><p> • Amazon Pay Wallet</p><p> • Mobikwik Wallet</p><p>Regulated by:</p><p>• RBI</p><p class=\"ql-align-center\"><br></p><p><strong>What is the news about?</strong></p><p>The news states that NPCI is expanding UPI international payment connectivity. This means India’s UPI payment system is being connected with payment systems of other countries to enable cross-border digital transactions.</p><p>Indian users can increasingly use UPI for making payments abroad while foreign users may also connect with India’s payment ecosystem.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is international UPI expansion important?</strong></p><p>International UPI connectivity is important because it:</p><p>• improves global acceptance of India’s digital payment system</p><p> • supports cashless international transactions</p><p> • enables secure and faster payments abroad</p><p> • helps Indian travelers and businesses</p><p> • strengthens India’s fintech leadership globally</p><p> • promotes digital financial inclusion</p><p>The expansion also improves remittance systems and reduces transaction costs for international money transfers.</p><p class=\"ql-align-center\"><br></p><p><strong>Countries linked with UPI</strong></p><p>India has partnered with several countries for UPI payment connectivity including:</p><p>• Singapore</p><p> • UAE</p><p> • France</p><p> • Sri Lanka</p><p> • Mauritius</p><p> • Nepal</p><p>More countries are expected to join in the future.</p><p class=\"ql-align-center\"><br></p><p><strong>How does international UPI help users?</strong></p><p>International UPI allows users to:</p><p>• make payments abroad using Indian apps</p><p> • pay merchants directly through QR codes</p><p> • avoid carrying large amounts of cash</p><p> • reduce foreign payment charges</p><p> • transfer money quickly and securely</p><p>It also benefits Indian tourists, students and businesses operating internationally.</p><p class=\"ql-align-center\"><br></p><p><strong>Security Features in UPI International Payments</strong></p><p>UPI international transactions are secured through:</p><p>• PIN authentication</p><p> • encrypted payment systems</p><p> • banking verification</p><p> • fraud monitoring systems</p><p> • RBI cyber security guidelines</p><p>These measures help protect users from digital fraud and cyberattacks.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Cyber Security in Digital Payments?</strong></p><p>Cyber security refers to protection of digital payment systems, banking networks and customer data from hacking, cyber fraud and unauthorized access.</p><p>Strong cyber security is important because digital payments involve sensitive financial information and online banking systems.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important for:</p><p>• Indian Economy</p><p> • Digital Economy</p><p> • Financial Inclusion</p><p> • Fintech and Banking</p><p> • Cyber Security</p><p> • Digital Payment Systems</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important facts include:</p><p>• NPCI full form</p><p> • UPI full form</p><p> • Establishment year of NPCI</p><p> • Difference between RBI and NPCI</p><p> • Digital payment methods</p><p> • International UPI expansion</p><p> • RuPay and BHIM</p><p> • RBI regulation of payment systems</p><p><br></p><p><br></p><p><br></p>', '', 'ECONOMY & BANKING', '', '', NULL, 'active', 1, '2026-05-04 09:56:00', '2026-05-13 15:34:02', '2026-05-13 15:34:02');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(69, '• Indian Air Force conducts major air defence exercise', '', '<h2>Indian Air Force conducts major air defence exercise</h2><p><br></p><p>• Tests integrated combat preparedness and defence coordination.</p><p>• Focus on aerial security, rapid response and operational readiness.</p>', '', '<p>Indian Air Force Conducts Major Air Defence Exercise</p><p><strong>What is Indian Air Force (IAF)?</strong></p><p>The Indian Air Force (IAF) is the air warfare branch of the Indian Armed Forces. It is responsible for protecting Indian airspace, conducting aerial warfare and supporting national security during peace and war. The Indian Air Force plays a major role in defending the country from aerial threats and supporting military operations through fighter aircraft, helicopters, transport aircraft and advanced defence systems.</p><p>The Indian Air Force is considered one of the strongest air forces in the world and is equipped with modern fighter jets, missile systems, radar networks and surveillance technologies.</p><p class=\"ql-align-center\"><br></p><p><strong>Establishment of Indian Air Force</strong></p><p>The Indian Air Force was established on:</p><p>• 8 October 1932</p><p>Initially, it was known as the Royal Indian Air Force during British rule. After India became a republic in 1950, the word “Royal” was removed and it became the Indian Air Force.</p><p class=\"ql-align-center\"><br></p><p><strong>Headquarters of Indian Air Force</strong></p><p>The headquarters of the Indian Air Force is located in:</p><p>• New Delhi</p><p class=\"ql-align-center\"><br></p><p><strong>Motto of Indian Air Force</strong></p><p>The motto of the Indian Air Force is:</p><p>• “Nabha Sparsham Deeptam”</p><p>Meaning:</p><p>• “Touch the Sky with Glory”</p><p>The motto is taken from the Bhagavad Gita.</p><p class=\"ql-align-center\"><br></p><p><strong>Current Chief of Air Staff</strong></p><p>The professional head of the Indian Air Force is called the:</p><p>• Chief of Air Staff (CAS)</p><p>Current Chief of Air Staff (2026):</p><p>• Air Chief Marshal Amar Preet Singh</p><p>The head of the Air Force is not called Chairman or Major. The highest-ranking officer in the IAF is the Air Chief Marshal serving as Chief of Air Staff.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Roles of Indian Air Force</strong></p><p><strong>Air Defence</strong></p><p>The IAF protects Indian airspace from enemy aircraft, missiles and aerial attacks.</p><p class=\"ql-align-center\"><br></p><p><strong>Combat Operations</strong></p><p>The Air Force conducts aerial warfare and supports military missions during conflicts.</p><p class=\"ql-align-center\"><br></p><p><strong>Transport and Logistics</strong></p><p>The IAF transports troops, weapons, relief materials and military equipment across the country.</p><p class=\"ql-align-center\"><br></p><p><strong>Disaster Relief and Rescue</strong></p><p>The Air Force helps during natural disasters, rescue operations and humanitarian missions.</p><p class=\"ql-align-center\"><br></p><p><strong>Surveillance and Reconnaissance</strong></p><p>The IAF uses radar systems, satellites and aircraft for monitoring borders and enemy activities.</p><p class=\"ql-align-center\"><br></p><p><strong>What is an Air Defence Exercise?</strong></p><p>An air defence exercise is a military training operation conducted to test and improve a country’s air defence capabilities, combat preparedness and coordination among defence forces.</p><p>These exercises simulate real combat situations and help armed forces practice responding to enemy air attacks, missile threats and emergency situations.</p><p>Air defence exercises involve:</p><p>• fighter aircraft</p><p> • radar systems</p><p> • missile defence systems</p><p> • command centres</p><p> • surveillance aircraft</p><p> • communication networks</p><p>The purpose is to ensure rapid response, operational readiness and effective coordination during national security threats.</p><p class=\"ql-align-center\"><br></p><p><strong>What was the news about?</strong></p><p>The news states that the Indian Air Force conducted a major air defence exercise to test integrated combat preparedness and defence coordination. The exercise focused on improving aerial security, rapid response capabilities and operational readiness of defence systems.</p><p>The exercise involved coordination between fighter aircraft, radar systems, air defence units and command centres to simulate real-time combat and aerial threat situations.</p><p>The objective was to strengthen India’s defence preparedness against possible air attacks and improve coordination among different military units.</p><p class=\"ql-align-center\"><br></p><p><strong>Why are Air Defence Exercises important?</strong></p><p>Air defence exercises are important because they help armed forces remain prepared for emergencies and national security threats.</p><p>These exercises help in:</p><p>• testing defence systems</p><p> • improving military coordination</p><p> • strengthening surveillance systems</p><p> • increasing combat readiness</p><p> • identifying weaknesses in defence infrastructure</p><p> • training military personnel for real combat situations</p><p>They also ensure faster decision-making and better communication during military operations.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Combat Preparedness?</strong></p><p>Combat preparedness means the readiness of military forces to respond effectively during war or security threats.</p><p>It includes:</p><p>• trained personnel</p><p> • operational weapons</p><p> • modern aircraft</p><p> • communication systems</p><p> • logistics support</p><p> • emergency response capability</p><p>High combat preparedness ensures that armed forces can quickly respond to enemy attacks and protect national security.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Defence Coordination?</strong></p><p>Defence coordination refers to cooperation and communication among different defence units, military branches and command systems during operations.</p><p>Effective defence coordination helps:</p><p>• improve mission success</p><p> • avoid communication failures</p><p> • increase operational efficiency</p><p> • ensure rapid military response</p><p>It is extremely important during air defence operations and national emergencies.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Operational Readiness?</strong></p><p>Operational readiness means the ability of military forces and equipment to perform missions effectively whenever required.</p><p>It includes:</p><p>• aircraft readiness</p><p> • weapon availability</p><p> • pilot training</p><p> • radar functionality</p><p> • fuel and logistics support</p><p>A high level of operational readiness ensures that defence forces can immediately respond to threats.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Aerial Security?</strong></p><p>Aerial security refers to protection of national airspace from enemy aircraft, drones, missiles and aerial threats.</p><p>The Indian Air Force maintains aerial security through:</p><p>• fighter jets</p><p> • radar systems</p><p> • missile defence systems</p><p> • surveillance aircraft</p><p> • air defence networks</p><p>Aerial security is important for protecting cities, military bases and strategic infrastructure.</p><p class=\"ql-align-center\"><br></p><p><strong>Major Aircraft of Indian Air Force</strong></p><p>Some important aircraft used by the Indian Air Force include:</p><p><strong>Fighter Aircraft</strong></p><p>• Rafale</p><p> • Sukhoi Su-30MKI</p><p> • Tejas</p><p> • Mirage 2000</p><p> • MiG-29</p><p class=\"ql-align-center\"><br></p><p><strong>Transport Aircraft</strong></p><p>• C-17 Globemaster</p><p> • C-130J Super Hercules</p><p> • AN-32</p><p class=\"ql-align-center\"><br></p><p><strong>Helicopters</strong></p><p>• Apache</p><p> • Chinook</p><p> • ALH Dhruv</p><p class=\"ql-align-center\"><br></p><p><strong>Important Military Exercises of Indian Air Force</strong></p><p><strong>Exercise Gagan Shakti</strong></p><p>A large-scale air warfare exercise conducted by the Indian Air Force to test combat capabilities.</p><p class=\"ql-align-center\"><br></p><p><strong>Exercise Vayu Shakti</strong></p><p>An operational exercise involving live aerial weapon demonstrations.</p><p class=\"ql-align-center\"><br></p><p><strong>Exercise Cope India</strong></p><p>A joint air exercise between India and the United States Air Force.</p><p class=\"ql-align-center\"><br></p><p><strong>Exercise Garuda</strong></p><p>A joint air exercise between India and France.</p><p class=\"ql-align-center\"><br></p><p><strong>Exercise Desert Eagle</strong></p><p>Joint exercise involving India and UAE Air Forces.</p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important for:</p><p>• Defence and Security</p><p> • Indian Armed Forces</p><p> • National Security</p><p> • Military Exercises</p><p> • Air Defence Systems</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important facts include:</p><p>• Establishment year of IAF</p><p> • Headquarters of Indian Air Force</p><p> • Motto of IAF</p><p> • Chief of Air Staff</p><p> • Meaning of air defence exercise</p><p> • Major military exercises</p><p> • Fighter aircraft names</p><p> • Combat preparedness and aerial security concepts</p><p><br></p>', '', 'DEFENCE & SECURITY', '', '', NULL, 'active', 1, '2026-05-04 10:12:00', '2026-05-13 15:52:56', '2026-05-13 15:52:56');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(70, 'Ministry of Home Affairs reviews cyber security preparedness', '', '<h2>Ministry of Home Affairs reviews cyber security preparedness</h2><p><br></p><p>• Focus on strengthening digital security and cyber attack response systems.</p><p>• Enhances protection of critical infrastructure and online networks.</p>', '<h2>गृह मंत्रालय ने साइबर सुरक्षा तैयारियों की समीक्षा की</h2><p><br></p><p>• डिजिटल सुरक्षा और साइबर हमले प्रतिक्रिया प्रणाली को मजबूत करने पर ध्यान दें।</p><p>• महत्वपूर्ण बुनियादी ढांचे और ऑनलाइन नेटवर्क की सुरक्षा बढ़ाता है।</p>', '<p>Ministry of Home Affairs Reviews Cyber Security Preparedness</p><p><strong>What is the main news about?</strong></p><p>The Ministry of Home Affairs (MHA) reviewed India’s cyber security preparedness to strengthen protection against increasing cyber threats and digital attacks. The review focused on improving digital security systems, cyber attack response mechanisms and protection of critical infrastructure and online networks.</p><p>The government discussed ways to improve coordination among cyber security agencies, strengthen monitoring systems and ensure faster response during cyber attacks. The review also emphasized protecting sensitive government systems, banking networks, communication systems and digital infrastructure from cyber threats.</p><p>The initiative is important because India’s increasing use of digital technology, online banking and internet-based services has also increased cyber security risks.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Ministry of Home Affairs (MHA)?</strong></p><p>The Ministry of Home Affairs is an important ministry of the Government of India responsible for internal security, law and order, border management and national security.</p><p>The ministry works on:</p><p>• internal security</p><p> • cyber security</p><p> • disaster management</p><p> • police administration</p><p> • border security</p><p> • anti-terror operations</p><p class=\"ql-align-center\"><br></p><p><strong>Current Home Minister of India</strong></p><p>The current Union Home Minister of India (2026) is:</p><p>• Amit Shah</p><p>The Home Minister heads the Ministry of Home Affairs and supervises national internal security matters.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Cyber Security?</strong></p><p>Cyber security refers to the protection of computer systems, digital networks, software, servers and data from cyber threats, hacking and unauthorized access.</p><p>Cyber security aims to protect sensitive information and digital infrastructure from cybercriminals, malware and online attacks.</p><p>It includes technologies, security systems and practices designed to prevent:</p><p>• hacking</p><p> • data theft</p><p> • cyber fraud</p><p> • malware attacks</p><p> • network damage</p><p> • unauthorized access</p><p class=\"ql-align-center\"><br></p><p><strong>Why is Cyber Security important?</strong></p><p>Cyber security is extremely important because governments, banks, businesses and individuals depend heavily on digital systems and internet-based services.</p><p>Strong cyber security helps protect:</p><p>• banking systems</p><p> • online payments</p><p> • government databases</p><p> • military networks</p><p> • communication systems</p><p> • personal information</p><p>Without strong cyber security, cyber attacks can cause financial loss, data theft and disruption of critical services.</p><p class=\"ql-align-center\"><br></p><p><strong>What is a Cyber Attack?</strong></p><p>A cyber attack is an attempt by hackers or cybercriminals to damage, steal or gain unauthorized access to computer systems, digital networks or sensitive information.</p><p>Cyber attacks target:</p><p>• government systems</p><p> • banks</p><p> • businesses</p><p> • defence networks</p><p> • mobile phones</p><p> • personal accounts</p><p>The purpose may include stealing money, damaging systems, spying or disrupting services.</p><p class=\"ql-align-center\"><br></p><p><strong>Common Types of Cyber Attacks</strong></p><p><strong>Phishing Attack</strong></p><p>Fraudulent emails, SMS or websites are used to trick people into sharing passwords, OTPs or banking information.</p><p class=\"ql-align-center\"><br></p><p><strong>Malware Attack</strong></p><p>Malicious software such as viruses or spyware is used to damage or control systems.</p><p class=\"ql-align-center\"><br></p><p><strong>Ransomware Attack</strong></p><p>Hackers lock or encrypt data and demand money to restore access.</p><p class=\"ql-align-center\"><br></p><p><strong>Hacking</strong></p><p>Unauthorized access to systems or accounts to steal or manipulate data.</p><p class=\"ql-align-center\"><br></p><p><strong>Denial of Service (DoS) Attack</strong></p><p>Attackers overload websites or networks with traffic to make services unavailable.</p><p class=\"ql-align-center\"><br></p><p><strong>Identity Theft</strong></p><p>Personal information is stolen and misused for fraud or illegal activities.</p><p class=\"ql-align-center\"><br></p><p><strong>How do Cyber Attacks happen?</strong></p><p>Cyber attacks happen through various methods used by hackers and cybercriminals.</p><p>Some common methods include:</p><p>• fake emails and SMS links</p><p> • infected software downloads</p><p> • weak passwords</p><p> • unsecured Wi-Fi networks</p><p> • fake mobile applications</p><p> • malicious websites</p><p> • social engineering techniques</p><p>Hackers exploit security weaknesses in systems and trick users into revealing sensitive information.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Cyber Security Preparedness?</strong></p><p>Cyber security preparedness means the readiness of organizations and governments to prevent, detect and respond to cyber attacks effectively.</p><p>It includes:</p><p>• secure digital systems</p><p> • trained cyber experts</p><p> • real-time monitoring</p><p> • emergency response systems</p><p> • backup systems</p><p> • cyber awareness programs</p><p>Preparedness helps reduce damage during cyber attacks and ensures quick recovery.</p><p class=\"ql-align-center\"><br></p><p><strong>Why did the Ministry of Home Affairs review cyber security preparedness?</strong></p><p>The Ministry reviewed cyber security preparedness because cyber threats are increasing rapidly due to expansion of digital services, online banking and internet usage.</p><p>The review aimed to:</p><p>• strengthen digital security</p><p> • improve cyber attack response systems</p><p> • protect critical infrastructure</p><p> • improve coordination among agencies</p><p> • secure government networks</p><p> • prevent cybercrime and cyber terrorism</p><p>The government wants to ensure that India’s digital infrastructure remains safe and secure.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Critical Infrastructure?</strong></p><p>Critical infrastructure refers to essential systems and facilities necessary for the functioning of a country.</p><p>Examples include:</p><p>• power grids</p><p> • banking systems</p><p> • telecom networks</p><p> • airports</p><p> • railway systems</p><p> • defence networks</p><p> • internet systems</p><p>Cyber attacks on critical infrastructure can seriously affect national security and public services.</p><p class=\"ql-align-center\"><br></p><p><strong>How can Cyber Attacks be prevented?</strong></p><p><strong>Strong Passwords</strong></p><p>Using strong and unique passwords helps protect accounts from hacking.</p><p class=\"ql-align-center\"><br></p><p><strong>Two-Factor Authentication (2FA)</strong></p><p>Extra security verification such as OTP or biometric authentication improves protection.</p><p class=\"ql-align-center\"><br></p><p><strong>Updated Software</strong></p><p>Regular software updates help fix security vulnerabilities.</p><p class=\"ql-align-center\"><br></p><p><strong>Avoid Suspicious Links</strong></p><p>Users should avoid clicking unknown links or downloading suspicious files.</p><p class=\"ql-align-center\"><br></p><p><strong>Secure Networks</strong></p><p>Using secure internet connections and firewalls improves network safety.</p><p class=\"ql-align-center\"><br></p><p><strong>Cyber Awareness</strong></p><p>Public awareness about cyber fraud and digital threats helps reduce cybercrime.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Cyber Crime?</strong></p><p>Cyber crime refers to illegal activities conducted using computers, internet systems or digital devices.</p><p>Examples include:</p><p>• online fraud</p><p> • hacking</p><p> • identity theft</p><p> • cyber bullying</p><p> • financial scams</p><p> • data theft</p><p>Cyber crime has increased significantly with the growth of digital technology and online transactions.</p><p class=\"ql-align-center\"><br></p><p><strong>Important Cyber Security Organizations in India</strong></p><p><strong>CERT-In</strong></p><p>CERT-In stands for:</p><p>• Indian Computer Emergency Response Team</p><p>It is the national agency responsible for handling cyber security incidents in India.</p><p class=\"ql-align-center\"><br></p><p><strong>National Critical Information Infrastructure Protection Centre (NCIIPC)</strong></p><p>NCIIPC protects India’s critical digital infrastructure from cyber threats.</p><p class=\"ql-align-center\"><br></p><p><strong>Ministry of Electronics and Information Technology (MeitY)</strong></p><p>MeitY works on digital governance, cyber policies and information technology development.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important for:</p><p>• Internal Security</p><p> • Cyber Security</p><p> • Digital Governance</p><p> • National Security</p><p> • Critical Infrastructure Protection</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important facts include:</p><p>• Meaning of cyber security</p><p> • Meaning of cyber attack</p><p> • CERT-In full form</p><p> • Ministry of Home Affairs role</p><p> • Types of cyber attacks</p><p> • Critical infrastructure</p><p> • Digital security systems</p><p> • Cyber crime concepts</p><p><br></p><p><br></p>', '<p>गृह मंत्रालय ने साइबर सुरक्षा तैयारियों की समीक्षा की</p><p><strong>मुख्य समाचार किस बारे में है?</strong></p><p>गृह मंत्रालय (एमएचए) ने बढ़ते साइबर खतरों और डिजिटल हमलों के खिलाफ सुरक्षा को मजबूत करने के लिए भारत की साइबर सुरक्षा तैयारियों की समीक्षा की। समीक्षा में डिजिटल सुरक्षा प्रणालियों, साइबर हमले प्रतिक्रिया तंत्र और महत्वपूर्ण बुनियादी ढांचे और ऑनलाइन नेटवर्क की सुरक्षा में सुधार पर ध्यान केंद्रित किया गया।</p><p>सरकार ने साइबर सुरक्षा एजेंसियों के बीच समन्वय में सुधार, निगरानी प्रणाली को मजबूत करने और साइबर हमलों के दौरान तेज प्रतिक्रिया सुनिश्चित करने के तरीकों पर चर्चा की। समीक्षा में संवेदनशील सरकारी प्रणालियों, बैंकिंग नेटवर्क, संचार प्रणालियों और डिजिटल बुनियादी ढांचे को साइबर खतरों से बचाने पर भी जोर दिया गया।</p><p>यह पहल महत्वपूर्ण है क्योंकि भारत में डिजिटल तकनीक, ऑनलाइन बैंकिंग और इंटरनेट-आधारित सेवाओं के बढ़ते उपयोग ने साइबर सुरक्षा जोखिम भी बढ़ा दिया है।</p><p class=\"ql-align-center\"><br></p><p><strong>गृह मंत्रालय (एमएचए) क्या है?</strong></p><p>गृह मंत्रालय भारत सरकार का एक महत्वपूर्ण मंत्रालय है जो आंतरिक सुरक्षा, कानून और व्यवस्था, सीमा प्रबंधन और राष्ट्रीय सुरक्षा के लिए जिम्मेदार है।</p><p>मंत्रालय इस पर काम करता है:</p><p>• आंतरिक सुरक्षा</p><p>• साइबर सुरक्षा</p><p>• आपदा प्रबंधन</p><p>• पुलिस प्रशासन</p><p>• सीमा सुरक्षा</p><p>• आतंकवाद विरोधी अभियान</p><p class=\"ql-align-center\"><br></p><p><strong>भारत के वर्तमान गृह मंत्री</strong></p><p>भारत के वर्तमान केंद्रीय गृह मंत्री (2026) हैं:</p><p>• अमित शाह</p><p>गृह मंत्री गृह मंत्रालय का प्रमुख होता है और राष्ट्रीय आंतरिक सुरक्षा मामलों की निगरानी करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>साइबर सुरक्षा क्या है?</strong></p><p>साइबर सुरक्षा से तात्पर्य कंप्यूटर सिस्टम, डिजिटल नेटवर्क, सॉफ्टवेयर, सर्वर और डेटा को साइबर खतरों, हैकिंग और अनधिकृत पहुंच से सुरक्षा से है।</p><p>साइबर सुरक्षा का उद्देश्य संवेदनशील जानकारी और डिजिटल बुनियादी ढांचे को साइबर अपराधियों, मैलवेयर और ऑनलाइन हमलों से बचाना है।</p><p>इसमें निम्नलिखित को रोकने के लिए डिज़ाइन की गई प्रौद्योगिकियाँ, सुरक्षा प्रणालियाँ और प्रथाएँ शामिल हैं:</p><p>• हैकिंग</p><p>• डेटा चोरी</p><p>• साइबर धोखाधड़ी</p><p>• मैलवेयर हमले</p><p>• नेटवर्क क्षति</p><p>• अनधिकृत पहुंच</p><p class=\"ql-align-center\"><br></p><p><strong>साइबर सुरक्षा क्यों महत्वपूर्ण है?</strong></p><p>साइबर सुरक्षा अत्यंत महत्वपूर्ण है क्योंकि सरकारें, बैंक, व्यवसाय और व्यक्ति डिजिटल सिस्टम और इंटरनेट-आधारित सेवाओं पर बहुत अधिक निर्भर हैं।</p><p>मजबूत साइबर सुरक्षा सुरक्षा में मदद करती है:</p><p>• बैंकिंग प्रणाली</p><p>• ऑनलाइन भुगतान</p><p>• सरकारी डेटाबेस</p><p>• सैन्य नेटवर्क</p><p>• संचार प्रणाली</p><p>• व्यक्तिगत जानकारी</p><p>मजबूत साइबर सुरक्षा के बिना, साइबर हमलों से वित्तीय नुकसान, डेटा चोरी और महत्वपूर्ण सेवाओं में व्यवधान हो सकता है।</p><p class=\"ql-align-center\"><br></p><p><strong>साइबर हमला क्या है?</strong></p><p>साइबर हमला हैकर्स या साइबर अपराधियों द्वारा कंप्यूटर सिस्टम, डिजिटल नेटवर्क या संवेदनशील जानकारी को नुकसान पहुंचाने, चोरी करने या अनधिकृत पहुंच प्राप्त करने का एक प्रयास है।</p><p>साइबर हमलों का लक्ष्य:</p><p>• सरकारी प्रणालियाँ</p><p>• बैंक</p><p>• व्यवसाय</p><p>• रक्षा नेटवर्क</p><p>• मोबाइल फ़ोन</p><p>• व्यक्तिगत खाते</p><p>उद्देश्य में पैसे चुराना, सिस्टम को नुकसान पहुंचाना, जासूसी करना या सेवाओं में बाधा डालना शामिल हो सकता है।</p><p class=\"ql-align-center\"><br></p><p><strong>साइबर हमलों के सामान्य प्रकार</strong></p><p><strong>फ़िशिंग हमला</strong></p><p>लोगों को पासवर्ड, ओटीपी या बैंकिंग जानकारी साझा करने के लिए धोखा देने के लिए धोखाधड़ी वाले ईमेल, एसएमएस या वेबसाइटों का उपयोग किया जाता है।</p><p class=\"ql-align-center\"><br></p><p><strong>मैलवेयर हमला</strong></p><p>वायरस या स्पाइवेयर जैसे दुर्भावनापूर्ण सॉफ़्टवेयर का उपयोग सिस्टम को नुकसान पहुंचाने या नियंत्रित करने के लिए किया जाता है।</p><p class=\"ql-align-center\"><br></p><p><strong>रैंसमवेयर हमला</strong></p><p>हैकर्स डेटा को लॉक या एन्क्रिप्ट करते हैं और एक्सेस बहाल करने के लिए पैसे की मांग करते हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>हैकिंग</strong></p><p>डेटा चुराने या हेरफेर करने के लिए सिस्टम या खातों तक अनधिकृत पहुंच।</p><p class=\"ql-align-center\"><br></p><p><strong>सेवा से इनकार (DoS) हमला</strong></p><p>हमलावर सेवाओं को अनुपलब्ध बनाने के लिए वेबसाइटों या नेटवर्क पर ट्रैफ़िक बढ़ा देते हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>चोरी की पहचान</strong></p><p>व्यक्तिगत जानकारी चुरा ली जाती है और धोखाधड़ी या अवैध गतिविधियों के लिए इसका दुरुपयोग किया जाता है।</p><p class=\"ql-align-center\"><br></p><p><strong>साइबर हमले कैसे होते हैं?</strong></p><p>साइबर हमले हैकर्स और साइबर अपराधियों द्वारा इस्तेमाल किए जाने वाले विभिन्न तरीकों से होते हैं।</p><p>कुछ सामान्य तरीकों में शामिल हैं:</p><p>• फर्जी ईमेल और एसएमएस लिंक</p><p>• संक्रमित सॉफ़्टवेयर डाउनलोड</p><p>• कमजोर पासवर्ड</p><p>• असुरक्षित वाई-फाई नेटवर्क</p><p>• नकली मोबाइल एप्लीकेशन</p><p>• दूषित वेबसाइट</p><p>• सोशल इंजीनियरिंग तकनीक</p><p>हैकर्स सिस्टम में सुरक्षा कमजोरियों का फायदा उठाते हैं और उपयोगकर्ताओं को संवेदनशील जानकारी प्रकट करने के लिए बरगलाते हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>साइबर सुरक्षा तैयारी क्या है?</strong></p><p>साइबर सुरक्षा तैयारी का अर्थ साइबर हमलों को प्रभावी ढंग से रोकने, पता लगाने और प्रतिक्रिया देने के लिए संगठनों और सरकारों की तत्परता है।</p><p>इसमें शामिल है:</p><p>• सुरक्षित डिजिटल सिस्टम</p><p>• प्रशिक्षित साइबर विशेषज्ञ</p><p>• वास्तविक समय में निगरानी</p><p>• आपातकालीन प्रतिक्रिया प्रणाली</p><p>• बैकअप सिस्टम</p><p>• साइबर जागरूकता कार्यक्रम</p><p>तैयारी साइबर हमलों के दौरान क्षति को कम करने में मदद करती है और त्वरित वसूली सुनिश्चित करती है।</p><p class=\"ql-align-center\"><br></p><p><strong>गृह मंत्रालय ने साइबर सुरक्षा तैयारियों की समीक्षा क्यों की?</strong></p><p>मंत्रालय ने साइबर सुरक्षा तैयारियों की समीक्षा की क्योंकि डिजिटल सेवाओं, ऑनलाइन बैंकिंग और इंटरनेट के उपयोग के विस्तार के कारण साइबर खतरे तेजी से बढ़ रहे हैं।</p><p>समीक्षा का उद्देश्य:</p><p>• डिजिटल सुरक्षा को मजबूत करना</p><p>• साइबर हमले की प्रतिक्रिया प्रणाली में सुधार</p><p>• महत्वपूर्ण बुनियादी ढांचे की रक्षा करें</p><p>• एजेंसियों के बीच समन्वय में सुधार</p><p>• सुरक्षित सरकारी नेटवर्क</p><p>• साइबर अपराध और साइबर आतंकवाद को रोकें</p><p>सरकार यह सुनिश्चित करना चाहती है कि भारत का डिजिटल बुनियादी ढांचा सुरक्षित रहे।</p><p class=\"ql-align-center\"><br></p><p><strong>क्रिटिकल इन्फ्रास्ट्रक्चर क्या है?</strong></p><p>महत्वपूर्ण बुनियादी ढांचे से तात्पर्य किसी देश के कामकाज के लिए आवश्यक आवश्यक प्रणालियों और सुविधाओं से है।</p><p>उदाहरणों में शामिल हैं:</p><p>• बिजली के जाल</p><p>• बैंकिंग प्रणाली</p><p>• दूरसंचार नेटवर्क</p><p>• हवाई अड्डे</p><p>• रेलवे सिस्टम</p><p>• रक्षा नेटवर्क</p><p>• इंटरनेट सिस्टम</p><p>महत्वपूर्ण बुनियादी ढांचे पर साइबर हमले राष्ट्रीय सुरक्षा और सार्वजनिक सेवाओं को गंभीर रूप से प्रभावित कर सकते हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>साइबर हमलों को कैसे रोका जा सकता है?</strong></p><p><strong>मजबूत पासवर्ड</strong></p><p>मजबूत और अद्वितीय पासवर्ड का उपयोग करने से खातों को हैकिंग से बचाने में मदद मिलती है।</p><p class=\"ql-align-center\"><br></p><p><strong>दो-कारक प्रमाणीकरण (2FA)</strong></p><p>ओटीपी या बायोमेट्रिक प्रमाणीकरण जैसे अतिरिक्त सुरक्षा सत्यापन से सुरक्षा में सुधार होता है।</p><p class=\"ql-align-center\"><br></p><p><strong>अद्यतन सॉफ्टवेयर</strong></p><p>नियमित सॉफ़्टवेयर अपडेट सुरक्षा कमजोरियों को ठीक करने में मदद करते हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>संदिग्ध लिंक से बचें</strong></p><p>उपयोगकर्ताओं को अज्ञात लिंक पर क्लिक करने या संदिग्ध फ़ाइलें डाउनलोड करने से बचना चाहिए।</p><p class=\"ql-align-center\"><br></p><p><strong>सुरक्षित नेटवर्क</strong></p><p>सुरक्षित इंटरनेट कनेक्शन और फ़ायरवॉल का उपयोग करने से नेटवर्क सुरक्षा में सुधार होता है।</p><p class=\"ql-align-center\"><br></p><p><strong>साइबर जागरूकता</strong></p><p>साइबर धोखाधड़ी और डिजिटल खतरों के बारे में सार्वजनिक जागरूकता साइबर अपराध को कम करने में मदद करती है।</p><p class=\"ql-align-center\"><br></p><p><strong>साइबर क्राइम क्या है?</strong></p><p>साइबर अपराध का तात्पर्य कंप्यूटर, इंटरनेट सिस्टम या डिजिटल उपकरणों का उपयोग करके की जाने वाली अवैध गतिविधियों से है।</p><p>उदाहरणों में शामिल हैं:</p><p>• ऑनलाइन धोखाधड़ी</p><p>• हैकिंग</p><p>• चोरी की पहचान</p><p>• साइबर बदमाशी</p><p>• वित्तीय घोटाले</p><p>• डेटा चोरी</p><p>डिजिटल प्रौद्योगिकी और ऑनलाइन लेनदेन के विकास के साथ साइबर अपराध में काफी वृद्धि हुई है।</p><p class=\"ql-align-center\"><br></p><p><strong>भारत में महत्वपूर्ण साइबर सुरक्षा संगठन</strong></p><p><strong>CERT-इन</strong></p><p>CERT-In का अर्थ है:</p><p>• भारतीय कंप्यूटर आपातकालीन प्रतिक्रिया टीम</p><p>यह भारत में साइबर सुरक्षा घटनाओं से निपटने के लिए जिम्मेदार राष्ट्रीय एजेंसी है।</p><p class=\"ql-align-center\"><br></p><p><strong>राष्ट्रीय महत्वपूर्ण सूचना अवसंरचना संरक्षण केंद्र (एनसीआईआईपीसी)</strong></p><p>एनसीआईआईपीसी भारत के महत्वपूर्ण डिजिटल बुनियादी ढांचे को साइबर खतरों से बचाता है।</p><p class=\"ql-align-center\"><br></p><p><strong>इलेक्ट्रॉनिक्स और सूचना प्रौद्योगिकी मंत्रालय (MeitY)</strong></p><p>MeitY डिजिटल प्रशासन, साइबर नीतियों और सूचना प्रौद्योगिकी विकास पर काम करता है।</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><strong>परीक्षा के लिए महत्व</strong></p><p><strong>यूपीएससी</strong></p><p>इसके लिए महत्वपूर्ण:</p><p>• आंतरिक सुरक्षा</p><p>• साइबर सुरक्षा</p><p>• डिजिटल गवर्नेंस</p><p>• राष्ट्रीय सुरक्षा</p><p>• महत्वपूर्ण बुनियादी ढांचे की सुरक्षा</p><p class=\"ql-align-center\"><br></p><p><strong>एसएससी/रेलवे/बैंकिंग</strong></p><p>महत्वपूर्ण तथ्यों में शामिल हैं:</p><p>• साइबर सुरक्षा का अर्थ</p><p>• साइबर हमले का मतलब</p><p>• CERT-पूर्ण रूप में</p><p>• गृह मंत्रालय की भूमिका</p><p>• साइबर हमलों के प्रकार</p><p>• महत्वपूर्ण बुनियादी ढाँचा</p><p>• डिजिटल सुरक्षा प्रणालियाँ</p><p>• साइबर अपराध अवधारणाएँ</p><p><br></p>', 'DEFENCE & SECURITY', '', '', NULL, 'active', 1, '2026-05-04 12:04:00', '2026-05-13 17:41:04', '2026-05-13 17:41:04');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(71, 'Indian shooters win medals at international championship', 'भारतीय निशानेबाजों ने अंतरराष्ट्रीय चैम्पियनशिप में पदक जीते', '<h2>Indian shooters win medals at international championship</h2><p><br></p><p>• Indian athletes performed strongly in shooting events.</p><p>• Highlights India’s growing success in international shooting competitions.</p>', '<h2>भारतीय निशानेबाजों ने अंतरराष्ट्रीय चैम्पियनशिप में पदक जीते</h2><p><br></p><p>• निशानेबाजी स्पर्धाओं में भारतीय एथलीटों ने जोरदार प्रदर्शन किया.</p><p>• अंतरराष्ट्रीय शूटिंग प्रतियोगिताओं में भारत की बढ़ती सफलता पर प्रकाश डाला गया।</p>', '<p>Indian Shooters Win Medals at International Championship</p><p><strong>What is the news about?</strong></p><p>Indian shooters delivered an impressive performance at an international shooting championship by winning multiple medals in different shooting events. The strong performance of Indian athletes highlighted India’s growing success and rising dominance in international shooting competitions.</p><p>Indian shooters performed exceptionally well in rifle, pistol and mixed-team events and secured medals against top shooters from various countries. The achievement reflects the improvement in India’s sports infrastructure, athlete training and international-level preparation in shooting sports.</p><p>The success of Indian shooters also boosted India’s reputation in global sports and demonstrated the country’s growing strength in precision-based Olympic sports.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Shooting Sport?</strong></p><p>Shooting is a competitive sport in which athletes use firearms or air guns to hit specific targets with maximum accuracy and precision.</p><p>The sport requires:</p><p>• concentration</p><p> • accuracy</p><p> • mental control</p><p> • stability</p><p> • discipline</p><p> • quick reflexes</p><p>Shooting is one of the important sports included in the Olympic Games and other international competitions.</p><p class=\"ql-align-center\"><br></p><p><strong>Main Types of Shooting Events</strong></p><p><strong>Rifle Shooting</strong></p><p>Athletes use rifles to shoot targets placed at fixed distances.</p><p>Common events include:</p><p>• 10m Air Rifle</p><p> • 50m Rifle 3 Positions</p><p class=\"ql-align-center\"><br></p><p><strong>Pistol Shooting</strong></p><p>Competitors use pistols to hit targets with precision.</p><p>Popular events include:</p><p>• 10m Air Pistol</p><p> • 25m Pistol</p><p class=\"ql-align-center\"><br></p><p><strong>Shotgun Events</strong></p><p>Athletes shoot moving targets called clay targets.</p><p>Major shotgun events include:</p><p>• Trap</p><p> • Skeet</p><p class=\"ql-align-center\"><br></p><p><strong>Why is India becoming successful in shooting sports?</strong></p><p>India’s success in shooting sports has increased due to better training facilities, international coaching, modern equipment and government support.</p><p>Several factors contributed to India’s growth in shooting:</p><p>• sports academies and training centres</p><p> • international exposure for athletes</p><p> • support under schemes like TOPS and Khelo India</p><p> • improved sports science and coaching</p><p> • strong junior-level talent development</p><p>Indian shooters are now regularly winning medals in Olympics, Asian Games, Commonwealth Games and World Championships.</p><p class=\"ql-align-center\"><br></p><p><strong>Major Indian Shooters</strong></p><p>Some famous Indian shooters include:</p><p><strong>Abhinav Bindra</strong></p><p>• First Indian individual Olympic gold medal winner</p><p> • Won Gold in 10m Air Rifle at Beijing Olympics 2008</p><p class=\"ql-align-center\"><br></p><p><strong>Manu Bhaker</strong></p><p>• One of India’s top pistol shooters</p><p> • Won medals in international shooting competitions</p><p class=\"ql-align-center\"><br></p><p><strong>Saurabh Chaudhary</strong></p><p>• Famous Indian pistol shooter</p><p> • Won medals in Asian and ISSF events</p><p class=\"ql-align-center\"><br></p><p><strong>Anjum Moudgil</strong></p><p>• International rifle shooter from India</p><p class=\"ql-align-center\"><br></p><p><strong>Rudrankksh Patil</strong></p><p>• Indian rifle shooter known for world-level performances</p><p class=\"ql-align-center\"><br></p><p><strong>What is ISSF?</strong></p><p>ISSF stands for:</p><p>• International Shooting Sport Federation</p><p>It is the international governing body for shooting sports worldwide.</p><p>ISSF organizes major international competitions including:</p><p>• World Championships</p><p> • World Cups</p><p> • Olympic qualification events</p><p class=\"ql-align-center\"><br></p><p><strong>Major International Shooting Competitions</strong></p><p><strong>Olympic Games</strong></p><p>Shooting is an important Olympic sport with rifle, pistol and shotgun events.</p><p class=\"ql-align-center\"><br></p><p><strong>ISSF World Cup</strong></p><p>International shooting competition organized regularly by ISSF.</p><p class=\"ql-align-center\"><br></p><p><strong>Asian Games</strong></p><p>Indian shooters have won several medals in Asian Games shooting events.</p><p class=\"ql-align-center\"><br></p><p><strong>Commonwealth Games</strong></p><p>India has historically performed strongly in shooting at Commonwealth Games.</p><p class=\"ql-align-center\"><br></p><p><strong>Importance of Shooting Sports for India</strong></p><p>Shooting has become one of India’s strongest medal-winning sports at international competitions.</p><p>The sport contributes to:</p><p>• Olympic medal success</p><p> • international sports recognition</p><p> • youth participation in sports</p><p> • development of sports infrastructure</p><p> • promotion of precision sports in India</p><p>Indian shooters are increasingly becoming globally competitive due to consistent performances.</p><p class=\"ql-align-center\"><br></p><p><strong>What skills are important in shooting sports?</strong></p><p>Successful shooting athletes require:</p><p>• concentration</p><p> • hand-eye coordination</p><p> • breathing control</p><p> • patience</p><p> • mental strength</p><p> • focus and discipline</p><p>Even small mistakes can affect performance because shooting is a highly precision-based sport.</p><p class=\"ql-align-center\"><br></p><p><strong>Government Support for Shooting Sports</strong></p><p>The Government of India supports shooting athletes through various sports programs.</p><p><strong>TOPS Scheme</strong></p><p>TOPS stands for:</p><p>• Target Olympic Podium Scheme</p><p>It provides financial and training support to elite athletes preparing for international competitions.</p><p class=\"ql-align-center\"><br></p><p><strong>Khelo India</strong></p><p>Khelo India promotes sports talent development at school and youth levels.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important for:</p><p>• Sports and Youth Affairs</p><p> • International Sports Competitions</p><p> • Government Sports Schemes</p><p> • Olympic Sports</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important facts include:</p><p>• ISSF full form</p><p> • Abhinav Bindra achievement</p><p> • Shooting event types</p><p> • Olympic shooting events</p><p> • TOPS scheme</p><p> • India’s international sports achievements</p><p><br></p><p><br></p><p><br></p>', '<p>भारतीय निशानेबाजों ने अंतर्राष्ट्रीय चैम्पियनशिप में पदक जीते</p><p><strong>खबर किस बारे में है?</strong></p><p>भारतीय निशानेबाजों ने अंतरराष्ट्रीय निशानेबाजी चैंपियनशिप में अलग-अलग निशानेबाजी स्पर्धाओं में कई पदक जीतकर शानदार प्रदर्शन किया। भारतीय एथलीटों के दमदार प्रदर्शन ने अंतरराष्ट्रीय शूटिंग प्रतियोगिताओं में भारत की बढ़ती सफलता और बढ़ते प्रभुत्व को उजागर किया।</p><p>भारतीय निशानेबाजों ने राइफल, पिस्टल और मिश्रित टीम स्पर्धाओं में असाधारण प्रदर्शन किया और विभिन्न देशों के शीर्ष निशानेबाजों के खिलाफ पदक हासिल किये। यह उपलब्धि भारत के खेल बुनियादी ढांचे, एथलीट प्रशिक्षण और शूटिंग खेलों में अंतरराष्ट्रीय स्तर की तैयारी में सुधार को दर्शाती है।</p><p>भारतीय निशानेबाजों की सफलता ने वैश्विक खेलों में भारत की प्रतिष्ठा को भी बढ़ाया और सटीकता-आधारित ओलंपिक खेलों में देश की बढ़ती ताकत का प्रदर्शन किया।</p><p class=\"ql-align-center\"><br></p><p><strong>निशानेबाजी खेल क्या है?</strong></p><p>शूटिंग एक प्रतिस्पर्धी खेल है जिसमें एथलीट अधिकतम सटीकता और परिशुद्धता के साथ विशिष्ट लक्ष्यों को हिट करने के लिए आग्नेयास्त्रों या एयर गन का उपयोग करते हैं।</p><p>खेल के लिए आवश्यक है:</p><p>• एकाग्रता</p><p>• शुद्धता</p><p>• मानसिक नियंत्रण</p><p>• स्थिरता</p><p>• अनुशासन</p><p>• त्वरित सजगता</p><p>निशानेबाजी ओलंपिक खेलों और अन्य अंतरराष्ट्रीय प्रतियोगिताओं में शामिल महत्वपूर्ण खेलों में से एक है।</p><p class=\"ql-align-center\"><br></p><p><strong>शूटिंग आयोजनों के मुख्य प्रकार</strong></p><p><strong>राइफल चलाना</strong></p><p>एथलीट निश्चित दूरी पर स्थित लक्ष्यों पर गोली चलाने के लिए राइफलों का उपयोग करते हैं।</p><p>सामान्य घटनाओं में शामिल हैं:</p><p>• 10 मीटर एयर राइफल</p><p>• 50 मीटर राइफल 3 पोजीशन</p><p class=\"ql-align-center\"><br></p><p><strong>पिस्तौल की शूटिंग</strong></p><p>प्रतियोगी लक्ष्य पर सटीकता से प्रहार करने के लिए पिस्तौल का उपयोग करते हैं।</p><p>लोकप्रिय घटनाओं में शामिल हैं:</p><p>• 10 मीटर एयर पिस्टल</p><p>• 25 मीटर पिस्टल</p><p class=\"ql-align-center\"><br></p><p><strong>बन्दूक घटनाएँ</strong></p><p>एथलीट गतिशील लक्ष्यों पर गोली चलाते हैं जिन्हें क्ले टारगेट कहा जाता है।</p><p>प्रमुख बन्दूक घटनाओं में शामिल हैं:</p><p>• जाल</p><p>• स्कीट</p><p class=\"ql-align-center\"><br></p><p><strong>भारत निशानेबाजी खेल में सफल क्यों हो रहा है?</strong></p><p>बेहतर प्रशिक्षण सुविधाओं, अंतरराष्ट्रीय कोचिंग, आधुनिक उपकरणों और सरकारी समर्थन के कारण शूटिंग खेलों में भारत की सफलता बढ़ी है।</p><p>निशानेबाजी में भारत की वृद्धि में कई कारकों ने योगदान दिया:</p><p>• खेल अकादमियाँ और प्रशिक्षण केंद्र</p><p>• एथलीटों के लिए अंतर्राष्ट्रीय प्रदर्शन</p><p>• TOPS और खेलो इंडिया जैसी योजनाओं के तहत समर्थन</p><p>• खेल विज्ञान और कोचिंग में सुधार</p><p>• मजबूत जूनियर स्तर की प्रतिभा का विकास</p><p>भारतीय निशानेबाज अब नियमित रूप से ओलंपिक, एशियाई खेल, राष्ट्रमंडल खेल और विश्व चैंपियनशिप में पदक जीत रहे हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>प्रमुख भारतीय निशानेबाज</strong></p><p>कुछ प्रसिद्ध भारतीय निशानेबाजों में शामिल हैं:</p><p><strong>अभिनव बिंद्रा</strong></p><p>• पहले भारतीय व्यक्तिगत ओलंपिक स्वर्ण पदक विजेता</p><p>• बीजिंग ओलंपिक 2008 में 10 मीटर एयर राइफल में स्वर्ण पदक जीता</p><p class=\"ql-align-center\"><br></p><p><strong>मनु भाकर</strong></p><p>• भारत के शीर्ष पिस्टल निशानेबाजों में से एक</p><p>• अंतर्राष्ट्रीय शूटिंग प्रतियोगिताओं में पदक जीते</p><p class=\"ql-align-center\"><br></p><p><strong>-सौरभ चौधरी</strong></p><p>• प्रसिद्ध भारतीय पिस्तौल निशानेबाज</p><p>• एशियाई और आईएसएसएफ स्पर्धाओं में पदक जीते</p><p class=\"ql-align-center\"><br></p><p><strong>अंजुम मौदगिल</strong></p><p>• भारत के अंतर्राष्ट्रीय राइफल शूटर</p><p class=\"ql-align-center\"><br></p><p><strong>रुद्राक्ष पाटिल</strong></p><p>• भारतीय राइफल शूटर विश्व स्तरीय प्रदर्शन के लिए जाने जाते हैं</p><p class=\"ql-align-center\"><br></p><p><strong>आईएसएसएफ क्या है?</strong></p><p>आईएसएसएफ का अर्थ है:</p><p>• अंतर्राष्ट्रीय शूटिंग खेल महासंघ</p><p>यह दुनिया भर में शूटिंग खेलों के लिए अंतर्राष्ट्रीय शासी निकाय है।</p><p>ISSF प्रमुख अंतर्राष्ट्रीय प्रतियोगिताओं का आयोजन करता है जिनमें शामिल हैं:</p><p>• विश्व चैंपियनशिप</p><p>• विश्व कप</p><p>• ओलिंपिक क्वालिफिकेशन इवेंट</p><p class=\"ql-align-center\"><br></p><p><strong>प्रमुख अंतर्राष्ट्रीय निशानेबाजी प्रतियोगिताएँ</strong></p><p><strong>ओलंपिक खेल</strong></p><p>राइफल, पिस्टल और शॉटगन स्पर्धाओं के साथ निशानेबाजी एक महत्वपूर्ण ओलंपिक खेल है।</p><p class=\"ql-align-center\"><br></p><p><strong>आईएसएसएफ विश्व कप</strong></p><p>ISSF द्वारा नियमित रूप से अंतर्राष्ट्रीय शूटिंग प्रतियोगिता का आयोजन किया जाता है।</p><p class=\"ql-align-center\"><br></p><p><strong>एशियाई खेल</strong></p><p>एशियाई खेलों की निशानेबाजी स्पर्धाओं में भारतीय निशानेबाजों ने कई पदक जीते हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>राष्ट्रमंडल खेल</strong></p><p>राष्ट्रमंडल खेलों में निशानेबाजी में भारत ने ऐतिहासिक रूप से जोरदार प्रदर्शन किया है.</p><p class=\"ql-align-center\"><br></p><p><strong>भारत के लिए निशानेबाजी खेल का महत्व</strong></p><p>निशानेबाजी अंतरराष्ट्रीय प्रतियोगिताओं में भारत के सबसे मजबूत पदक जीतने वाले खेलों में से एक बन गई है।</p><p>खेल इसमें योगदान देता है:</p><p>• ओलंपिक पदक की सफलता</p><p>• अंतर्राष्ट्रीय खेल मान्यता</p><p>• खेलों में युवाओं की भागीदारी</p><p>• खेल अवसंरचना का विकास</p><p>• भारत में सटीक खेलों को बढ़ावा देना</p><p>लगातार अच्छे प्रदर्शन के कारण भारतीय निशानेबाज विश्व स्तर पर प्रतिस्पर्धी बनते जा रहे हैं।</p><p class=\"ql-align-center\"><br></p><p><strong>शूटिंग खेलों में कौन से कौशल महत्वपूर्ण हैं?</strong></p><p>सफल शूटिंग एथलीटों को आवश्यकता होती है:</p><p>• एकाग्रता</p><p>• हाथ-आँख समन्वय</p><p>• श्वास पर नियंत्रण</p><p>• धैर्य</p><p>• मानसिक शक्ति</p><p>• फोकस और अनुशासन</p><p>यहां तक ​​कि छोटी गलतियां भी प्रदर्शन को प्रभावित कर सकती हैं क्योंकि शूटिंग अत्यधिक सटीकता पर आधारित खेल है।</p><p class=\"ql-align-center\"><br></p><p><strong>शूटिंग खेलों के लिए सरकारी सहायता</strong></p><p>भारत सरकार विभिन्न खेल कार्यक्रमों के माध्यम से निशानेबाजी एथलीटों का समर्थन करती है।</p><p><strong>टॉप्स योजना</strong></p><p>TOPS का अर्थ है:</p><p>• लक्ष्य ओलंपिक पोडियम योजना</p><p>यह अंतरराष्ट्रीय प्रतियोगिताओं की तैयारी करने वाले विशिष्ट एथलीटों को वित्तीय और प्रशिक्षण सहायता प्रदान करता है।</p><p class=\"ql-align-center\"><br></p><p><strong>खेलो इंडिया</strong></p><p>खेलो इंडिया स्कूल और युवा स्तर पर खेल प्रतिभा विकास को बढ़ावा देता है।</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>परीक्षा के लिए महत्व</strong></p><p><strong>यूपीएससी</strong></p><p>इसके लिए महत्वपूर्ण:</p><p>• खेल और युवा मामले</p><p>• अंतर्राष्ट्रीय खेल प्रतियोगिताएँ</p><p>• सरकारी खेल योजनाएँ</p><p>• ओलंपिक खेल</p><p class=\"ql-align-center\"><br></p><p><strong>एसएससी/रेलवे/बैंकिंग</strong></p><p>महत्वपूर्ण तथ्यों में शामिल हैं:</p><p>• आईएसएसएफ का फुल फॉर्म</p><p>• अभिनव बिंद्रा की उपलब्धि</p><p>• शूटिंग इवेंट के प्रकार</p><p>• ओलंपिक शूटिंग स्पर्धाएँ</p><p>• टॉप्स योजना</p><p>• भारत की अंतर्राष्ट्रीय खेल उपलब्धियाँ</p><p><br></p><p><br></p>', 'GAMES & SPORTS', '', '', NULL, 'active', 1, '2026-05-04 12:12:00', '2026-05-13 17:46:07', '2026-05-13 17:46:07');
INSERT INTO `current_affairs` (`id`, `title_en`, `title_hi`, `short_summary_en`, `short_summary_hi`, `content_en`, `content_hi`, `category`, `tags`, `youtube_link`, `featured_image`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES
(72, ' India–France Indo-Pacific cooperation agreement discussed', '', '<h2> India–France Indo-Pacific cooperation agreement discussed</h2><p><br></p><p>• Focus on maritime security and technology collaboration.</p><p>• Strengthens strategic partnership in the Indo-Pacific region.</p>', '', '<p>India–France Indo-Pacific Cooperation Agreement Discussed</p><p><strong>What is the news about?</strong></p><p>India and France recently discussed strengthening cooperation in the Indo-Pacific region through greater strategic, maritime and technological collaboration. The discussions focused on improving maritime security, defence cooperation, technology partnership and maintaining a free, open and secure Indo-Pacific region.</p><p>Both countries emphasized the importance of strengthening their long-term strategic partnership and expanding cooperation in areas such as naval security, defence manufacturing, cyber security, space technology, clean energy and Indo-Pacific stability.</p><p>The discussions highlighted the growing importance of India–France relations in global geopolitics and regional security.</p><p class=\"ql-align-center\"><br></p><p><strong>What is the Indo-Pacific Region?</strong></p><p>The Indo-Pacific region is a large strategic and economic region that includes the Indian Ocean and the Pacific Ocean along with surrounding countries.</p><p>The region stretches from:</p><p>• eastern coast of Africa</p><p> to</p><p> • western Pacific Ocean</p><p>It includes important countries such as:</p><p>• India</p><p> • France</p><p> • Japan</p><p> • Australia</p><p> • USA</p><p> • Indonesia</p><p> • Singapore</p><p>The Indo-Pacific region is extremely important because it contains major international trade routes, sea lanes and strategic maritime zones.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is the Indo-Pacific region important?</strong></p><p>The Indo-Pacific region is important for global trade, security and economic growth.</p><p>Major reasons include:</p><p>• important sea trade routes</p><p> • energy transportation routes</p><p> • strategic military importance</p><p> • maritime security</p><p> • global supply chains</p><p> • economic cooperation</p><p>A large percentage of world trade passes through the Indo-Pacific region, making it strategically significant for many countries.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Maritime Security?</strong></p><p>Maritime security refers to protection of oceans, sea routes, ports and coastal areas from threats such as piracy, terrorism, smuggling and illegal activities.</p><p>It includes:</p><p>• naval security</p><p> • coastal surveillance</p><p> • protection of shipping routes</p><p> • anti-piracy operations</p><p> • disaster response at sea</p><p>Strong maritime security is important for protecting trade and national security.</p><p class=\"ql-align-center\"><br></p><p><strong>Why are India and France focusing on maritime security?</strong></p><p>India and France are focusing on maritime security because both countries have strategic interests in the Indian Ocean region.</p><p>The cooperation aims to:</p><p>• protect sea trade routes</p><p> • maintain regional stability</p><p> • strengthen naval cooperation</p><p> • improve surveillance systems</p><p> • counter piracy and illegal activities</p><p> • ensure freedom of navigation</p><p>France is also an important Indo-Pacific country because it has overseas territories and military presence in the Indian and Pacific Oceans.</p><p class=\"ql-align-center\"><br></p><p><strong>What is Strategic Partnership?</strong></p><p>A strategic partnership is a long-term cooperative relationship between countries based on shared political, economic, defence and security interests.</p><p>India and France share a strong strategic partnership in areas such as:</p><p>• defence cooperation</p><p> • space technology</p><p> • nuclear energy</p><p> • cyber security</p><p> • maritime security</p><p> • trade and investment</p><p>The partnership helps both countries strengthen diplomatic and military cooperation.</p><p class=\"ql-align-center\"><br></p><p><strong>India–France Defence Cooperation</strong></p><p>India and France have strong defence relations and regularly conduct military exercises and defence projects.</p><p>Important defence cooperation includes:</p><p>• Rafale fighter aircraft deal</p><p> • naval cooperation</p><p> • defence technology sharing</p><p> • joint military exercises</p><p> • submarine and aerospace collaboration</p><p>France is one of India’s key defence partners.</p><p class=\"ql-align-center\"><br></p><p><strong>Rafale Fighter Aircraft</strong></p><p>India purchased Rafale fighter jets from France to strengthen the Indian Air Force.</p><p><strong>Manufactured By</strong></p><p>• Dassault Aviation (France)</p><p><strong>Importance</strong></p><p>Rafale aircraft improve:</p><p>• air combat capability</p><p> • missile systems</p><p> • aerial defence preparedness</p><p> • operational strength of IAF</p><p class=\"ql-align-center\"><br></p><p><strong>Technology Collaboration Between India and France</strong></p><p>The discussions also focused on technology cooperation between the two countries.</p><p>Important areas include:</p><p>• artificial intelligence (AI)</p><p> • cyber security</p><p> • digital technology</p><p> • clean energy</p><p> • space research</p><p> • defence manufacturing</p><p>Technology collaboration helps improve innovation and strategic capabilities.</p><p class=\"ql-align-center\"><br></p><p><strong>Space Cooperation Between India and France</strong></p><p>India and France cooperate in space technology through:</p><p>• ISRO</p><p> • CNES (French Space Agency)</p><p>The countries work together on:</p><p>• satellite launches</p><p> • climate monitoring</p><p> • ocean observation</p><p> • space research missions</p><p class=\"ql-align-center\"><br></p><p><strong>What is Freedom of Navigation?</strong></p><p>Freedom of navigation means all countries have the right to move ships and conduct trade freely in international waters according to international law.</p><p>Many countries support a free and open Indo-Pacific region to ensure uninterrupted trade and maritime security.</p><p class=\"ql-align-center\"><br></p><p><strong>Why is India–France Indo-Pacific cooperation important?</strong></p><p>The cooperation is important because it strengthens regional security and improves strategic balance in the Indo-Pacific.</p><p>It also helps:</p><p>• maintain peace and stability</p><p> • strengthen naval security</p><p> • improve defence coordination</p><p> • support global trade routes</p><p> • increase technological cooperation</p><p> • counter regional security challenges</p><p>The partnership reflects growing geopolitical cooperation between democratic countries in the Indo-Pacific region.</p><p class=\"ql-align-center\"><br></p><p><strong>Major Military Exercises Between India and France</strong></p><p><strong>Exercise Varuna</strong></p><p>A joint naval exercise conducted by the Indian Navy and French Navy.</p><p>Focus areas include:</p><p>• maritime warfare</p><p> • naval coordination</p><p> • anti-submarine operations</p><p> • maritime surveillance</p><p class=\"ql-align-center\"><br></p><p><strong>Exercise Garuda</strong></p><p>A joint air exercise between the Indian Air Force and French Air Force.</p><p class=\"ql-align-center\"><br></p><p><strong>Exercise Shakti</strong></p><p>A joint military exercise between the armies of India and France.</p><p class=\"ql-align-center\"><br></p><p><br></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p><strong>Importance for Exams</strong></p><p><strong>UPSC</strong></p><p>Important for:</p><p>• International Relations</p><p> • Indo-Pacific Strategy</p><p> • Maritime Security</p><p> • Defence Cooperation</p><p> • India–France Relations</p><p class=\"ql-align-center\"><br></p><p><strong>SSC / Railway / Banking</strong></p><p>Important facts include:</p><p>• Indo-Pacific region meaning</p><p> • Maritime security meaning</p><p> • Rafale aircraft</p><p> • India–France military exercises</p><p> • France capital and currency</p><p> • Strategic partnership concepts</p><p><br></p><p><br></p>', '', 'MoUS & AGREEMENTS', '', '', NULL, 'active', 1, '2026-05-04 12:28:00', '2026-05-13 18:01:26', '2026-05-13 18:01:26');
